const SEEDED_BY={wheat:"grows wild in the Yard",tomatoe:"rotten tomatoes, in the Yard",rattlebean:"the Gloam",lanternroot:"the Lantern Mire",bonegourd:"the Boneyard",stormcorn:"Cloudreach &amp; the Thunderhead",goldtomatoe:"It's a secret",glassgourd:"the Carnival",emberwheat:"the Vault",starfruit:"the Trailer Park"};const growTime=ms=>{const m=Math.round(ms/6e4),h=Math.floor(m/60);return m<60?`${m} min`:`${h} hr${m%60?` ${m%60} min`:""}`};function cropTable(G,H){const nm=k=>H.esc(G.ITEMS[k]?.name||k);const areasOf=k=>Object.values(G.SCENES).filter(d=>(d.mobs||[]).some(([t])=>(G.MOBS[t]?.drops||[]).some(x=>x[0]===k))).map(d=>H.esc(d.name||"")).filter(Boolean);const rows=Object.entries(G.CROPS).sort((a,b)=>a[1].lvl-b[1].lvl).map(([k,c])=>{const out=G.cropYield(k),v=G.valueOf(out),where=SEEDED_BY[k]||(areasOf(k).join(", ")||"&mdash;");return`<tr><td>${H.ico(k)} ${nm(k)}${out!==k?` &rarr; ${H.ico(out)} ${nm(out)}`:""}</td><td>${c.lvl}</td><td>${growTime(c.ms)}</td><td>${c.yield[0]}&ndash;${c.yield[1]}</td><td>${c.xp.toLocaleString()}</td><td>${v>0?v.toLocaleString():"&mdash;"}</td><td>${where}</td></tr>`});return`<table class="tbl"><tr><th>Crop</th><th>Harvesting</th><th>Grows in</th><th>Pays back</th><th>xp</th><th>Sells</th><th>Seeded by</th></tr>${rows.join("")}</table>`}const SEEDS_NOTE=G=>`<p><b>Most crops are their own seed</b>: planting spends one of the thing you are growing, so the first of each kind has to be found. They drop from the monsters of the zone that grows them, at about <b>one kill in eighty</b>. <b>The four Wizardry flowers are the exception.</b> They grow from ${["seed_sun","seed_ember","seed_frost","seed_void"].map(k=>G.ITEMS[k]?.name).filter(Boolean).join(", ").replace(/, ([^,]*)$/," and $1")}, which drop from monsters all over the map at about <b>one kill in a hundred and twenty-five</b>, and you harvest the flower that ink is brewed from. What you can grow is decided by where you can survive.</p>`;const GUIDES=[{id:"pets",title:"Pets",icon:"🐾",cat:"Going further",body:(G,H)=>{const R=G.RANKS,rk=r=>`<b style="color:${R[r].col}">${R[r].mark?`${R[r].mark} `:""}${R[r].name}</b>`;const eggOf=Object.fromEntries(Object.entries(G.EGGS).map(([k,e])=>[e.pet,k]));const places=list=>list.map(s=>G.SCENES[s]?.name||(s==="wild"?"The Wilderness":s==="deep"?"The Deep Wild":s)).join(", ");const from=(k,p)=>{if(G.PET_DROP_KEYS.includes(k))return`Any monster, about 1 kill in ${Math.round(1/G.PET_DROP).toLocaleString()}, in: ${places([...G.PET_SCENES])}`;if(p.legend)return`Breed two Greater ${H.esc(G.PETS[p.base]?.name||p.base)} in your pet pen`;if(eggOf[k])return`Hatch a ${H.esc(G.ITEMS[eggOf[k]]?.name||eggOf[k])} in a hatchery. Eggs drop from monsters in: ${places(G.EGGS[eggOf[k]].from)}`;if(k==="coilling")return"The chest at the end of the Great Pyramid, about 1 clear in 20";if(k==="blackcat")return"The Pumpkin King, during the Long Night only, about 1 King in 40";if(k==="potboy")return"The Deepwarden, in the Depths of the Mountain, about 1 kill in 60";return"&mdash;"};const rows=Object.entries(G.PETS).filter(([k,p])=>!p.held&&(k!=="blackcat"||G.hwOn())).sort(([,a],[,b])=>(a.legend?1:0)-(b.legend?1:0)).map(([k,p])=>`<tr><td><b>${H.esc(p.name)}</b></td><td>${rk(p.legend?"legend":"ordinary")}</td><td>${H.esc(G.petFxText(p.fx))}</td><td>${from(k,p)}</td></tr>`).join("");return`<p><b>A pet follows you around and gives you a bonus while you wear it.</b> You wear one at a time, in the paw square in your <b>Equipment</b> tab. Take it off and the bonus stops.</p>
      <h3>Ranks</h3>
      <p>Every pet is ${rk("ordinary")}, ${rk("greater")} or ${rk("legend")}. The ones you find are Ordinary. Breed two Ordinary pets in a pet pen to get a Greater one: it has the two stats you pick from its parents, 25% stronger, and glows blue. Breed two Greater pets of the same kind to get that pet's Legendary: a different pet with its own powers, glowing orange. The <b>Breeding</b> guide has the details.</p>
      <h3>Every pet</h3>
      <table class="tbl"><tr><th>Pet</th><th>Rank</th><th>Gives</th><th>How to get it</th></tr>${rows}</table>
      <h3>Good to know</h3>
      <p><b>Walk speed and work speed are different.</b> Walk speed is how fast you move. Work speed is how fast you hit a monster, a rock or a tree, and how fast you fish and pick pockets.</p>
      <p><b>Speed has a limit.</b> Pets, food and gear all share the same cap, so stacking a fast pet on a fast meal won't go past it.</p>
      <p><b>Name yours whatever you like.</b> Everyone sees the name. You can also let a pet go, and that can't be undone.</p>
      <h3>Trading and selling pets</h3>
      <p>A pet keeps its rank, its stats and its name when it changes hands. There are three ways:</p>
      <ul><li><b>The trade window.</b> Your pets are listed under your bag. Click one to offer it; click it again to take it back. Up to ${G.PET_TRADE.tradeMax} a trade.</li>
      <li><b>Livia's Exchange, the Pets tab.</b> Pick a pet and a price. It leaves your pets while it is up. Anyone can buy it outright, and the money goes to your bank, less 1%. You can have ${G.PET_TRADE.exSlots} up at once, and take one down any time.</li>
      <li><b>Bom, at the Prize Counter.</b> He buys any pet: ${Object.entries(G.PET_TRADE.bom).map(([r,n])=>`${G.RANKS[r].name} ${n.toLocaleString()}`).join(", ")} tickets. Use the Sell to Bom button in your Equipment tab while you stand at his counter. Another player will usually pay more.</li></ul>
      <p>One person can keep up to ${G.PET_TRADE.own} at once.</p>`}},{id:"longnight",title:"The Long Night",icon:"🎃",cat:"Going further",body:(G,H)=>{const on=G.hwOn(),left=G.hwDaysLeft(),corn=n=>`${Number(n).toLocaleString()} candy corn`;const nm=k=>H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k)),pct=x=>`${Math.round(x*100)}%`;const K=G.MOBS.pumpkinking,night=`${G.HW.night[0]-12} to ${G.HW.night[1]-12} PM Central`;const shelf=G.HW.market.map(([k,n,c])=>`<tr><td>${H.ico(k)} ${n>1?`${n} `:""}${nm(k)}${G.ITEMS[k].slot?' <em class="qtag">Halloween 2026 Event</em>':""}</td><td>${corn(c)}</td><td>${G.ITEMS[k].slot?"keep it":"used up"}</td></tr>`).join("");const cos=Object.values(G.STORE).filter(it=>it.tab==="night"&&it.corn).map(it=>`<tr><td>${H.esc(it.name)} (a name cosmetic)</td><td>${corn(it.corn)}</td><td>keep it, worn from the Store's Name tab</td></tr>`).join("");const fits=Object.values(G.VANITY_SETS).filter(v=>v.corn).map(v=>{const pieces2=Object.values(G.VANITY).filter(p=>p.set===Object.keys(G.VANITY_SETS).find(k=>G.VANITY_SETS[k]===v));return`<tr><td>The ${H.esc(v.name)} fit, ${pieces2.length} pieces</td><td>${corn(pieces2[0]?.corn||0)} a piece</td><td>keep it, coloured at Ronde's</td></tr>`}).join("");const pieces=[["gallows_bow","one chop in 10,000"],["coffin_ring","one swing at a rock in 10,000"],["drowned_boots","one cast in 10,000"],["lantern_quiver","the King (2%), or Hexa"],["skull_wand","the King (2%), or Hexa"],["bag_shroud","the King (2%), or Hexa"],["reaper_scythe","the King (1%), or 1 in 3,000 off any level 80+ monster"],["king_crown","the King (1%), or 1 in 3,000 off any level 80+ monster"],["ferry_coin","the King (1%), or 1 in 3,000 off any level 80+ monster"]].map(([k,from])=>{const it=G.ITEMS[k];return`<tr><td>${H.ico(k)} ${nm(k)}${it.legend?" <b>legendary</b>":""}</td><td>${H.esc(G.SKILLS[it.req.skill].name)} ${it.req.lvl}</td><td>${H.esc(G.fxText(it.fx))}${it.pouch?`; holds ${it.pouch.cap.toLocaleString()} ${it.pouch.ammo==="page"?"pages":"arrows"}`:""}</td><td>${from}</td></tr>`}).join("");const quests=[["hw_lights","Lights Out","Mudge the Lamplighter, the Lantern Mire","easy"],["hw_vigil","The Sister's Vigil","Sister Morrow, the Boneyard","medium"],["hw_king","The Pumpkin King","Hexa, the Yard","hard"]].map(([k,t,who,tier])=>`<tr><td>${H.wl(`quests/${k}`,t)}</td><td>${who}</td><td>${tier}</td><td>${H.esc(G.QUESTS[k].reward.text)}</td></tr>`).join("");return`<div class="wnote" style="border-color:#c8641e;background:rgba(200,100,30,.12)"><b>🎃 ${on?`The Long Night is on: ${left} day${left===1?"":"s"} left.`:"The Long Night is not on."}</b> It ends on the morning of <b>November 2nd</b>. Everything seasonal goes then: the tent, the King, the lanterns and every candy corn you have not spent. Everything you have <b>bought or found</b> stays yours for good.</div>
      <p class="lede">EastScape's Halloween, ${G.HW.from.slice(5).replace("-","/")} to ${G.HW.until.slice(5).replace("-","/")}. A month with its own coin, its own boss, its own shop, nine pieces of gear that exist nowhere else, and a hiscore board. Nothing in it touches tickets: what you earn and spend here is candy corn, and only candy corn.</p>

      <h3>1. What is on</h3>
      <ul>
        <li><b>Candy corn</b> drops from everything you kill and gather. It is the only thing the Night Market takes.</li>
        <li><b>Hexa the Candy Witch</b> keeps the Night Market, a tent in the Yard west of the north road.</li>
        <li><b>The Pumpkin King</b> rises once an hour in the Lantern Mire.</li>
        <li><b>Nightfall</b>, ${night} every evening: the world goes dark and every candy corn drop doubles.</li>
        <li><b>The Ghost Hunt</b>: ${G.HW.lanterns} ghost lanterns a day, hidden on the open maps, ${G.HW.lanternCorn} corn each.</li>
        <li><b>Trick or treat</b>, once a day, said to anyone.</li>
        <li><b>Three quests</b>, one per difficulty, ending in the King himself.</li>
        <li><b>Nine event pieces</b> of gear, all of them very rare drops.</li>
        <li>A <b>Candy corn</b> board on the Hiscores for the month.</li>
      </ul>

      <h3>2. How candy corn is earned</h3>
      <table class="tbl"><tr><th>Source</th><th>Pays</th><th>How often</th></tr>
        <tr><td>Any kill</td><td>${G.HW.corn.n[0]}&ndash;${G.HW.corn.n[1]}</td><td>${pct(G.HW.corn.kill)} of kills</td></tr>
        <tr><td>Any catch, cut or dig</td><td>${G.HW.corn.n[0]}&ndash;${G.HW.corn.n[1]}</td><td>${pct(G.HW.corn.gather)} of gathers</td></tr>
        <tr><td>A ghost lantern</td><td>${G.HW.lanternCorn}</td><td>${G.HW.lanterns} a day, each once, new places every morning</td></tr>
        <tr><td>Trick or treat (a treat)</td><td>${G.HW.trick.corn[0]}&ndash;${G.HW.trick.corn[1]}, or seeds, or a pie</td><td>once a day; ${pct(G.HW.trick.trickAt)} of the time it is a trick instead</td></tr>
        <tr><td>The Pumpkin King</td><td>${K.drops.find(([k])=>k==="candycorn")[1][0]}&ndash;${K.drops.find(([k])=>k==="candycorn")[1][1]}</td><td>every kill, once an hour</td></tr>
        <tr><td>The three quests</td><td>${["hw_lights","hw_vigil","hw_king"].map(k=>G.QUESTS[k].reward.items.find(([i])=>i==="candycorn")[1]).join(" + ")}</td><td>once</td></tr>
        <tr><td><b>Nightfall</b></td><td colspan="2">every drop above is <b>doubled</b> from ${night}</td></tr>
      </table>
      <p>An ordinary evening comes to about 150&ndash;250 corn; a hard one about 500. It expires: on November 2nd whatever is in your bag or bank turns to sugar, so spend it.</p>

      <h3>3. What candy corn buys</h3>
      <p>All of it at <b>the Night Market</b>, Hexa's tent in the Yard. The fits can also be bought from Ronde. Nothing here is ever sold for tickets. <b>Every event item can be traded to another player and listed on Livia's Exchange</b>; Bom will take any of them for <b>1 ticket</b>, and nothing more.</p>
      <table class="tbl"><tr><th>Item</th><th>Price</th><th>After the event</th></tr>${shelf}
        <tr><td>🐈‍⬛ The Black Cat (a pet)</td><td>${corn(G.HW.pet[1])}</td><td>keep it</td></tr>${cos}${fits}
        <tr><td>Reforging any Hallowed or event piece, per level</td><td>${corn(G.forgeCost("hallowed_helm")[1])} (a legendary ${corn(G.forgeCost("reaper_scythe")[1])})</td><td>the level stays; the corn does not</td></tr>
      </table>
      <p><b>Priced against a month.</b> A pie is a few kills. A fit is about a fortnight of play. The Hallowed set is the month if you grind for it, and the Pumpkin King drops every piece of it too, so the shelf is the slow certain road and the Mire the fast lucky one. The Black Cat is every corn a serious player will see before November; the King drops it one time in forty.</p>

      <h3>4. The Pumpkin King</h3>
      <p>Once an hour he climbs out of the clearing in the <b>Lantern Mire</b>; chat says when, and <b>typing /pumpkin in chat</b> tells you (and only you) how long until he rises, or how long he has left and how much health. He stands ${Math.round(G.HW.king.stays/6e4)} minutes and sinks back. Level ${K.lvl}, ${K.hp} hitpoints, hits up to ${K.max}, attacks on sight, <b>weak to fire and sun</b>, and he hits half again as hard once he is under ${pct(K.enrage.at)}. He takes a crowd: three players need about ten minutes, and one player alone will not finish him inside the twenty he stands. Every point of damage pays combat xp, so a long fight is a rich one. Everyone who does at least ${Math.round(G.OPEN_SHARE*100)}% of his health gets their own drops and quest credit, however many of you there are.</p>
      <p>Every kill drops candy corn and ectoplasm. He also drops the Hallowed helm, cuirass and greaves, the Lantern Quiver, Skull Wand and Shroud Satchel, all three legendaries, and one King in forty has the Black Cat at his heel.</p>

      <h3>5. The nine pieces</h3>
      <p>Every one carries the <b>Halloween 2026 Event</b> tag, glows orange in your bag, is yours to keep, and reforges with candy corn instead of bars. Their numbers sit at their level's tier; the effect is the reason to want one.</p>
      <table class="tbl"><tr><th>Piece</th><th>Needs</th><th>Does</th><th>From</th></tr>${pieces}</table>
      <p>The bow, the ring and the boots never sit on a shelf: one chop, one swing, one cast in ten thousand, during the event only. The three legendaries fall from the King one time in a hundred, and one in three thousand from anything of level 80 or more killed while the event is on.</p>

      <h3>6. The Ghost Hunt, Nightfall, trick or treat</h3>
      <p><b>Lanterns.</b> ${G.HW.lanterns} ghost lanterns stand somewhere on the nine open maps each day, about one a map, moved every morning. Click one for ${G.HW.lanternCorn} corn (${G.HW.lanternCorn*2} at Nightfall), once each a day. All ten is ${G.HW.lanterns*G.HW.lanternCorn} corn.</p>
      <p><b>Nightfall.</b> ${night}, every evening. The maps go dark (the Yard stays dark all month, for the look; its corn doubles only in the hour like everywhere else), the jack-o'-lanterns light the paths, and every candy corn drop is doubled until the hour is out. The wallet chip counts down to it.</p>
      <p><b>Trick or treat.</b> Once a day, say it to any person in the game. ${pct(1-G.HW.trick.trickAt)} of the time it is a treat: a handful of corn, two pumpkin seeds, or a warm pie. The rest is a trick, and a trick can cost you five corn, drop a spider in your bag, or put you in the Boneyard.</p>

      <h3>7. Pumpkins, pie and the brew</h3>
      <p>Pumpkin seeds plant on your island at <b>Harvesting ${G.CROPS.seed_pumpkin.lvl}</b>, ripe in ${Math.round(G.CROPS.seed_pumpkin.ms/6e4)} minutes, ${G.CROPS.seed_pumpkin.yield[0]}&ndash;${G.CROPS.seed_pumpkin.yield[1]} pumpkins a plot, two seeds back every time and a third one in ten. A pumpkin bakes into a ${nm("pumpkinpie")} on any fire at Cooking ${G.RECIPES.cook_pumpkin.lvl}: heals ${G.ITEMS.pumpkinpie.heal} and, for ${G.ITEMS.pumpkinpie.meal.mins} minutes outside, rare drops come ${pct(G.ITEMS.pumpkinpie.meal.fx.rare)} easier and kills pay ${pct(G.ITEMS.pumpkinpie.meal.fx.tix)} more. Not xp: nothing in EastScape buys xp.</p>
      <p>${nm("ectoplasm")} falls off one kill in ${Math.round(1/G.HW.ecto)} during the event. Two of it, a pumpkin and a medium vial brew a ${nm("pot_witch")} at the cauldron (Alchemy ${G.RECIPES.brew_witch.lvl}): drink it and your next death costs no hospital bill.</p>

      <h3>8. The quests</h3>
      <table class="tbl"><tr><th>Quest</th><th>Who</th><th>Tier</th><th>Pays</th></tr>${quests}</table>
      <p>They are a chain, in that order. The last one hands you the Hallowed helm outright.</p>

      <h3>9. What leaves and what stays</h3>
      <table class="tbl"><tr><th>Goes on November 2nd</th><th>Stays for good</th></tr>
        <tr><td>Hexa and the Night Market</td><td>Every piece of gear you found or bought</td></tr>
        <tr><td>The Pumpkin King, the lanterns, Nightfall, trick or treat</td><td>The Black Cat, the fits, the Pumpkin name and the Ember frame</td></tr>
        <tr><td>Every unspent candy corn</td><td>Pumpkins, pies and brews already in your bag</td></tr>
        <tr><td>The Candy corn board</td><td>Your quest rewards and your place on the other boards</td></tr>
      </table>
      <p>The Night Market says how many days are left at the top of its window, so does your candy corn chip, and the last week turns both red. Spend the corn.</p>`}},{id:"trailer",title:"The Trailer Park",icon:"🚚",cat:"Going further",body:`<p><b>North off the Thunderhead.</b> The road west ends at the Vault; this is the turning before it, and the two are the top of the game side by side rather than one after the other.</p>
      <p><b>Combat 80</b> to start a fight here, <b>Fishing 80</b> for the black water. Everything in it bites.</p>
      <table class="tbl"><tr><th>Who</th><th>Level</th></tr>
        <tr><td>Junkyard Dog</td><td>80</td></tr><tr><td>Rabid Possum</td><td>84</td></tr>
        <tr><td>The Scrapper</td><td>88</td></tr><tr><td>Yard Gator</td><td>92</td></tr>
        <tr><td><b>The Junk King</b></td><td><b>98</b></td></tr>
      </table>
      <p><b>The King</b> stands in the fenced yard at the east end. He has more than twice the hitpoints of anything else in the game and he is the only thing that drops <b>his cap</b> or <b>his wrench</b>. He is meant to be killed many times over.</p>
      <p><b>The richest gathering there is</b>, and all of it wants a top-rung tool:</p>
      <table class="tbl"><tr><th>What</th><th>Needs</th></tr>
        <tr><td>Truck on blocks — catalytic converter</td><td>Mining 65, Starfall pickaxe</td></tr>
        <tr><td>Slag bank — slagstone</td><td>Mining 85, Eclipse pickaxe</td></tr>
        <tr><td>Rustpine</td><td>Woodcutting 65, Starfall axe</td></tr>
        <tr><td>Bogwood</td><td>Woodcutting 80, Eclipse axe</td></tr>
        <tr><td>Black water — mud cat and bowfin</td><td>Fishing 80, Eclipse rod</td></tr>
      </table>
      <p>Cook the fish and they are the best food this side of the <a data-wiki="areas/deep">Deep Wild</a>, whose Black Pool holds the two that beat them. Until this zone there was nothing above Vaultwood to cut and nothing above the Vault to mine, so the top of the <a data-wiki="guides/tools">tool ladder</a> had nothing to work on; the Deep's Gallows oak (Woodcutting 90) is the one tree past it.</p>`},{id:"alchemy",title:"Alchemy: sand into potions",icon:"🧪",cat:"Skills",body:`<p><b>Alchemy runs 1 to 100 and it starts with sand.</b> Dig it out of the pits in <a data-wiki="guides/sands">The Golden Sands</a> at <b>Mining 20</b>, melt it to glass at the <b>cauldron</b> under the temple colonnade, then brew the glass with whatever the world drops.</p>
      <p><b>One cauldron does both jobs.</b> It is the only one in the game, and it both blows the vials and brews the potions &mdash; so everything to do with Alchemy happens on one tile, and you never need a single level of Smithing to train it.</p>
      <h4>It can go wrong</h4>
      <p><b>Nothing here is a certainty.</b> A recipe spoils about <b>half</b> the time at the level that unlocks it and settles down as you climb past it &mdash; but it never reaches nothing. Glasswork bottoms out around <b>one batch in fifty</b>, for ever. A spoiled batch leaves nothing behind.</p>
      <h4>The vial is the tier, and the timer</h4>
      <table class="tbl"><tr><th>Vial</th><th>Alchemy</th><th>Sand</th><th>Holds</th></tr>
        <tr><td><b>Small vial</b></td><td>1</td><td>1</td><td>10 minutes</td></tr>
        <tr><td><b>Medium vial</b></td><td>34</td><td>2</td><td>15 minutes</td></tr>
        <tr><td><b>Large flask</b></td><td>68</td><td>4</td><td>20 minutes</td></tr>
      </table>
      <p>So a potion's strength and how long it lasts are both written on the bottle. There is nothing else to learn about the ladder.</p>
      <h4>The ingredients are things you already throw away</h4>
      <p>This is the point of the skill. <b>Six of the seven farm crops</b> go in a potion and had no other use at all; so do <b>staticfur</b> off a Thunderwolf, a <b>marked card</b> off a Card Counter, a <b>receipt</b> off a Tax Wraith, a <b>shark tooth</b>, a <b>cobweb</b>, a <b>sporecap</b>, a <b>husk</b>, <b>bones</b> and <b>stormjelly</b>. Two are native to the Sands: a <b>scarab shell</b> and a <b>cobra fang</b>.</p>
      <h4>Every potion, in order</h4>
      <p>The ladder <b>alternates a skilling buff with a combat one</b> all the way up, so whichever sort of player you are there is never a dead stretch. <b>"Bite" is fishing</b> &mdash; it is how readily a fish takes the hook, not how hard you hit.</p>
      <table class="tbl"><tr><th>Alch</th><th>Potion</th><th>Does</th><th>Needs</th></tr>
        <tr><td>1</td><td><b>Swift draught</b></td><td>skilling: +4% speed</td><td>small vial, 2 sporecap</td></tr>
        <tr><td>10</td><td><b>Hide tonic</b></td><td>combat: +5% tough</td><td>small vial, 2 hide</td></tr>
        <tr><td>19</td><td><b>Keen-eye water</b></td><td>skilling: +6% rare</td><td>small vial, 2 wheat, sporecap</td></tr>
        <tr><td>23</td><td><b>Salt salve</b></td><td>heals 14 at once</td><td>small vial, 2 lanternroot</td></tr>
        <tr><td>28</td><td><b>Rattle brew</b></td><td>fishing: fish bite 2% more often</td><td>small vial, 2 rattlebean</td></tr>
        <tr><td>36</td><td><b>Quickhand philtre</b></td><td>skilling: +7% speed</td><td>medium vial, marked card, lanternroot</td></tr>
        <tr><td>45</td><td><b>Gourd draught</b></td><td>combat: +9% tough</td><td>medium vial, 2 bonegourd, bones</td></tr>
        <tr><td>50</td><td><b>Field salve</b></td><td>heals 26 at once</td><td>medium vial, 3 lanternroot, bonegourd</td></tr>
        <tr><td>54</td><td><b>Ghost grease</b></td><td>skilling: +5% steal</td><td>medium vial, cobweb, husk</td></tr>
        <tr><td>62</td><td><b>Tax-dodger's tincture</b></td><td>combat: +9% tickets</td><td>medium vial, receipt, stormcorn</td></tr>
        <tr><td>70</td><td><b>Prospector's flask</b></td><td>skilling: +14% rare</td><td>large flask, gold tomato, marked card, scarab shell</td></tr>
        <tr><td>78</td><td><b>Fang flask</b></td><td>fishing: fish bite 4.5% more often</td><td>large flask, shark tooth, cobra fang, rattlebean</td></tr>
        <tr><td>84</td><td><b>Royal salve</b></td><td>heals 44 at once</td><td>large flask, 4 lanternroot, scarab shell</td></tr>
        <tr><td>90</td><td><b>Storm flask</b></td><td>skilling: +12% speed</td><td>large flask, staticfur, stormjelly, lanternroot</td></tr>
        <tr><td>100</td><td><b>Pharaoh's draught</b></td><td>combat: +18% tough; fishing: +3% bite</td><td>large flask, 2 scarab shell, cobra fang, gold tomato</td></tr>
      </table>
      <p><b>A potion stacks with your gear.</b> Every number above sits well under the ceiling the game caps each effect at, so drinking one adds to what you are wearing instead of replacing it.</p>
      <p><b>They only work outside.</b> Like the bar's food and drink, a buff counts down in places that have monsters in them, not on the casino floor.</p>`},{id:"sands",title:"The Golden Sands",icon:"🏜️",cat:"Going further",body:`<p><b>Combat 40 to 49, west out of <a data-wiki="guides/road">the Boneyard</a></b> &mdash; and it is a <b>second route, not a rung</b>. At Combat 40 you may go north to Cloudreach or west to here, and each has its own ore, tree and fish. Neither is ahead of the other.</p>
      <p>It is where <a data-wiki="guides/alchemy">Alchemy</a> lives. The <b>sand pits</b> are the front of that whole chain, and the game's only <b>cauldron</b> stands under the temple colonnade in the middle of the map.</p>
      <table class="tbl"><tr><th>What</th><th>Needs</th><th>Gives</th></tr>
        <tr><td><b>Sand pits</b> (five of them)</td><td>Mining 20</td><td>sand &mdash; 45 xp</td></tr>
        <tr><td><b>Stardust seams</b></td><td>Mining 50</td><td>stardust &mdash; 150 xp</td></tr>
        <tr><td><b>Date palms</b></td><td>Woodcutting 45</td><td>palm logs &mdash; 190 xp</td></tr>
        <tr><td><b>The oasis</b></td><td>Fishing 40 / 48</td><td>oasis perch, temple carp</td></tr>
      </table>
      <p><b>Sand is Mining 20 on purpose</b>, far below the map's own band: the barrier is meant to be <i>getting here</i>, not a second grind once you have. And <b>stardust had exactly one rock in the whole game</b> before this map &mdash; there are two more here.</p>
      <h4>What lives there</h4>
      <p><b>Sand Cobras</b> (41) in the dunes and <b>Gilt Scarabs</b> (45) round the pits &mdash; the cobra drops the <b>fang</b> and the scarab the <b>shell</b>, both of which go in the best potions. <b>Bandaged Debtors</b> (43) shuffle about the precinct and <b>Tomb Jackals</b> (47) hold the pyramid. Everything waits to be hit first except <b>one jackal by the pyramid door</b>, which comes at you on sight.</p>
      <h4>The Great Pyramid</h4>
      <p>It stands on the eastern skyline and <b>the tomb door is sealed</b>. The party fight behind it is still being built &mdash; when it opens it will work like <a data-wiki="guides/crypt">the Crypt</a>: a private copy of the tomb for your group, an ante each, and something very old at the bottom of it.</p>`},{id:"tools",title:"Tools: the grade ladder",icon:"⛏️",cat:"Skills",body:(G,H)=>{const rungs=G.TOOL_RUNGS.map((r,i)=>({...r,upTo:G.TOOL_RUNGS[i+1]?G.TOOL_RUNGS[i+1].gate-1:null,spd:G.ITEMS[`${r.key}_pickaxe`]?.tspd,price:(G.SHOP.sells.find(([k])=>k===`${r.key}_pickaxe`)||[])[1]}));const names=rungs.map(r=>r.name.toLowerCase());const cheap=rungs.filter(r=>r.price&&r.price<1e4).length;return`<p>A <b>pickaxe</b>, an <b>axe</b> and a <b>fishing rod</b> come in ${names.length} grades, the same ${names.length} as the armour: ${names.join(", ")}.</p>
      <p><b>The rock decides.</b> Whatever you are mining, cutting or fishing asks for a tool of its own grade or better &mdash; emerald ore wants an emerald pickaxe, and a bronze one will not touch it. The grade a thing wants is always the grade named on the thing itself, so if you can work it at all, the right tool is one you can hold.</p>
      <table class="tbl"><tr><th>Tool</th><th>Works up to</th><th>Speed</th><th>At the counter</th></tr>
        ${rungs.map(r=>`<tr><td>${H.ico(`${r.key}_pickaxe`)} <b>${H.esc(r.name)}</b></td><td>${r.upTo?`level ${r.upTo}`:"anything"}</td><td>${r.spd?`+${Math.round((r.spd-1)*100)}%`:"&mdash;"}</td><td>${r.price?r.price.toLocaleString():"&mdash;"}</td></tr>`).join("")}
      </table>
      <p>A better tool is also <b>quicker at everything below it</b>, so it is never wasted on easy work.</p>
      <p><b>Two ways to get one.</b> Buy it at the <a data-wiki="npcs/Bom Trady">Prize Counter</a> &mdash; the first ${cheap} are cheap for their grade on purpose, and the top two are not &mdash; or <b>smith it</b>: two bars for a pickaxe or an axe, one for a rod, at the anvil.</p>
      <p><b>The top rungs gate above their own ore.</b> A ${H.esc(rungs.at(-2).name)} rock is worked with the tool below it, so a new grade never quietly raises the bar on rocks you were already mining, and you are never asked for a pickaxe you can only make from ore that pickaxe is needed for.</p>
      <p><b>You have to be holding it.</b> Pickaxe, axe or rod, it goes in the weapon slot &mdash; one in your bag will not do. That is the whole cost of the ladder: while you are working you are not carrying a sword.</p>`}},{id:"start",title:"Start here",icon:"🧭",cat:"Starting out",body:`<p><b>This is a casino with a world attached.</b> The tables are the point; everything outside exists to pay for them.</p>
      <h3>The first five minutes</h3>
      <p><b>Play a table.</b> You start with enough to play. Every game takes tickets or real ZCoins &mdash; the window has a toggle, and the odds are identical either way.</p>
      <p><b>When you run out, go outside.</b> Walk out of the casino into the Yard. Hit something, chop something, or fish. Take what you find to <a data-wiki="npcs/Bom Trady">Bom Trady</a> in the middle of the floor and it becomes tickets.</p>
      <p><b>Cook your fish before you sell it.</b> Raw fish is worth nothing and Bom will not take it &mdash; the campfire is by the casino door, and cooking roughly doubles what a fish is worth.</p>
      <h3>Then what</h3>
      <p><b>Check the task board</b> inside the casino: three <a data-wiki="guides/jobs">jobs a day</a>, usually things you were going to do anyway.</p>
      <p><b>Buy a better tool before better gear.</b> <a data-wiki="guides/tools">Tools</a> decide what you can gather at all, and a grade up is 8% off every swing forever.</p>
      <p><b>Walk north when the Yard gets easy.</b> The world is a chain of areas about ten levels apart &mdash; see <a data-wiki="guides/road">The road out</a>.</p>
      <h3>Worth knowing early</h3>
      <p><b>Nothing is locked.</b> You can walk anywhere at level one, and die there.</p>
      <p><b>Dying does not cost you your gear</b>, only some of the tickets in your pocket. Bank them before a long trip.</p>
      <p><b>Press H</b> to open this wiki at any time.</p>`},{id:"keys",title:"Keybinds",icon:"⌨️",cat:"Starting out",body:`<p><b>Every key, in one place.</b> None of them fire while you are typing in a box (chat, a search, a name), or while Ctrl, Alt or Cmd is held, so they never get in the way of the browser's own shortcuts.</p>
      <h3>Moving and fighting</h3><table class="tbl"><tr><th>Key</th><th>Does</th></tr>
      <tr><td><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> or the arrow keys</td><td>Walk. Holding a key keeps walking. A click on the ground or on anything walks you there and does it.</td></tr>
      <tr><td><kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> <kbd>4</kbd></td><td>Use your quick slots, the four squares beside the Chat button: a potion, food, a buff, arrows, or a piece of gear (press again to take it off). <b>Press and hold</b> a slot, or right-click it, to change what is in it.</td></tr>
      <tr><td><kbd>E</kbd></td><td>Eat the best <b>cooked</b> food in your bag, whatever heals most. It never touches potions, drinks, buff meals or smoked fish, and does nothing at full health.</td></tr>
      </table>
      <h3>Windows</h3><table class="tbl"><tr><th>Key</th><th>Does</th></tr>
      <tr><td><kbd>T</kbd></td><td>Open or close the chat.</td></tr>
      <tr><td><kbd>Enter</kbd></td><td>Open the chat with the cursor in the box; Enter again sends.</td></tr>
      <tr><td><kbd>G</kbd></td><td>The games: every table in the casino, in one list.</td></tr>
      <tr><td><kbd>Y</kbd></td><td>Achievements.</td></tr>
      <tr><td><kbd>H</kbd> or <kbd>?</kbd></td><td>This wiki.</td></tr>
      <tr><td><kbd>M</kbd></td><td>Mute or unmute every sound, the jukebox included.</td></tr>
      <tr><td><kbd>N</kbd></td><td>The connection panel: your ping, for when something feels laggy.</td></tr>
      <tr><td><kbd>Esc</kbd></td><td>Close whatever is open: a window, a conversation, the item info box, or the chat box.</td></tr>
      </table>
      <h3>Talking to people</h3><table class="tbl"><tr><th>Key</th><th>Does</th></tr>
      <tr><td><kbd>1</kbd> to <kbd>9</kbd></td><td>Pick that answer. While somebody is talking to you the number keys answer them and <b>do not</b> use your quick slots.</td></tr>
      <tr><td><kbd>Space</kbd></td><td>Carry on, when there is only one answer.</td></tr>
      </table>
      <h3>With the mouse</h3><table class="tbl"><tr><th>Do this</th><th>To</th></tr>
      <tr><td>Shift-click in your bag</td><td>Drop it (it asks first, unless you turned that off in Settings).</td></tr>
      <tr><td>Right-click any item</td><td>Open its page in this wiki.</td></tr>
      <tr><td>Shift-click in the bank</td><td>Take out a full stack, or put in every one you carry.</td></tr>
      <tr><td>Shift-click in a trade</td><td>Offer the whole stack.</td></tr>
      </table>`},{id:"casino",title:"The casino",icon:"🎰",cat:"Starting out",body:`<p><b>Eight tables, and every one of them plays for tickets or for real ZCoins.</b> Same game, same odds, same server roll &mdash; the only difference is what you put in. The window has a toggle.</p>
      <table class="tbl"><tr><th>Table</th><th>How it goes</th></tr>
        <tr><td>&#127920; Slots</td><td>Three of a kind pays; two cherries pay 1.4&times;. Three sevens takes the jackpot</td></tr>
        <tr><td>&#129689; Coin Flip</td><td>Heads or tails, pays 1.95&times;</td></tr>
        <tr><td>&#127922; Dice</td><td>Roll under your number. The lower you call it, the more it pays</td></tr>
        <tr><td>&#127905; Wheel</td><td>Red or black pays 1.97&times;. The thin gold sliver pays 58&times;</td></tr>
        <tr><td>&#127183; Higher or Lower</td><td>Every right call multiplies your stake; cash out whenever. A tie is a push</td></tr>
        <tr><td>&#128163; Mines</td><td>25 tiles, some are bombs. Every gem multiplies; cash out before you find one</td></tr>
        <tr><td>&#128992; Plinko</td><td>Twelve rows of pegs. The edges pay 25&times;</td></tr>
        <tr><td>&#127903;&#65039; Scratch-Off</td><td>Nine boxes; three of a kind wins that symbol's prize</td></tr>
      </table>
      <p><b>The odds are not a secret and they are not fixed per game.</b> Every play draws its own house edge inside a narrow band, sealed behind a committed hash before your stake is taken and revealed when the play is over. No table is a better bet than another &mdash; that is deliberate, because a game that pays better than the rest is one people would only play.</p>
      <p><b>Limits.</b> Minimum 10 a bet, and a short pause between bets so nothing can be machine-gunned. The ZCoin side carries the same hourly limits the site's own floor has always had.</p>
      <p><b>Wins get announced.</b> Anything from 5&times; tells the room; 25&times; and up tells everyone in the game.</p>
      <p>Broke? <b>Go outside.</b> Hit something or fish, and take what you find to <a data-wiki="npcs/Bom Trady">Bom Trady</a>. See <a data-wiki="guides/tickets">Tickets</a>.</p>`},{id:"tickets",title:"Tickets and the Prize Counter",icon:"🎫",cat:"Starting out",body:`<p><b>Tickets are the money and Bom Trady is the whole economy.</b> He stands in the middle of the casino floor. Everything you find outside becomes tickets at his counter, and everything you want comes back over it.</p>
      <p><b>He buys loot and things you made</b> &mdash; ore, bars, logs, cooked fish, monster drops. He does <b>not</b> buy raw fish, so cook it first, and he leaves your tools, charms and anything wearable alone so you cannot cash in the set you are standing in by accident.</p>
      <p><b>He sells</b> tools, bronze gear, food, drinks and your bag upgrades. Your <a data-wiki="guides/vip">VIP rank</a> is a standing discount on all of it.</p>
      <p><b>Tickets stay on you.</b> They cannot be banked, dropped or given away in a trade &mdash; they only leave by being spent. What a death costs you is a share of the tickets in your pocket, which is the argument for spending them before a long trip out.</p>
      <p><b>Real ZCoins are a different thing entirely.</b> Find one and the counter puts it straight onto your balance on the site. There is no exchange rate in either direction: you cannot buy ZCoins with tickets and you cannot turn ZCoins into tickets. That wall is deliberate &mdash; without it, fishing would print real currency.</p>
      <p>Other players are usually the better price for anything rare. See <a data-wiki="guides/trading">Trading and the Market</a>.</p>`},{id:"road",title:"The road out",icon:"🗺️",cat:"Starting out",body:(G,H)=>{const ORDER=["workyard","gloam","mire","boneyard","orchard","cloud","frozen","frostspire","sands","thunderhead","carnival","boardwalk","bw_cabin","bw_light","bw_wreck","bw_pier","bw_skull","foundry","fd_grove","fd_maze","fd_isle","fd_chain","fd_gate","fd_hall","vault","depths","trailer","valley","valley_ridge","valley_lair","wild","deep"].filter(k=>G.SCENES[k]&&!G.SCENES[k].wikiHide);const NOTE={workyard:"the casino, the bank, the campfire, the furnace and anvil, sardines",gloam:"emerald and diamond ore, gloomwillow, trout and catfish",mire:"lanternfish, mudskipper, the first real gear drops",boneyard:"bonefish, ghost carp, the Crypt &mdash; and <b>pets start dropping here</b>",cloud:"dragonstone and onyx ore, skyash, sky eel and cloud ray",frozen:"north of Cloudreach, and a mage's country (Combat 100, or Magic 60 with a wand): yetis and snow owls on shelves and ice floes only a spell or an arrow reaches, frost wolves and wraiths on the snow, glacite (Mining 94), frostpine (Woodcutting 94), icefin through the ice (Fishing 94), and the Ice Wyrm, which comes up through the lake once a day",frostspire:"north of the Frozen Reach: Frost Giants on the shelves, Ice Elementals on the tarn's floes, Frost Wraiths, and the Frost Jarl on the high ice shelf, an open-world boss only spells reach",sands:'sand for <a data-wiki="guides/alchemy">Alchemy</a>, the cauldron, the Great Pyramid',thunderhead:"storm marlin, thunder squid, the way to the last two",carnival:"the games, the duck pond, goldfish and koi",vault:"end-game fighting, and the only <b>nova</b> and <b>singularity</b> ore in the game",boardwalk:"a drowned seaside market west of the Carnival: mackerel, bluefin and swordfish off the piers, the Chip Shop, gulls and Kraken Arms that only a bow or a wand reaches, and Captain Claw at the bottom of the strand",orchard:"the country south of the Boneyard: a market wagon under the big trees, pines (Woodcutting 52) and walnuts (66), Pomona's stove, wasps over the pond, and across the brook's stone bridge an orc camp behind a fence, its wood below it, and the Gardener at the bottom of it",bw_cabin:"the Boardwalk's second island: a cabin, palms, starfall rocks and mackerel",bw_light:"a lighthouse on its own island: starfall and eclipse rocks, bluefin, Clawhands on the sand",bw_wreck:"a ship broken in two on a sandbar: eclipse rocks, swordfish, and Kraken Arms in the shallows",bw_pier:"the pirates' house and a boathouse out on the pier: nova rocks, bluefin and swordfish",bw_skull:"the last island: the skull in the rock, nova rocks, Captain Claw, and the chest he sits on, which opens for everyone who put him down",foundry:"the Works, the Foundry's way in, south of the Thunderhead: Basalt the foreman (he buys the imps' tallies), the blast furnace (every furnace recipe, half as much xp again, and a slag batch that makes a third bar), Eclipse veins, Slag Golems, and a field of bone spikes that go off on their own",fd_grove:"west of the Works: a dead tree, pools that pulse like something breathing, Eclipse veins, golems and an imp, and ground that catches fire",fd_maze:"south of the Works: paths over the lava with the tower at the bottom and a lavafall, Nova veins, imps, the spitfire in the middle of the floor, and the portal to the Floating Isle",fd_isle:"through the Lava Maze's portal: an island of rock on chains over the lava, the crusher on its pentagram, a Singularity vein and a Nova vein, Cinder Elementals",fd_chain:"south of the Lava Maze: a rock hung on chains over the lava, walked across on the chains themselves, a Singularity vein, a geyser, Cinder Elementals",fd_gate:"south of the Chained Rock: a causeway over the lava to the burning door in the castle wall, and a tiny volcano that throws lava balls at it",fd_hall:"through the burning door: the wall of bodies, two towers with an eye on each, and Old Bessemer, the giant, up to his chest in it",depths:"ledges over a bottomless drop: monsters that shrug off a whole fighting style, abyss crystal, eclipse and nova ore, and the Deepwarden",trailer:"the best gathering in the game, and the meanest neighbours",valley:"north of the Trailer Park, and a bow's country (Combat 90, or Archery 40 with a bow): cavemen and pterodactyls on ledges only an arrow reaches, sabretooths on the road, woolly mammoths on the plateaus, coelacanth in the lake (Fishing 92), cycads (Woodcutting 92), and the Mammoth Matriarch, an open-world boss up on the great plateau",valley_ridge:"north of the Lowlands: plateau after plateau with Caveman Hunters and Elder Pterodactyls on top, raptors on the ground, fossil rocks (Mining 92)",valley_lair:"the end of the valley: the dragon fossil, a volcano, tar horrors in the tar pits, and Old Rex on his throne up on the high plateau, an open-world boss only arrows reach",wild:"the road past the Yard's east gate: nodes far apart, most things attack first, and the first of three monsters found nowhere else",deep:"the far end of the Wilderness: the Black Pool (Fishing 92 and 97), the Gallows oak (Woodcutting 90), the Grim Liches, the Nexus"};const rows=ORDER.filter(k=>G.SCENES[k]&&G.OPEN.has(k)).map(k=>{const ls=[...new Set((G.SCENES[k].mobs||[]).map(([t])=>G.MOBS[t]?.lvl))].filter(Boolean).sort((a,b)=>a-b);return{k,name:G.SCENES[k].name,band:ls.length?`${ls[0]}&ndash;${ls.at(-1)}`:"&mdash;",note:NOTE[k]||""}});return`<p><b>The world is a chain.</b> Each area is about ten levels past the last, and the way on is an edge of the map &mdash; walk off it and you are in the next one. Nothing is locked; you can walk anywhere at level one and die there.</p>
      <table class="tbl"><tr><th>Area</th><th>Monsters</th><th>What it has</th></tr>
        ${rows.map(r=>`<tr><td>${H.wl(`areas/${r.k}`,H.esc(r.name))}</td><td>${r.band}</td><td>${r.note}</td></tr>`).join("")}
      </table>
      <p><b>Cloudreach and the Golden Sands are a fork, not a rung.</b> At Combat 40 either will have you; they hold different ore, different trees and different fish, and neither is ahead of the other.</p>
      <p><b>Go one area past comfortable, not three.</b> Monsters hit harder than their level suggests once you are out of your depth, and dying costs a bigger share of your tickets the deeper you are &mdash; see <a data-wiki="guides/dying">Dying</a>.</p>
      <p><b>Bank first.</b> A death takes a percentage of what you are <i>carrying</i>, so an empty pocket makes a long trip out nearly free.</p>
      <p><b>The Wilderness is off this chain</b> and other players can attack you in it.</p>`}},{id:"tower",title:"The Tower",icon:"🗼",cat:"Going further",body:(G,H)=>{const T=H.TWR&&H.TWR.TOWER;if(!T)return`<p>The Tower stands in the Yard's north court. Climb it a floor at a time.</p>`;const mins=(T.fightMs/6e4).toFixed(1).replace(/\.0$/,""),bosses=Object.keys(T.bosses).map(Number).sort((a,b)=>a-b);return`<p><b>One door, ${T.floors} floors, one monster on each.</b> It stands in the Yard's north court beside the furnace. You need <b>Combat ${T.entry}</b> to go in, and floor 1 fights like a level ${H.TWR.levelOn(1)} monster; the top floor fights like a level <b>${T.topLevel}</b> one.</p>
      <p><b>Every fight is about the same length &mdash; ${mins} minutes &mdash; whoever you are.</b> The floor is built around the damage you actually do, so a better set does not make the climb shorter, it makes it survivable. What the Tower sells is a long, quiet fight you can half-watch; what it asks for is <b>food</b>.</p>
      <h3>Bring more fish than you think</h3>
      <p>At ${mins} minutes a floor you are being hit for the whole of it. Fill the bag. A floor you cannot finish is a floor you walk out of, and walking out is free &mdash; the climb is not.</p>
      <h3>Checkpoints every ${T.checkEvery}</h3>
      <p><b>You do not start again at the bottom.</b> The climb remembers the last checkpoint you passed, and they sit every ${T.checkEvery} floors, so the most a bad floor costs you is ${T.checkEvery-1} of them. When you come back you may start from that checkpoint &mdash; or from <b>floor 1</b>, if you would rather have the run.</p>
      <h3>Bosses</h3>
      <p>Every ${T.bossEvery}th floor is somebody in particular, and the ${T.floors}th is <b>The House</b>. A boss carries <b>${T.bossHp}&times;</b> the health of an ordinary floor and gets meaner below half, so treat ${bosses.slice(0,3).join(", ")} &hellip; ${bosses.at(-1)} as the floors to arrive at full.</p>
      <p><b>It pays in tickets and it pays well</b>, but it is a wage, not a jackpot: the deeper floors pay more because they take as long and hurt more, not because anything up there drops. Bring food, not bag space.</p>`}},{id:"carnival",title:"The Carnival",icon:"🎪",cat:"Going further",body:(G,H)=>{const band=[...new Set((G.SCENES.carnival?.mobs||[]).map(([t])=>G.MOBS[t]?.lvl))].filter(Boolean).sort((a,b)=>a-b);const gr=G.MOBS.grinner,tix=G.BOUNTY?.grinner;return`<p><b>Combat ${band[0]} to ${band.at(-1)}, east off the Thunderhead.</b> Four freaks on the midway, a duck pond, and a cage in the north-west with something in it.</p>
      <h3>The three stalls</h3>
      <p>Balloon Pop, the Shooting Gallery and Whack-a-Mole. <b>100 tickets a go</b>, a perfect round pays about <b>five times that</b>, and there is a short wait between rounds. They pay on how many you hit and they get faster as you go, so the last few shots are the ones worth having.</p>
      <p>They are a <b>game, not a wage</b>: a good round beats the fee, and no amount of practice beats fighting the midway for the same minutes. Play them because they are there.</p>
      <h3>The duck pond</h3>
      <p>The only water on the map, and the only place to catch ${H.ico("goldfish")} <b>goldfish</b> and ${H.ico("koi")} <b>koi</b>. Both ${H.wl("guides/smoking","smoke")}, and the koi's smoke is the best <b>bite rate</b> buff in the game &mdash; a fishing buff you have to fish for.</p>
      <h3>The cage</h3>
      <p><b>The Grinning Man</b> is behind a turnstile, and the turnstile takes a ${H.ico("carnivalticket")} <b>Carnival ticket</b>. They drop from the four outside at about <b>one kill in a hundred</b>, so the real price of the door is roughly half an hour of farming the midway.</p>
      <p>Which is why he pays what he pays: <b>${tix?tix.toLocaleString():"thousands"} tickets</b>, against a few hundred for anything else on the map. He is slow, he hits like the band above him, and he is only back every <b>five minutes</b> &mdash; so a party splits one of him rather than farming him.</p>
      <p><b>The ticket is a cover charge, paid once.</b> Going out costs nothing, and going back in costs another ticket.</p>`}},{id:"crypt",title:"The Crypt (parties)",icon:"🗝️",cat:"Going further",body:`<p><b>The only thing in the game you cannot do alone.</b> The stairs are in the Boneyard. Two to four of you go in, the door shuts, and what is inside is yours &mdash; nobody else can wander through it.</p>
      <h3>Getting a party</h3>
      <p><b>Click someone and invite them.</b> They get a line with an Accept on it, good for a minute. While anyone in the party is inside, everybody sees everybody health and where they are.</p>
      <p><b>Leaving the game does not leave the party.</b> Your place is held for three minutes, so a dropped connection is not a lost run &mdash; log back in and you are still in it, on the floor you were on.</p>
      <h3>The run</h3>
      <p><b>There is an ante</b>, taken on the way in, the same for everyone. A cleared crypt pays every member still in the party and still inside.</p>
      <p><b>The boss scales to how many of you there are</b>, so four people do not make it four times easier &mdash; they make the deeper tiers survivable at all.</p>
      <p><b>Monsters do not come back inside a run</b>, and the party shares them: you all hit the same thing instead of fighting over it.</p>
      <p><b>Nothing drops on the floor in there.</b> The run pays at the end, which is why clearing it matters and killing things in it does not, on its own.</p>
      <p><b>Fastest clears are recorded.</b> That is the actual reason to go back.</p>`},{id:"fighting",title:"Fighting",icon:"⚔️",cat:"Skills",body:(G,H)=>`<p><b>Click a monster.</b> You walk to it and keep swinging until one of you stops. Whoever hits it first owns it &mdash; nobody else can take your kill, except in the Wilderness where nothing is owned.</p>
      <h3>One skill, not four</h3>
      <p><b>Combat is a single skill and there are no stances to pick.</b> Every point of damage you deal trains it, and it does all three jobs at once: you land more of your swings, you hit harder, and you get hit less. Better weapons and armour ask for it.</p>
      <p><b>Hitpoints trains alongside it, always.</b> Damage pays Melee xp (Archery with a bow, Magic with a wand) and a third as much again into Hitpoints, so your health climbs whatever you are fighting. <b>At range it climbs slower:</b> with a bow or a wand, Hitpoints gets a third of what it gets with a melee weapon, because you are not the one standing in the way of the hits.</p>
      <h3>Three weapons, one speed each</h3>
      <p>Every tier has the same three, and they are within a whisker of each other on damage over time. It is a feel choice, not a power one.</p>
      <table class="tbl"><tr><th>Weapon</th><th>Swings every</th><th>Leans</th></tr>
        <tr><td>Gladius</td><td>1.8s</td><td>fast and accurate, small hits</td></tr>
        <tr><td>Longsword</td><td>2.4s</td><td>the middle of the three</td></tr>
        <tr><td>Maul</td><td>3.0s</td><td>slow and heavy, big hits</td></tr>
      </table>
      <h3>The nine grades</h3>
      <p>Weapons and armour gate on <b>Combat</b>, rings and amulets on <b>Hitpoints</b>. Bronze is the only tier Brutus sells; everything above it is <a data-wiki="guides/smithing">smithed</a> or dropped.</p>
      <table class="tbl"><tr><th>Grade</th><th>Needs</th><th>Full set defence</th><th>Weapon</th></tr>
        <tr><td>Bronze</td><td>10</td><td>20</td><td>+8 acc, +6 str</td></tr>
        <tr><td>Emerald</td><td>20</td><td>34</td><td>+12 acc, +10 str</td></tr>
        <tr><td>Diamond</td><td>30</td><td>48</td><td>+16 acc, +14 str</td></tr>
        <tr><td>Dragonstone</td><td>40</td><td>62</td><td>+20 acc, +18 str</td></tr>
        <tr><td>Onyx</td><td>50</td><td>76</td><td>+24 acc, +22 str</td></tr>
        <tr><td>Starfall</td><td>60</td><td>90</td><td>+28 acc, +26 str</td></tr>
        <tr><td>Eclipse</td><td>70</td><td>104</td><td>+32 acc, +30 str</td></tr>
        <tr><td>Nova</td><td>80</td><td>118</td><td>+36 acc, +34 str</td></tr>
        <tr><td>Singularity</td><td>90</td><td>132</td><td>+40 acc, +38 str</td></tr>
      </table>
      <p><b>The top two name their weapons differently.</b> Nova and Singularity do not carry a gladius, a longsword and a maul: they are the <b>flare knife, halberd and starbreaker</b>, and the <b>event blade, voidglaive and collapser</b>. The three roles are unchanged &mdash; quick, balanced, slow and heavy &mdash; only the names.</p>
      <p><b>And their weapons are a chase.</b> Every Nova or Singularity weapon wants a <b>core</b> as well as bars. A core drops from the hardest things in the game &mdash; the Junk King, the Yard Gator, the Last Dealer, the Hoodie and the Squeeze &mdash; at about one kill in two thousand, or it can be built at an anvil out of a heap of what those places drop. The armour and the tools need no core.</p>
      <p><b>Reforging is the other way up.</b> Bars spent at the anvil push a piece you already own three levels further, which is worth about a tier &mdash; a way to keep going when the next grade is out of reach, not a way past it. It can also destroy the piece. See the anvil.</p>
      <h3>Clicking again makes you swing faster</h3>
      <p><b>Click the monster you are already fighting and your next swing comes sooner.</b> Keep doing it and it comes sooner still, in four steps:</p>
      ${(()=>{const s=G.SWING_STACK,gl=G.ITEMS.bronze_gladius?.speed||1800,ml=G.ITEMS.bronze_maul?.speed||3e3;const row=(n,cut)=>`<tr><td>${n}${n===1?"st":n===2?"nd":n===3?"rd":"th"} swing in a row</td><td>${Math.round(cut*100)}% sooner</td><td>${(gl*(1-cut)/1e3).toFixed(2)}s</td><td>${(ml*(1-cut)/1e3).toFixed(2)}s</td></tr>`;return`<table class="tbl"><tr><th>Clicked before the swing?</th><th>Off the wait</th><th>Gladius</th><th>Maul</th></tr>
          <tr><td>No &mdash; left alone</td><td>&mdash;</td><td>${(gl/1e3).toFixed(2)}s</td><td>${(ml/1e3).toFixed(2)}s</td></tr>
          ${s.map((cut,n)=>row(n+1,cut)).join("")}
          ${s.length?`<tr><td>and onwards</td><td>${Math.round(s[s.length-1]*100)}% &mdash; the ceiling</td><td>${(gl*(1-s[s.length-1])/1e3).toFixed(2)}s</td><td>${(ml*(1-s[s.length-1])/1e3).toFixed(2)}s</td></tr>`:""}
        </table>`})()}
      <h4>How it actually works, so you are not guessing</h4>
      <p><b>It counts SWINGS, not clicks.</b> The game asks one question each time your weapon comes round: did you click since the last swing? Yes and you move one rung up the ladder; no and you drop straight back to the bottom. <b>Clicking five times between two swings is worth exactly the same as clicking once</b> &mdash; there is nothing to be gained from hammering it, and that is deliberate.</p>
      <p><b>So the whole technique is one click per swing.</b> Watch your character, click the monster again each time it lands a blow, and by the fourth you are at the ceiling and staying there.</p>
      <p><b>Miss one and you start again at the bottom.</b> Not one rung down &mdash; all the way. A stretch of clicking is worth far more than the same number of clicks scattered about, which is why this rewards paying attention rather than clicking a lot.</p>
      <p><b>Starting a NEW fight resets you.</b> Walking to the next monster costs you the ladder, so a big slow thing you stand and work is where this pays best; the ladder is also why finishing something already hurt beats wandering off to a fresh one.</p>
      <p><b>It stacks with everything else</b> &mdash; a faster weapon, a tool or pet speed bonus, a whiskey &mdash; because it takes a percentage off whatever your wait already is. The quick weapons gain the least in absolute seconds and the heavy ones the most.</p>
      <p><b>You never have to use it.</b> Leave it alone and your swing is the plain number in the table above; the game is balanced around that, and this is for when you want to lean in. It works on other players in the Wilderness too, and so does theirs.</p>
      <h3>The jackpot kill</h3>
      <p>A kill pays tickets, and about <b>one in every two hundred and fifty</b> pays <b>twelve times</b> what it should. It is not tied to what you killed, where you are or how long you have played &mdash; it is a lump of luck on an ordinary monster.</p>
      <h3>What a kill pays</h3>
      <p><b>Tickets come off a monster as a RANGE, not a fixed number.</b> Every kill is worth a certain amount and what actually drops is a slice of it, so two of the same monster rarely pay the same.</p>
      ${(()=>{const wide=Object.keys(G.MOBS).filter(k=>G.BOUNTY[k]&&G.tixSpread(k)[1]>G.tixSpread("__none__")[1]);const def=G.tixSpread("__none__");if(!wide.length)return`<p>Every monster uses the same band: <b>${def[0]}x to ${def[1]}x</b> of what it is worth.</p>`;const s=G.tixSpread(wide[0]);const eg=wide.map(k=>({k,b:G.BOUNTY[k]})).sort((x,y)=>y.b-x.b)[0];return`<p><b>Most monsters swing ${def[0]}x to ${def[1]}x</b> &mdash; a fairly tight wobble around what they are worth.</p>
        <p><b>The Thunderhead's swing ${s[0]}x to ${s[1]}x instead</b>: ${wide.map(k=>H.esc(G.MOBS[k].name)).sort().join(", ")}. The average is exactly the same; any single kill can pay a fifth or nearly double. ${H.esc(G.MOBS[eg.k].name)} is worth ${eg.b}, so out there it pays <b>${Math.round(eg.b*s[0])}</b> to <b>${Math.round(eg.b*s[1])}</b> where anywhere else it would be ${Math.round(eg.b*def[0])} to ${Math.round(eg.b*def[1])}.</p>
        <p><b>Why.</b> The Thunderhead was the richest ground in the game by a distance and its drops were cut. A flat cut only makes a place worse; widening the band gives back the <i>excitement</i> without giving back the <i>average</i>. The same money over a night, a great deal more swing in it.</p>`})()}
      <p><b>Ticket buffs multiply the drop</b>, so a Coin Toad or a tincture is worth the same percentage wherever you fight. And about <b>one kill in ${G.JACKPOT_KILL.odds}</b> pays <b>${G.JACKPOT_KILL.mult} times</b> what it should, which is not tied to what you killed or where you are.</p>
      <p><b>During a <a data-wiki="items/pot_double">2X event</a> every ticket doubles</b>, dropped or paid, for everyone on the server.</p>
      <p><b>Eat before you need to.</b> Cooked fish is the bulk of the healing in the game &mdash; and a salve out of the <a data-wiki="guides/alchemy">cauldron</a> heals more than any of it. See <a data-wiki="guides/cooking">Cooking</a>.</p>`},{id:"fishing",title:"Fishing",icon:"🎣",cat:"Skills",body:(G,H)=>{const spots=new Map;for(const[key,d]of Object.entries(G.SCENES)){if(d.wikiHide)continue;let b;try{b=G.buildScene(key)}catch{continue}for(const o of b.objs){if(o.t!=="spot")continue;const lvl=o.req?.lvl||1,sig=`${d.name}|${o.name}|${o.fish||"sardine"}`;if(!spots.has(sig))spots.set(sig,{where:d.name,name:o.name,lvl,xp:o.xp,fish:o.fish||"sardine",fish2:o.fish2||(o.fish?null:"perch"),f2lvl:o.fish2lvl??(o.fish?null:5),xp2:o.xp2})}}const rows=[...spots.values()].sort((a,b)=>a.lvl-b.lvl);const smokes=Object.keys(G.ITEMS).filter(k=>k.startsWith("s")&&G.ITEMS[k].meal&&G.ITEMS[k.slice(1)]).length;const fish=(k,lvl,xp)=>k?`${H.ico(k)} ${H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k))} &mdash; ${lvl}${xp?`, ${xp} xp`:""}`:"&mdash;";return`<p>Click a fishing spot with a <b>rod in your hand</b> &mdash; in the weapon slot, not the bag. You keep pulling fish out until you walk away or the three-minute idle cutoff stops you, which makes it the most comfortable thing in the game to do while you are half watching something else.</p>
      <p><b>Most spots hold two fish.</b> The second is better, needs a higher level, and turns up about a third of the time once you can catch it. Until then you get the first one only. A few waters hold one fish and nothing else.</p>
      <p><b>The water gates your rod as well as your level</b>, the same way a rock gates a pickaxe.</p>
      <table class="tbl"><tr><th>Water</th><th>Where</th><th>Rod</th><th>First fish</th><th>Second fish</th></tr>
        ${rows.map(r=>`<tr><td>${H.esc(r.name)}</td><td>${H.esc(r.where)}</td><td>${H.esc(G.toolNeed(r.lvl).name)}</td><td>${fish(r.fish,r.lvl,r.xp)}</td><td>${fish(r.fish2,r.f2lvl,r.xp2)}</td></tr>`).join("")}
      </table>
      <p><b>A better rod is faster, not luckier.</b> Each grade up takes 8% off the time between casts. See <a data-wiki="guides/tools">Tools</a>.</p>
      <p><b>A bite is not guaranteed.</b> It starts at about ${Math.round(G.FISHING.chance(1)*100)}% a cast and climbs with your level to ${Math.round(G.FISHING.chance(99)*100)}%, so a rod is never quite a conveyor belt.</p>
      <p><b>Raw fish is not food and Bom will not buy it.</b> That is the point rather than an inconvenience: cooking roughly doubles what a fish is worth and is the only thing that makes it heal. See <a data-wiki="guides/cooking">Cooking</a>, and <a data-wiki="guides/smoking">Smoked fish</a> for the ${["no","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve"][smokes]||smokes} that smoke into a 20-minute buff.</p>
      <p><b>Fishing is also the best place to find a real ZCoin</b> &mdash; roughly one cast in three hundred, creeping up with the better fish. See <a data-wiki="guides/zcoins">Finding ZCoins</a>.</p>`}},{id:"cooking",title:"Cooking",icon:"🍳",cat:"Skills",body:(G,H)=>{const rows=Object.entries(G.RECIPES).filter(([id])=>id.startsWith("cook_")).map(([,r])=>({to:r.out[0],lvl:r.lvl,stop:r.burnStop,heal:G.ITEMS[r.out[0]]?.heal,sell:G.SHOP.buys[r.out[0]],smoked:!!G.ITEMS[`s${r.in[0][0]}`]})).sort((a,b)=>a.lvl-b.lvl||(a.heal||0)-(b.heal||0));const smokes=rows.filter(r=>r.smoked).length;const WORD=["no","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve"];return`<p>There is a <b>campfire</b> just inside the Yard, by the way in from the casino, and a <b>range</b> in some interiors. Click it with raw food in your bag.</p>
      <p><b>Cooking roughly doubles a fish.</b> Raw fish cannot be eaten and Bom will not buy it, so every fish is worth a stop at the fire on the way home. The fire always cooks the best thing in your bag that you are able to cook, so there is nothing to choose.</p>
      <p><b>You will burn some at first, and then you will stop.</b> Each dish has a level at which it never burns again &mdash; that is the second column, and it is the one worth levelling towards.</p>
      <table class="tbl"><tr><th>Dish</th><th>Cook at</th><th>Stops burning</th><th>Heals</th><th>Bom pays</th></tr>
        ${rows.map(r=>`<tr><td>${H.ico(r.to)} ${H.wl(`items/${r.to}`,H.esc(G.ITEMS[r.to]?.name||r.to))}${r.smoked?" <small>(smokes)</small>":""}</td><td>${r.lvl}</td><td>${r.stop??"&mdash;"}</td><td>${r.heal??"&mdash;"}</td><td>${r.sell??"&mdash;"}</td></tr>`).join("")}
      </table>
      <p><b>${H.esc(String(WORD[smokes]||smokes).replace(/^./,c=>c.toUpperCase()))} of these can be smoked instead</b>, which heals more, sells for far more and gives a 20-minute buff. It needs charcoal, and the fire does it automatically when you are carrying some. See <a data-wiki="guides/smoking">Smoked fish</a>.</p>
      <p><b>Meat sits under fish on purpose.</b> A chicken is not a worse sardine; it is something you can cook at level 1 without a rod.</p>`}},{id:"smithing",title:"Smithing",icon:"🔨",cat:"Skills",body:`<p><b>The most common question about this skill is how to start it at all</b>, because at Smithing 1 you cannot make a single bar or a single piece of gear. Everything asks for level 10.</p>
      <p><b>You start by burning logs.</b> That is the whole answer. Take logs to the <b>furnace</b> in the Yard's north court and it turns them into <b>charcoal</b> &mdash; a Smithing level 1 job, and the only one there is. Charcoal is then the fuel every smelt needs, so the logs you burn getting to level 10 are not wasted: you need them anyway.</p>
      <table class="tbl"><tr><th>Burn</th><th>Gives</th><th>xp each</th></tr>
        <tr><td>Logs, Gloomwillow logs</td><td>1 charcoal</td><td>5</td></tr>
        <tr><td>Deadwood, Skyash, Rustpine logs</td><td>2 charcoal</td><td>10</td></tr>
        <tr><td>Ancient yew logs</td><td>3 charcoal</td><td>15</td></tr>
        <tr><td>Vaultwood, Bogwood logs</td><td>4 charcoal</td><td>20</td></tr>
        <tr><td>Gallows logs</td><td>8 charcoal</td><td>40</td></tr>
      </table>
      <p><b>Level 10 is 1,154 xp</b>, so it is about 230 ordinary logs &mdash; or far fewer if you are already cutting something better. Burning has a small chance to fail and eat the log; that is normal and it does not stop.</p>
      <h3>Then the chain</h3>
      <p><b>Ore + charcoal &rarr; bar, at the furnace. Bars &rarr; gear, at the anvil.</b> Both are in the Yard's north court, beside the Crypt stairs.</p>
      <table class="tbl"><tr><th>Bar</th><th>Smithing</th><th>Takes</th><th>xp</th></tr>
        <tr><td>Bronze</td><td>10</td><td>1 copper + 1 tin + 1 charcoal</td><td>15</td></tr>
        <tr><td>Emerald</td><td>20</td><td>2 emerald ore + 1 charcoal</td><td>30</td></tr>
        <tr><td>Diamond</td><td>30</td><td>2 diamond ore + <b>2</b> charcoal</td><td>45</td></tr>
        <tr><td>Dragonstone</td><td>40</td><td>2 dragonstone ore + <b>2</b> charcoal</td><td>60</td></tr>
        <tr><td>Onyx</td><td>50</td><td>4 onyx ore + 2 <b>grimstone</b> + <b>6</b> charcoal</td><td>75</td></tr>
        <tr><td>Starfall</td><td>60</td><td>4 starfall ore + 1 <b>onyx bar</b> + <b>6</b> charcoal</td><td>90</td></tr>
        <tr><td>Eclipse</td><td>70</td><td>4 eclipse ore + 2 <b>voidglass</b> + <b>8</b> charcoal</td><td>105</td></tr>
        <tr><td>Nova</td><td>80</td><td>4 nova ore + 1 <b>eclipse bar</b> + <b>10</b> charcoal</td><td>120</td></tr>
        <tr><td>Singularity</td><td>90</td><td>4 singularity ore + 1 <b>nova bar</b> + <b>12</b> charcoal</td><td>135</td></tr>
      </table>
      <p><b>From onyx up a bar costs twice what it used to</b> (2026-09-27): twice the ore, twice the extra and twice the charcoal. The bar of the tier below is still one, because it has already doubled.</p>
      <p><b>The top of the ladder wants more than ore.</b> Onyx needs grimstone, eclipse needs voidglass, and starfall, nova and singularity each want a finished bar of the tier below &mdash; so a Singularity bar is a Nova bar is an Eclipse bar, all the way down &mdash; so the last stretch is a chain, not a grind, and the charcoal bill climbs with it.</p>
      <p><b>You do not choose what to make.</b> The furnace and the anvil always make the best thing you can, out of what is in your bag, which is why a furnace with logs AND ore in front of it burns, smelts, burns and smelts by itself.</p>
      <h3>What a piece costs</h3>
      <table class="tbl"><tr><th>Piece</th><th>Bars</th><th>xp at bronze</th></tr>
        <tr><td>Cuirass</td><td>5</td><td>100</td></tr>
        <tr><td>Greaves, shield, maul</td><td>3</td><td>60</td></tr>
        <tr><td>Helm, longsword, ring</td><td>2</td><td>40</td></tr>
        <tr><td>Amulet</td><td>3</td><td>60</td></tr>
        <tr><td>Boots, gloves, gladius</td><td>1</td><td>20</td></tr>
      </table>
      <p>Each grade wants Smithing equal to its <a data-wiki="guides/fighting">gear tier</a> &mdash; emerald at 20, diamond at 30, and so on up to eclipse at 70.</p>
      <h3>Why bother, when Bom sells gear</h3>
      <p><b>Because he is not cheap.</b> A full eclipse set over his counter is around 819,000 tickets; the ore to smith one is about 2,125. Diamond is 62 times dearer bought, onyx 138, eclipse 386. Once you have a furnace and an anvil there is no sensible reason to buy gear again.</p>
      <p><b>Smith to wear it, not to sell it.</b> Bom buys smithed gear back for an eighth of his shelf price and never more than <b>2,500</b> a piece, reforged or not. Everything from onyx up hits that ceiling, and from nova up the bars are worth more sold on their own than the finished piece.</p>
      <h3>Reforging</h3>
      <p><b>Bars also push gear you already own further.</b> At the anvil, three levels, each worth 5.5% of that piece's own stats or +1, whichever is more &mdash; about a tier in total. A reforge costs the same bars the piece cost to make.</p>
      <p><b>It can destroy the piece.</b> +1 always works. +2 is 80%, and a miss there has an 8% chance of breaking it; +3 is 55%, with a 15% chance. About one piece in seven is lost on the way to +3, and the bars go whether it works or not.</p>
      <p>Tools reforge too, and they buy <b>speed</b> rather than combat &mdash; +2.5% a level at mining, chopping or fishing.</p>
      <h3>Temper, Flux and the Master's seal</h3>
      <p><b>Carrying one does nothing on its own.</b> At the anvil, open the <b>Reforge</b> tab. Every aid you are carrying shows as a button above the list of your gear. <b>Click the button so it lights up</b>, then reforge. A lit aid is used up on that one attempt, whether it works or not, so light it again before the next swing. You can light more than one at once.</p>
      <table class="tbl"><tr><th>Aid</th><th>What it does</th><th>Make it at the anvil</th></tr>
        <tr><td><a data-wiki="items/temper">Temper</a></td><td><b>+20% to that attempt's chance.</b> +2 goes from 80% to 99%, +3 from 55% to 75%, +4 from 35% to 55%. It does <b>not</b> stop a failure breaking the piece.</td><td>Smithing 20: 2 whetgrit and 1 bronze bar</td></tr>
        <tr><td><a data-wiki="items/flux">Flux</a></td><td><b>A failure cannot destroy the piece:</b> it drops one level instead. It does not raise the chance.</td><td>Smithing 40: 2 quench salts and 1 whetgrit</td></tr>
        <tr><td><a data-wiki="items/masters_seal">Master's seal</a></td><td>Takes a piece <b>one step past +3, to +4</b> (35% to succeed).</td><td>Smithing 60: 1 seal wax and 1 flux</td></tr>
      </table>
      <p><b>Temper and Flux together</b> on a +3 attempt is 75% to succeed and no chance of losing the piece. Whetgrit, quench salts and seal wax come from pickpocketing in the Thieves' Guild.</p>`},{id:"mining",title:"Mining",icon:"⛏️",cat:"Skills",body:(G,H)=>{const at={};for(const[key,d]of Object.entries(G.SCENES)){if(d.wikiHide)continue;let b;try{b=G.buildScene(key)}catch{continue}for(const o of b.objs){if(o.req?.skill!=="mining"||!o.ore)continue;const r=at[o.ore]||={lvl:o.req.lvl,where:new Set,vein:false};r.lvl=Math.min(r.lvl,o.req.lvl);r.where.add(d.name);r.vein||=o.t==="vein"}}const useOf=ore=>{const rs=Object.values(G.RECIPES).filter(x=>x.in.some(([k])=>k===ore));if(!rs.length)return"&mdash;";const main=rs.find(x=>x.in[0][0]===ore);if(main&&G.ITEMS[main.out[0]])return H.wl(`items/${main.out[0]}`,H.esc(G.ITEMS[main.out[0]].name))+(rs.length>1?" and up":"");const other=G.ITEMS[rs[0].out[0]];return other?`needed for ${H.wl(`items/${rs[0].out[0]}`,H.esc(other.name.toLowerCase())+"s")}`:"&mdash;"};const rows=Object.entries(at).map(([ore,r])=>({ore,...r,tool:G.toolNeed(r.lvl),pays:G.SHOP.buys[ore],into:useOf(ore)})).sort((a,b)=>a.lvl-b.lvl);return`<p>Click a rock with a <b>pickaxe in your hand</b> &mdash; in the weapon slot, not the bag. Every rock holds 2 to 12 ore and you keep working it until it is empty, so one rock is several swings rather than one.</p>
      <p><b>Two things gate a rock: your level AND your pickaxe</b>, and they are not the same number. Emerald ore needs Mining 20 and an emerald pickaxe &mdash; having the level with a bronze pickaxe gets you nothing, which is the single most common reason a rock will not budge. <b>The pickaxe a rock wants is not always its own grade</b>: the top rungs gate above their ore on purpose, so nova ore is worked with an eclipse pickaxe. See <a data-wiki="guides/tools">Tools</a>.</p>
      <table class="tbl"><tr><th>Ore</th><th>Mining</th><th>Pickaxe</th><th>Where</th><th>Bom pays</th><th>What it makes</th></tr>
        ${rows.map(r=>`<tr><td>${H.ico(r.ore)} ${H.wl(`items/${r.ore}`,H.esc(G.ITEMS[r.ore]?.name||r.ore))}${r.vein?" <small>(vein)</small>":""}</td><td>${r.lvl}</td><td>${H.esc(r.tool.name)}</td><td>${[...r.where].join(", ")}</td><td>${r.pays??"&mdash;"}</td><td>${r.into}</td></tr>`).join("")}
      </table>
      <p><b>Copper and tin are a pair.</b> A bronze bar wants one of each, so mine them together or you will be back.</p>
      <p><b>A vein never runs dry.</b> It is slower per ore than a rock &mdash; about six seconds a swing against under two &mdash; but it does not empty and it does not stop you, so it is what you stand at while you are half watching something else. The three-minute idle cutoff still applies.</p>
      <p><b>Some of these are not ore, they are ingredients.</b> The top bars will not go without them, which is what makes the last stretch of <a data-wiki="guides/smithing">Smithing</a> a chain rather than a grind.</p>
      <p><b>Selling raw ore is the worst thing you can do with it.</b> A bar is worth more than its ore, and gear is worth vastly more than bars.</p>`}},{id:"woodcutting",title:"Woodcutting",icon:"🪓",cat:"Skills",body:(G,H)=>{const at={};for(const[key,d]of Object.entries(G.SCENES)){if(d.wikiHide)continue;let b;try{b=G.buildScene(key)}catch{continue}for(const o of b.objs){if(o.req?.skill!=="woodcutting")continue;const y=o.log||"logs",r=at[y]||={lvl:o.req.lvl,where:new Set};r.lvl=Math.min(r.lvl,o.req.lvl);r.where.add(d.name)}}const burnOf=log=>{const r=Object.values(G.RECIPES).find(x=>x.in.length===1&&x.in[0][0]===log&&x.out[0]==="charcoal");return r?r.out[1]:0};const rows=Object.entries(at).map(([log,r])=>({log,...r,tool:G.toolNeed(r.lvl),pays:G.SHOP.buys[log],char:burnOf(log)})).sort((a,b)=>a.lvl-b.lvl);const noBurn=rows.filter(r=>!r.char);return`<p>Click a tree with an <b>axe in your hand</b>. A tree is good for about 25 logs before it falls, an oak for about 50, and a felled one is back in fifteen seconds.</p>
      <p><b>Most trees are scenery.</b> The ones you can actually cut have their own art &mdash; in the Yard they are the two gnarled Old oaks, and every zone past it names its tree. If clicking does nothing, it is not a tree.</p>
      <p><b>Level and axe are separate gates</b>, the same as <a data-wiki="guides/mining">mining</a>.</p>
      <table class="tbl"><tr><th>Logs</th><th>Woodcutting</th><th>Axe</th><th>Where</th><th>Bom pays</th><th>Burns into</th></tr>
        ${rows.map(r=>`<tr><td>${H.ico(r.log)} ${H.wl(`items/${r.log}`,H.esc(G.ITEMS[r.log]?.name||r.log))}</td><td>${r.lvl}</td><td>${H.esc(r.tool.name)}</td><td>${[...r.where].join(", ")}</td><td>${r.pays??"&mdash;"}</td><td>${r.char?`${r.char} charcoal`:"<b>nothing</b>"}</td></tr>`).join("")}
      </table>
      <p><b>Logs are fuel, not just stock.</b> Every smelt in the game needs charcoal and charcoal is burnt logs, so woodcutting feeds <a data-wiki="guides/smithing">Smithing</a> exactly the way mining does.</p>
      <p><b>A log further out is not always worth more.</b> Charcoal per log and what Bom pays for it move separately &mdash; read both columns before walking somewhere for a tree.</p>
      ${noBurn.length?`<p><b>${noBurn.map(r=>H.esc(G.ITEMS[r.log]?.name||r.log)).join(" and ")} will not burn.</b> There is no furnace recipe for ${noBurn.length>1?"them":"it"} yet, so for now ${noBurn.length>1?"they are":"it is"} something to sell rather than fuel.</p>`:""}
      <p><b>Burning is the only Smithing you can do at level 1</b>, so a woodcutter already has a Smithing career started whether they meant to or not.</p>`}},{id:"harvesting",title:"Harvesting",icon:"🌾",cat:"Skills",body:(G,H)=>`<p><b>Two halves.</b> Picking things that grow in the world, and growing your own on <a data-wiki="guides/islands">your island</a>.</p>
      <p><b>In the world</b>: <b>three patches of wheat grow wild in the Yard</b> &mdash; one in the north-west above the copper, one beside the path through the middle, and one out in the south-west meadow. Click them and they grow back on their own. <b>It is the only gathering skill that needs nothing in your hand</b> &mdash; no tool, no grade, no gate but your level.</p>
      <p><b>On your island</b> a plot grows in real time whether you are logged in or not, and pays back several of what you planted. That is where the levels are.</p>
      ${SEEDS_NOTE(G)}
      ${cropTable(G,H)}
      <p><b>Plant the longest crop you can before you log off</b> and the short ones while you are around. A plot is doing nothing between ripening and your coming back, which is the only real skill in this skill.</p>
      <p><b>Your island decides how many plots you have</b> &mdash; 8 to start, 12 for 5,000 tickets, 20 for 20,000. It multiplies everything above, so it is the upgrade that matters.</p>
      <p><b>It is background money, not a living.</b> A full set of plots kept going comes to a fraction of what fighting the same zone pays; the appeal is that it happens while you are doing something else.</p>`},{id:"thieving",title:"Thieving",icon:"🤏",cat:"Skills",body:(G,H)=>`<p><b>The Thieves&rsquo; Guild is south of the Yard</b>, behind a door that wants a permit. Inside are four rooms of guild members, two marks to a room, and you pick their pockets. <b>Nothing in there fights back and nothing can be attacked</b> &mdash; it is the only skill in the game that needs no combat level at all, no weapon and no armour.</p>

      <h3>Getting in</h3>
      <p>You need a <b>Thieves&rsquo; permit</b>, and there are two ways to hold one:</p>
      <ul><li>Buy one at the shop for <b>50,000 tickets</b>.</li>
        <li>Find one in <b>the Hoodie&rsquo;s hoard</b> at the end of a Crypt run &mdash; about one chest in 105, 62 or 39 depending on the difficulty. Not past your three paid runs for the day.</li></ul>
      <p>It is an ordinary item, so it can be <b>bought and sold on the market</b>, which usually means it changes hands for rather less than the shop charges. The door takes it off you the first time and never asks again &mdash; so a permit you have already used cannot be sold on.</p>

      <h3>The four rooms</h3>
      <p><b>A clean run pays twice.</b> Lift five in a row without being caught and the fifth one comes out with two things instead of one. Getting caught puts you back to nothing &mdash; so the stun is not just lost time, it is the run it breaks.</p>
      <p>Each room is behind a door, and <b>the door and the marks are two different ladders</b>. The first door opens at Thieving 10 although the Grifters behind it cannot be picked until 25 &mdash; that is on purpose, so there is somewhere to walk to and look at while you are still learning.</p>
      <table class="tbl"><tr><th>Room</th><th>Door opens</th><th>Pick at</th><th>xp a pick</th><th>Tickets an hour</th></tr>
        <tr><td>The Back Room &mdash; Apprentice Lifters</td><td>&mdash;</td><td>1</td><td>19</td><td>~3,400</td></tr>
        <tr><td>The Back Room &mdash; Cutpurses</td><td>&mdash;</td><td>15</td><td>36</td><td>~4,500</td></tr>
        <tr><td>The Card Room &mdash; Grifters</td><td>10</td><td>25</td><td>56</td><td>~9,000</td></tr>
        <tr><td>The Card Room &mdash; The Shills</td><td>10</td><td>40</td><td>95</td><td>~14,800</td></tr>
        <tr><td>The Store Room &mdash; The Fixers</td><td>50</td><td>50</td><td>138</td><td>~22,000</td></tr>
        <tr><td>The Store Room &mdash; Housebreakers</td><td>50</td><td>62</td><td>182</td><td>~26,300</td></tr>
        <tr><td>The Vault Room &mdash; The Quartermaster</td><td>75</td><td>75</td><td>250</td><td>~33,000</td></tr>
        <tr><td>The Vault Room &mdash; The Ringleader</td><td>75</td><td>90</td><td>337</td><td>~36,300</td></tr>
      </table>

      <h3>How a pick works</h3>
      <p>Click a mark and you keep trying, one attempt every <b>2.4 seconds</b>, until you stop or you land one. Against a mark of <b>your own level you land 55%</b>, and <b>every level above that adds 2%</b>, up to a ceiling of <b>90%</b>. So a room you have just unlocked is the hard one and the room behind you is nearly free.</p>
      <p><b>Get caught</b> and the mark has your wrist: you are held for <b>two to three and a half seconds</b> and <b>one stolen thing falls out of your bag</b>. Only things taken in the guild can be lost that way &mdash; never tickets, never your gear, never your permit.</p>
      <p><b>After a successful lift that mark keeps a hand on their pocket for six seconds.</b> There are three of each in every room, so you work the room rather than one pocket.</p>

      <h3>What they carry</h3>
      ${(()=>{const marks=Object.values(G.MARKS).sort((x,y)=>x.lvl-y.lvl);return`<table class="tbl"><tr><th>Mark</th><th>Thieving</th><th>What</th><th>How often</th><th>Fence</th></tr>
          ${marks.map(m=>(m.drop||[]).map(([k,ch],i)=>`<tr>${i?"":`<td rowspan="${m.drop.length}">${H.esc(m.name)}</td><td rowspan="${m.drop.length}">${m.lvl}</td>`}<td>${H.ico(k)} ${H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k))}</td><td>${Math.round(ch*100)}%</td><td>${G.SHOP.buys[k]?G.ITEMS[k]?.name.match(/ore|glass/i)?`${G.SHOP.buys[k]}, but smelt it`:G.SHOP.buys[k]:"keep it"}</td></tr>`).join("")).join("")}
        </table>`})()}
      <p><b>Buttons, watches, signets and ledgers are just money</b> &mdash; sell them at the Prize Counter. Everything else goes to an anvil, and that is the half worth having.</p>

      <h3>What the materials make</h3>
      <p>Three things, all at the <b>anvil</b>, none of them sold anywhere. Each is spent on <b>one reforge attempt</b> whatever that attempt does; tick them on at the anvil before you swing and the odds shown move with them.</p>
      <table class="tbl"><tr><th>What</th><th>Smithing</th><th>Made from</th><th>What it does</th></tr>
        <tr><td><b>Temper</b></td><td>20</td><td>2 whetgrit, 1 bronze bar</td><td>Adds <b>20 points</b> to the odds of that reforge</td></tr>
        <tr><td><b>Flux</b></td><td>40</td><td>2 quenching salts, 1 whetgrit</td><td>A failed reforge <b>cannot destroy the piece</b>; it only drops a level</td></tr>
        <tr><td><b>Master&rsquo;s seal</b></td><td>60</td><td>1 guild seal wax, 1 flux</td><td>The only way to take a piece <b>past +3, to +4</b></td></tr>
      </table>
      <p>A seal eats a flux, so seals can never be commoner than flux. If you are reforging something you would hate to lose, the honest advice is <b>flux first and temper second</b>: a temper only improves your chances, a flux is what stops the piece cracking in half.</p>

      <h3>Things go wrong at the anvil</h3>
      <p><b>Nothing you smelt or hammer is a certainty.</b> One attempt in ten fails &mdash; a bar, a piece of gear, a temper, all of it &mdash; at every level, and a failure takes the materials with it. The panel at the furnace and the anvil prints the chance on every row, so you are never guessing.</p>
      <p><b>Nova and Singularity are the exception</b> and never fail. Their weapons already cost a core that drops about one kill in two thousand; asking you to gamble that as well would be cruel rather than tense.</p>

      <h3>The other way to the top of smithing</h3>
      <p><b>The Quartermaster&rsquo;s room carries starfall ore, eclipse ore and voidglass.</b> Those three are otherwise only found in the Vault, and voidglass is not dropped by any monster at all &mdash; so a thief can supply their own Starfall and Eclipse gear without ever going down there. That is the real reason people want into the last room.</p>

      <h3>The Ditched set</h3>
      <p>Four pieces of a thief&rsquo;s kit that somebody threw in the water rather than be caught holding, and they come back out on a <b>fishing line</b>. Nobody in the guild sells them and nothing in the guild drops them &mdash; if you want them you fish, or you buy them off somebody who did.</p>
      <table class="tbl"><tr><th>Piece</th><th>Slot</th><th>Each gives</th></tr>
        <tr><td>Ditched hood</td><td>Helm</td><td rowspan="4">+2.5% to pick, +3% speed</td></tr>
        <tr><td>Ditched coat</td><td>Body</td></tr>
        <tr><td>Ditched gloves</td><td>Gloves</td></tr>
        <tr><td>Ditched boots</td><td>Boots</td></tr>
      </table>
      <p><b>A full set is +10% on every pick and +12% speed</b>, which takes the climb to 99 from about 72 hours to 61 &mdash; and to around 58 if you also have a pet that hurries you along. It is worn in ordinary armour slots, so you are giving up your combat gear to wear it. Inside the guild that costs you nothing, because nothing in there fights back; the moment you walk out, it costs you everything.</p>
      <p><b>The 90% ceiling still holds.</b> Gear helps while you are climbing towards it, which is the part that drags, and does nothing once you are already there.</p>
      <p>A piece turns up about <b>once every two hours</b> of steady fishing, from any water, so a set is an evening. Gear that helps you find rare things helps here too.</p>

      <h3>Who to talk to</h3>
      <p>Four guild members wander the rooms and are not marks &mdash; you cannot pick them, and they will not mind you trying. <b>Sticky Pete</b>, in the first room, explains how picking works. <b>Marla Nine-Fingers</b>, in the card room, explains what the materials are for. <b>The Quiet Man</b> and <b>Odile the Clerk</b> keep the two back rooms.</p>

      <h3>What it is worth</h3>
      <p><b>1 to 99 is about 72 hours</b> if you always work the best room you can reach &mdash; about level with Woodcutting, and a good deal quicker than Combat&rsquo;s 149. A full Ditched set takes it to roughly 61. The top room earns about what a middling miner does. That is deliberate: a room where nothing fights back should not also be the best money in the game, and the guild&rsquo;s real payment is the materials.</p>`},{id:"magic",title:"Magic",icon:"🪄",cat:"Skills",body:(G,H)=>{const nm=k=>H.esc(G.ITEMS[k]?.name||k),E=G.ELEMENTS,els=G.ELEMENT_KEYS;const pages=Object.keys(G.ITEMS).filter(k=>G.ITEMS[k].ammo?.kind==="page").sort((a,b)=>G.ITEMS[a].req.lvl-G.ITEMS[b].req.lvl);const wands=Object.keys(G.ITEMS).filter(k=>G.ITEMS[k].wand).sort((a,b)=>G.ITEMS[a].req.lvl-G.ITEMS[b].req.lvl);const bags=Object.keys(G.ITEMS).filter(k=>G.ITEMS[k].pouch?.ammo==="page").sort((a,b)=>G.ITEMS[a].req.lvl-G.ITEMS[b].req.lvl);const byEl=(el,f)=>Object.keys(G.MOBS).filter(t=>G.MOBS[t][f]===el).map(t=>H.wl(`monsters/${t}`,H.esc(G.MOBS[t].name)));return`<p><b>The third way to fight.</b> Hold a wand and every roll reads your <b>Magic</b> level &mdash; accuracy, max hit and defence &mdash; and every point of damage pays Magic xp, one for one, the way Melee and Archery do. Your combat level takes your best style in full and a little of the others.</p>
      <h3>Getting started</h3>
      <p>Brutus sells a <b>rough wand</b>, a <b>Scrap Satchel</b> and <b>Arcane bolts</b>, all Magic 1. Wand in the weapon hand, bag in the offhand, click the pages in your bag to load it. A wand casts from ${G.ITEMS.logs_wand.launcher.range} tiles and spends one page a cast.</p>
      <h3>The five elements</h3>
      <p>A page carries an element. A monster <b>weak</b> to it takes ${Math.round((G.MAGIC.weakMul-1)*100)}% more; one that <b>resists</b> it takes ${Math.round((1-G.MAGIC.resistMul)*100)}% less. Hover a monster to see which. Each element also does something of its own:</p>
      <table class="tbl"><tr><th>Element</th><th>Does</th><th>Weak to it</th></tr>
        <tr><td>${H.el("fire")} Fire</td><td>Half the time it burns: ${Math.round(G.MAGIC.burn.share*100)}% of the hit again a moment later</td><td>${byEl("fire","weak").join(", ")}</td></tr>
        <tr><td>${H.el("frost")} Frost</td><td>Slows the monster's swing for ${G.MAGIC.slow.ms/1e3} seconds</td><td>${byEl("frost","weak").join(", ")}</td></tr>
        <tr><td>${H.el("storm")} Storm</td><td>Arcs to one monster beside the target for half the damage</td><td>${byEl("storm","weak").join(", ")}</td></tr>
        <tr><td>${H.el("void")} Void</td><td>Ignores ${Math.round(G.MAGIC.pierce*100)}% of the target's defence</td><td>${byEl("void","weak").join(", ")}</td></tr>
        <tr><td>${H.el("sun")} Sun</td><td>Heals you for ${Math.round(G.MAGIC.sunHeal*100)}% of the damage</td><td>${byEl("sun","weak").join(", ")}</td></tr>
      </table>
      <p>Arcane pages are practice pages: no element, so nothing is weak to them and nothing resists them.</p>
      <h3>Spell pages</h3>
      <table class="tbl"><tr><th>Magic</th><th>Page</th><th>Adds</th></tr>${pages.map(k=>`<tr><td>${G.ITEMS[k].req.lvl}</td><td>${H.ico(k)} ${H.wl(`items/${k}`,nm(k))}</td><td>+${G.ITEMS[k].ammo.str}</td></tr>`).join("")}</table>
      <h3>Wands</h3>
      <table class="tbl"><tr><th>Magic</th><th>Wand</th></tr>${wands.map(k=>`<tr><td>${G.ITEMS[k].req.lvl}</td><td>${H.ico(k)} ${H.wl(`items/${k}`,nm(k))}</td></tr>`).join("")}</table>
      <h3>Magic Bags</h3>
      <p>Only five, so the steps are big. Each holds one kind of page in the offhand, and each can be reforged for more room. A wand casts only what is loaded in its Magic Bag: pages in your bag do not cast until you load them. Click a different page to swap spells.</p>
      <table class="tbl"><tr><th>Magic</th><th>Bag</th><th>Holds</th></tr>${bags.map(k=>`<tr><td>${G.ITEMS[k].req.lvl}</td><td>${H.ico(k)} ${H.wl(`items/${k}`,nm(k))}</td><td>${G.ITEMS[k].pouch.cap.toLocaleString()}</td></tr>`).join("")}</table>
      <p>Everything a wand casts is printed with <a data-wiki="guides/wizardry">Wizardry</a>.</p>`}},{id:"jewelcrafting",title:"Jewelcrafting",icon:"💍",cat:"Skills",body:(G,H)=>{const nm=k=>H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k)),rows=Object.values(G.RECIPES).filter(r=>r.station==="jbench").sort((a,b)=>a.lvl-b.lvl);const row=r=>`<tr><td>${r.lvl}</td><td>${H.ico(r.out[0])} ${r.out[1]>1?`${r.out[1]} `:""}${nm(r.out[0])}</td><td>${r.in.map(([k,n])=>`${n} ${nm(k)}`).join(", ")}</td><td>${r.xp}</td></tr>`;const WORD={tough:"less damage taken",bite:"more bites",speed:"faster at everything",rare:"better drops",tix:"more tickets"};return`<p><b>The jeweller's bench stands in the Yard, beside the anvil.</b> It does three things, and each is made out of another skill's work.</p>
      <h3>Polishing</h3><p>This is what trains it. Beads from the Yard's copper and tin, then glass from sand, then every ore from diamond up into a polished stone that Bom pays a little more for than the ore.</p>
      <table class="tbl"><tr><th>Level</th><th>Makes</th><th>From</th><th>xp</th></tr>${rows.filter(r=>!/^jc_(cut|set)/.test(r.id)).map(row).join("")}</table>
      <h3>Cutting</h3><p>The four gems Mining turns up (and the Depths' crystal veins, now and then) cut into stones worth far more.</p>
      <table class="tbl"><tr><th>Level</th><th>Makes</th><th>From</th><th>xp</th></tr>${rows.filter(r=>/^jc_cut/.test(r.id)).map(row).join("")}</table>
      <h3>Setting</h3><p>A cut gem goes into a ring or amulet Smithing made. It keeps every number its metal had and gains the gem's power; an amulet carries it twice.</p>
      <table class="tbl"><tr><th>Level</th><th>Makes</th><th>From</th><th>Adds</th></tr>${rows.filter(r=>/^jc_set/.test(r.id)).map(r=>{const it=G.ITEMS[r.out[0]],B=G.ITEMS[it.gembase];const add=Object.entries(it.fx||{}).filter(([k,v])=>(B.fx||{})[k]!==v).map(([k,v])=>`${Math.round(v*100)}% ${WORD[k]||k}`).join(", ");return`<tr><td>${r.lvl}</td><td>${H.ico(r.out[0])} ${nm(r.out[0])}</td><td>${r.in.map(([k,n])=>`${n} ${nm(k)}`).join(", ")}</td><td>${add}</td></tr>`}).join("")}</table>`}},{id:"fungiculture",title:"Fungiculture",icon:"🍄",cat:"Skills",body:(G,H)=>{const nm=k=>H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k)),mins=ms=>ms>=54e5?`${Math.round(ms/36e4)/10} h`:`${Math.round(ms/6e4)} min`;const where=Object.fromEntries(Object.keys(G.FUNGI).map(sk=>[G.FUNGI[sk].yields,Object.entries(G.FUNG_WILD).filter(([,l])=>l.includes(G.FUNGI[sk].yields)).map(([m])=>G.SCENES[m]?.name||(m==="wild"?"The Wilderness":m==="deep"?"The Deep Wild":m))]));const shrooms=new Set(Object.values(G.FUNGI).map(F=>F.yields));const made=Object.values(G.RECIPES).filter(r=>r.station!=="compost"&&r.in.some(([x])=>shrooms.has(x))).sort((a,b)=>a.skill.localeCompare(b.skill)||a.lvl-b.lvl);const uses=k=>Object.values(G.RECIPES).filter(r=>r.in.some(([x])=>x===k)&&r.station!=="compost").map(r=>nm(r.out[0])).filter((v,i,a)=>a.indexOf(v)===i).join(", ")||"&mdash;";return`<p><b>Mushrooms, grown in a cellar under your island and picked wild on every map.</b> Yahsmeena sells a <b>Cellar ladder</b>; put it down with Decorate and click it to climb down. Only you can.</p>
      <h3>The cellar</h3>
      <ol><li>Make <b>compost</b> at the bin in the corner. This is how Fungiculture is trained from level 1.</li>
      <li>Click a <b>fungus bed</b> and plant <b>spawn</b> in it. Each planting takes compost, one to three by the shroom.</li>
      <li>Come back when it is ripe. A bed gives its shrooms, and <b>${G.SEED_BACK} spawn back, ${G.SEED_BACK+1} one time in ${Math.round(1/G.SEED_EXTRA)}</b>, so a bed planted once keeps going.</li></ol>
      <p>A first island opens ${G.FUNG.beds[1]} beds, a bigger one ${G.FUNG.beds[2]}, the Far Shore all ${G.FUNG.beds[3]}. Rainmaker waters a bed like a plot, a Truffle Pig makes every harvest a quarter heavier (its Legendary, the Truffle Baron, nearly half), and either one out <b>triples the shrooms and the spawn</b> a bed gives back.</p>
      <h3>Compost</h3>
      <table class="tbl"><tr><th>Level</th><th>Makes</th><th>From</th></tr>${Object.values(G.RECIPES).filter(r=>r.station==="compost").sort((a,b)=>a.lvl-b.lvl).map(r=>`<tr><td>${r.lvl}</td><td>${r.out[1]} ${nm("compost")}</td><td>${r.in.map(([k,n])=>`${n} ${nm(k)}`).join(", ")}</td></tr>`).join("")}</table>
      <h3>Wild clusters</h3>
      <p>Every outdoor map has <b>three clusters</b>, always in the same places. Each gives you one pick a day: ${G.FUNG.wildN[0]} to ${G.FUNG.wildN[1]} shrooms, some xp, and about ${Math.round(G.FUNG.wildSpawn*100)}% of the time its spawn. A cluster you have picked today is drawn faint. The Gloam's toadstools drop sporecap spawn now and then too.</p>
      <p><b>The black truffle grows nowhere wild.</b> Wear a Truffle Pig while you pick: about ${Math.round(G.FUNG.truffle.pick*100)}% of picks turn one up, and some turn up its spawn. The Truffle Baron finds them about ${Math.round(G.FUNG.truffle.pick*G.TRUFFLE_BARON*100)}% of the time. Either one also <b>triples</b> the shrooms a wild pick gives, and any spawn it turns up.</p>
      <h3>The shrooms</h3>
      <table class="tbl"><tr><th>Level</th><th>Shroom</th><th>Grows</th><th>Compost</th><th>xp</th><th>Wild in</th><th>Goes into</th></tr>${Object.entries(G.FUNGI).map(([sk,F])=>`<tr><td>${F.lvl}</td><td>${H.ico(F.yields)} ${nm(F.yields)}</td><td>${mins(F.ms)}</td><td>${F.compost}</td><td>${F.xp.toLocaleString()}</td><td>${where[F.yields].length?H.esc(where[F.yields].join(", ")):"A Truffle Pig finds it"}</td><td>${uses(F.yields)}</td></tr>`).join("")}</table>
      <h3>What shrooms make</h3>
      <p>Every recipe that uses a shroom. Potions and inks are brewed at a <b>cauldron</b> (Alchemy). Meals and pet food are cooked at a <b>campfire</b> (Cooking).</p>
      <table class="tbl"><tr><th>Level</th><th>Makes</th><th>From</th><th>Where</th></tr>${made.map(r=>`<tr><td>${r.lvl} ${H.esc(G.SKILLS[r.skill]?.name||r.skill)}</td><td>${H.ico(r.out[0])} ${r.out[1]>1?`${r.out[1]} `:""}${nm(r.out[0])}</td><td>${r.in.map(([k,n])=>`${n} ${nm(k)}`).join(", ")}</td><td>${r.station==="cauldron"?"Cauldron":r.station==="fire"?"Campfire":H.esc(G.STATIONS[r.station]?.name||r.station)}</td></tr>`).join("")}</table>`}},{id:"breeding",title:"Breeding",icon:"🥚",cat:"Skills",body:(G,H)=>{const nm=k=>H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k)),pet=k=>`${H.esc(G.PETS[k].name)}`,hrs=ms=>`${Math.round(ms/36e5)} hours`,R=G.RANKS;const rk=r=>`<b style="color:${R[r].col}">${R[r].mark?`${R[r].mark} `:""}${R[r].name}</b>`;const foods=Object.values(G.RECIPES).filter(r=>/^petfood_/.test(r.id)).sort((a,b)=>a.lvl-b.lvl||a.id.localeCompare(b.id));return`<p><b>Pets come in three ranks:</b> ${rk("ordinary")}, ${rk("greater")} and ${rk("legend")}. Breed two in your island's <b>pet pen</b> to make a better one; hatch eggs in a <b>hatchery</b>.</p>
      <h3>The pet pen</h3>
      <p>Click the pen, put a pair in, and <b>pick one stat from each parent</b>: the baby gets both, so a pair bred for the right stats makes a better one. It shows the baby before you start. Press <b>Breed</b>: the food goes in at once and the clock runs by itself, logged in or not. When you collect, you get the baby <b>and both parents back</b>, so the same pair can go straight back in: the food and the time are the cost. Stopping early gives them back too, but the food is gone.</p>
      <table class="tbl"><tr><th>Put in</th><th>Get</th><th>Food</th><th>Time</th><th>Breeding</th></tr>
        <tr><td>${rk("ordinary")} + ${rk("ordinary")}</td><td>${rk("greater")}: looks like whichever parent you choose, and carries the one stat you pick from each parent, 25% stronger</td><td>${G.BREED.greater.food} ${nm(R.greater.food)}</td><td>${hrs(G.BREED.greater.ms)}</td><td>${G.BREED.greater.lvl}</td></tr>
        <tr><td>${rk("greater")} + ${rk("greater")} of the same kind</td><td>${rk("legend")}: its own pet and powers, plus the one stat you pick from each parent</td><td>${G.BREED.legend.food} ${nm(R.legend.food)}</td><td>${hrs(G.BREED.legend.ms)}</td><td>${G.BREED.legend.lvl}</td></tr></table>
      <table class="tbl"><tr><th>Two Greater&hellip;</th><th>make</th><th>Does</th></tr>${Object.entries(G.LEGEND_OF).map(([base,k])=>`<tr><td>${pet(base)}</td><td>${rk("legend")} ${pet(k)}</td><td>${H.esc(G.petFxText(G.PETS[k].fx))}</td></tr>`).join("")}</table>
      <h3>The hatchery</h3>
      <p>Yahsmeena sells a <b>Hatchery</b>. Put it down on your island, click it, and put an egg in with ${G.BREED.hatch.food} ${nm(R.ordinary.food)}. That is all: it hatches when the clock runs out.</p>
      <p>About one kill in ${Math.round(1/G.BREED.eggDrop).toLocaleString()} drops an egg, and each map has its own. Eggs trade and list on the Exchange.</p>
      <table class="tbl"><tr><th>Egg</th><th>Hatches in</th><th>Into</th><th>Does</th><th>Found</th></tr>${Object.entries(G.EGGS).map(([k,e])=>`<tr><td>${H.ico(k)} ${nm(k)}</td><td>${hrs(e.ms)}</td><td>${pet(e.pet)}</td><td>${H.esc(G.petFxText(G.PETS[e.pet].fx))}</td><td>${e.from.map(s=>H.esc(G.SCENES[s]?.name||s)).join(", ")}</td></tr>`).join("")}</table>
      <h3>Pet food</h3>
      <p>Three kinds, cooked at any campfire, each from more than one pair of ingredients so whatever you are carrying from that part of the game will do.</p>
      <p><b>No pet yet? Cook pet food.</b> While you own no pet, hold no egg and have nothing in the pen or hatchery, every batch you cook trains Breeding a little: ${G.BREED.foodXp.petfood_ordinary} xp for Ordinary, ${G.BREED.foodXp.petfood_greater} for Greater, ${G.BREED.foodXp.petfood_legend} for Legendary. Once you have a pet or an egg, the xp comes from the pen and the hatchery instead.</p>
      <table class="tbl"><tr><th>Cooking</th><th>Makes</th><th>From</th></tr>${foods.map(r=>`<tr><td>${r.lvl}</td><td>${H.ico(r.out[0])} ${r.out[1]} ${nm(r.out[0])}</td><td>${r.in.map(([k,n])=>`${n} ${nm(k)}`).join(", ")}</td></tr>`).join("")}</table>`}},{id:"wizardry",title:"Wizardry",icon:"📜",cat:"Skills",body:(G,H)=>{const nm=k=>H.esc(G.ITEMS[k]?.name||k),E=G.ELEMENTS;const sites=Object.entries(G.ALTAR_SITES).map(([sc,A])=>`<tr><td>${H.esc(G.STATIONS[A.t].name[0].toUpperCase()+G.STATIONS[A.t].name.slice(1))}</td><td>${H.esc(G.SCENES[sc]?.name||sc)}</td></tr>`).join("");const seeds=Object.entries(G.CROPS).filter(([,c])=>c.yields);const tier=C_=>C_.vals.map(v=>C_.what(v)).join(" / ");return`<p><b>Wizardry ties the others together.</b> Seeds from monsters grow on your island (Harvesting), the flowers are brewed into ink at the cauldron (Alchemy), paper is pressed from logs (eight sheets a willow log, fourteen from a Gallows log at Wizardry 90), and pages and scrolls are <b>printed at altars</b> around the world. Every print can fail, like any craft.</p>
      <h3>The altars</h3>
      <p>Each altar prints its own element's pages and scrolls, so printing means travelling:</p>
      <table class="tbl"><tr><th>Altar</th><th>Where</th></tr>${sites}<tr><td><b>The Nexus</b></td><td>The Deep Wild</td></tr></table>
      <p><b>The Nexus</b> is the best altar in the game, in the most dangerous place: it prints what every altar prints, <b>${G.NEXUS.mult}× the pages</b> (a wand or a Magic Bag still comes out one at a time), for <b>${Math.round((G.NEXUS.xp-1)*100)}% more Wizardry xp</b>. Anyone can find you there.</p>
      <h3>Seeds and ink</h3>
      <table class="tbl"><tr><th>Harvesting</th><th>Plant</th><th>Grows</th><th>Brews</th></tr>${seeds.map(([k,c])=>`<tr><td>${c.lvl}</td><td>${H.ico(k)} ${nm(k)}</td><td>${H.ico(c.yields)} ${nm(c.yields)}</td><td>${H.ico(`ink_${Object.keys(E).find(e=>E[e].bloom===c.yields)}`)} ${nm(`ink_${Object.keys(E).find(e=>E[e].bloom===c.yields)}`)}</td></tr>`).join("")}</table>
      <p>Seeds drop from the monsters of each element's home, and they are rare: about one kill in a hundred and twenty-five (the Grim Lich in the Deep Wild, ten times that). A harvested seed crop gives two seeds back, and one harvest in ten gives three, so every plot doubles itself and a farm grows by one plot a harvest. Storm ink is brewed from the Stormcorn that already grows on your island; Arcane ink from sulky sporecaps.</p>
      <h3>Utility pages</h3>
      <p>Buffs, one at a time: reading a new one replaces the old. The clock runs only outside. <b>Your Wizardry sets the tier</b> when you read it: I below ${G.MAGIC.tierAt[0]}, II from ${G.MAGIC.tierAt[0]}, III from ${G.MAGIC.tierAt[1]}.</p>
      <table class="tbl"><tr><th>Wizardry</th><th>Page</th><th>Altar</th><th>Tier I / II / III</th><th>Lasts</th></tr>${Object.entries(G.CHARMS).sort((a,b)=>a[1].lvl-b[1].lvl).map(([k,C_])=>`<tr><td>${C_.lvl}</td><td>${H.ico(`scroll_${k}`)} ${H.esc(C_.name)}</td><td>${H.el(C_.el)} ${E[C_.el].name}</td><td>${H.esc(tier(C_))}</td><td>${C_.mins} min</td></tr>`).join("")}</table>
      <p><b>Homeward</b> (Sun altar, Wizardry 10) puts you on your own island.</p>
      <h3>Waystones</h3>
      <p>Four, spaced across the world, at a fork or the far end of a branch, so you still walk to everything between. Printed at the Storm altar. Not in the Wilderness, not inside a run, not within 10 seconds of being hit.</p>
      <table class="tbl"><tr><th>Wizardry</th><th>Waystone</th></tr>${Object.entries(G.WAYSTONES).map(([k,Wy])=>`<tr><td>${Wy.lvl}</td><td>${H.ico(k)} ${H.esc(Wy.name)}</td></tr>`).join("")}</table>
      <p>Wands and Magic Bags are made at the Arcane altar in the Yard, from logs, ink and the gems that turn up in ore.</p>`}},{id:"archery",title:"Archery",icon:"🏹",cat:"Skills",body:G=>`<p><b>A second way to fight.</b> Hold a bow and every roll in the fight reads your Archery level instead of Combat &mdash; accuracy, max hit and defence &mdash; and every point of damage pays Archery the xp Combat would have had. Hitpoints trains alongside it at <b>a third of melee's rate</b>: you are not the one getting hit. Your combat level takes the higher of the two.</p>
      <h3>Getting started</h3>
      <p>Brutus sells a <b>rough shortbow</b>, a <b>rough quiver</b> and <b>bone arrows</b>, all Archery 1. Bow in the weapon hand, quiver in the offhand (it takes the shield's place), click the arrows in your bag to load it. Arrows stack to 1,000 in the bag.</p>
      <h3>How a bow fights</h3>
      <ul><li><b>You shoot from where you stand.</b> A shortbow reaches ${G.ITEMS.logs_shortbow.launcher.range} tiles, a longbow ${G.ITEMS.logs_longbow.launcher.range}; click something inside that and you never move. Click something further and you walk only to the edge of your reach.</li>
      <li><b>One arrow a shot, hit or miss, and only from the quiver.</b> Arrows in your bag do not fire: load them into the quiver first. When the quiver is empty the bow stops.</li>
      <li><b>The arrow is the damage.</b> Every arrow adds half its strength to what lands, from +${Math.round(G.ITEMS.bone_arrow.ammo.str*G.AMMO_SHARE)} for bone to +${Math.round(G.ITEMS.singularity_arrow.ammo.str*G.AMMO_SHARE)} for singularity; the bow is speed and reach. Each arrow has its own Archery level to draw.</li>
      <li><b>Big targets are hard to miss.</b> Arrows do a fifth more to large monsters and bosses.</li>
      <li><b>Stand and shoot.</b> With a loaded quiver, when your target dies you draw on the next one of the same kind inside your reach without a click, and the fight's idle timer runs eight minutes instead of three. A sword still needs you at the keyboard.</li>
      <li><b>Some things only an arrow reaches.</b> Thunder Geese sit over the tear in the Thunderhead's floor, on water nobody can walk to. A sword is told so; a bow just shoots.</li>
      <li><b>In the wild, first blood goes to the bow.</b> An archer gets free shots while a sword closes four to six tiles &mdash; and shoots back from range once it arrives, at Archery's defence.</li></ul>
      <p>Everything a bow fires is made at the <a data-wiki="guides/fletching">fletching table</a>.</p>`},{id:"gems",title:"Gems",icon:"💎",cat:"Skills",body:(G,H)=>{if(!H.WIKI)return"<p>Open this page from the game to see where every gem comes from.</p>";const nm=k=>H.wl(`items/${k}`,`${H.ico(k)} ${H.esc(H.ITEMS[k]?.name||k)}`);const shut=r=>H.ITEMS[r.out[0]]?.held||H.SKILLS[r.skill]?.held;const boost=Object.values(G.PETS).filter(p=>p.fx?.gem&&!p.held).map(p=>`a <b>${H.esc(p.name)}</b> (+${p.fx.gem}%)`);const pct=p=>`1 in ${Math.round(1/p)}`;const gem=g=>{const rocks=H.WIKI.gemFrom?.[g.key]||[],mobs=H.dropsOf(g.key);const uses=Object.values(G.RECIPES).filter(r=>r.in.some(([k])=>k===g.key)&&!shut(r)).filter((r,i,a)=>a.findIndex(x=>x.out[0]===r.out[0])===i);return`<h3>${H.ico(g.key)} ${H.wl(`items/${g.key}`,H.esc(g.name))}</h3>
          <table class="tbl"><tr><th>Rock</th><th>Where</th><th>Mining</th><th>Chance</th></tr>${rocks.length?rocks.map(s=>`<tr><td>${H.esc(s.obj)} (${nm(s.ore)})</td><td>${H.areaLink(s.scene)}</td><td>${s.lvl}</td><td>${pct(s.p)} ores</td></tr>`).join(""):`<tr><td colspan="4">No rock you can reach turns one up yet.</td></tr>`}</table>
          ${mobs.length?`<p><b>Also dropped by</b> ${mobs.map(d=>`${H.wl(`monsters/${d.mob}`,H.esc(H.MOBS[d.mob].name))} (${d.ch==null?"always":pct(d.ch)})`).join(", ")}.</p>`:""}
          <p><b>Tips</b> ${g.tips.map(nm).join(" and ")} for <b>+${g.str}</b> arrow strength (Fletching ${g.lvl}).${uses.length?` <b>Used in</b> ${uses.map(r=>nm(r.out[0])).join(", ")}.`:""}</p>`};return`<p><b>Four gems, all from Mining.</b> Every ore you get has a small chance to come with a gem as well: <b>${pct(G.GEMS[0].drop)}</b>, the same for every gem and at any level. Which gem depends on the ore: the cheap ores give rubies, the top ores give opals.</p>
        <table class="tbl"><tr><th>Gem</th><th>Mined out of</th><th>Chance</th></tr>${G.GEMS.map(g=>`<tr><td>${nm(g.key)}</td><td>${g.ores.map(nm).join(", ")}</td><td>${pct(g.drop)} ores</td></tr>`).join("")}</table>
        <p><b>More gems:</b> the <b>${H.esc(G.CHARMS.stonesense.name)}</b> page (Wizardry ${G.CHARMS.stonesense.lvl}) makes them turn up ${G.CHARMS.stonesense.vals.join("/")}% more often by tier${boost.length?`, and so does ${boost.join(" or ")} following you`:""}. A rock gives the same chance on every ore, so a vein that never runs dry is the best place to stand.</p>
        ${G.GEMS.map(gem).join("")}`}},{id:"gembag",title:"The gem bag and the Gem Sorter",icon:"💎",cat:"Going further",body:(G,H)=>{const S=G.GEMSET,nm=k=>H.wl(`items/${k}`,`${H.ico(k)} ${H.esc(H.ITEMS[k]?.name||k)}`),tix=n=>`${n.toLocaleString()} tickets`;const odds=(lo,hi)=>{let p=0;for(let r=lo;r<=hi;r++)p+=G.gemOdds(r);p*=100;return p<1?`${p.toFixed(1)}%`:`${Math.round(p)}%`};const sgn=r=>`${r>0?"+":""}${r}%`,side=w=>S.list.filter(g=>g.where===w);const row=g=>`<tr><td>${nm(g.k)}</td><td>${H.esc(g.does)}</td><td>${g.skill?H.esc(H.SKILLS?.[g.skill]?.name||g.skill):"monsters of level "+S.dropLvl+"+"}</td></tr>`;return`<p><b>Gems are small permanent bonuses you carry with you.</b> Find one, have the Gem Sorter roll it a bonus, and put it in your <b>gem bag</b>, which works wherever you are. Open the bag from the <b>Gems</b> button on your inventory; it pops open beside it.</p>
        <h3>The gem bag</h3>
        <p>Two sides of ${S.bag.max} settings each: <b>Combat</b> gems on one side, <b>Skilling</b> gems on the other, and a gem only fits its own side. ${S.bag.start===1?"One setting on each side is open":`${S.bag.start} settings on each side are open`} from the start; the rest open for tickets, each side on its own: ${S.bag.price.map(tix).join(", then ")}.</p>
        <p>Only a <b>sorted</b> gem goes in. Taking one out gives it back <b>as it was</b>, roll and all, so you can rearrange the bag, trade a sorted gem or sell it on the Market. <b>Only the best ${S.perType} of any one gem count</b>: a third ruby adds nothing, so fill the bag with different stones.</p>
        <h3>The Gem Sorter</h3>
        <p>A jeweller's bench in the Yard's north court. Stand by it and it will <b>sort</b> a gem (roll its bonus) for <b>${tix(S.cost)}</b> a roll, <b>re-roll</b> a sorted one for the same, or <b>buy any gem back</b> for ${tix(S.sell)}, whatever its roll. A roll lands between <b>${sgn(S.roll[0])}</b> and <b>${sgn(S.roll[1])}</b>, and the higher it is, the rarer it is. A negative roll is exactly that much worse.</p>
        <table class="tbl"><tr><th>Band</th><th>Roll</th><th>Chance</th></tr>${G.GEM_BANDS.map(([n,lo,hi])=>`<tr><td><b>${n}</b></td><td>${lo===hi?sgn(lo):`${sgn(lo)} to ${sgn(hi)}`}</td><td>${odds(lo,hi)}</td></tr>`).join("")}</table>
        <p>A perfect ${sgn(S.roll[1])} is about <b>1 in ${Math.round(1/G.gemOdds(S.roll[1]))}</b> rolls, and the room hears about it when somebody lands one.</p>
        <h3>Finding gems</h3>
        <p>From level <b>${S.dropLvl}</b> in a skill, every action has a 1 in ${Math.round(1/S.drop).toLocaleString()} chance of turning up that skill's gem. Monsters of level ${S.dropLvl} or more drop a combat gem now and then, and a boss more often. Every gem found is unsorted; they trade and bank like anything else, and a sorted one keeps its roll when it changes hands.</p>
        <h3>Combat gems</h3>
        <table class="tbl"><tr><th>Gem</th><th>Does</th><th>From</th></tr>${side("gear").map(row).join("")}</table>
        <h3>Skilling gems</h3>
        <table class="tbl"><tr><th>Gem</th><th>Does</th><th>From</th></tr>${side("case").map(row).join("")}</table>`}},{id:"tinkering",title:"Tinkering and World Projects",icon:"🔧",cat:"Skills",body:(G,H)=>{const T=G.TINK,P=T.parts,num=n=>Number(n).toLocaleString();const parts=o=>Object.entries(o||{}).filter(([p,n])=>n>0).map(([p,n])=>p==="tickets"?`${num(n)} tickets`:`${num(n)} ${H.esc(P[p]?.name||p)}`).join(", ");const gad=Object.entries(G.GADGETS).filter(([,g])=>g.item!==false).sort((a,b)=>a[1].lvl-b[1].lvl);const proj=Object.entries(G.PROJECTS);return`<p><b>Tinkering turns junk into things.</b> Talk to <b>${H.esc(T.npc)}</b> at her Scrap Bench by Bronny's worksite in the Yard. Salvage what you don't need into <b>parts</b>, build <b>gadgets</b> out of parts and a ticket fee, and give parts to the <b>World Projects</b> the whole server builds together.</p>
        <h3>Parts</h3>
        <p>Four kinds, kept in a pouch of their own: they take no bag space, and Bom won't buy them.</p>
        <table class="tbl"><tr><th>Part</th><th>Worth</th><th>Mostly from</th></tr>
          <tr><td><b>${P.scrap.name}</b></td><td>${P.scrap.pv}</td><td>anything: drops, loot, the leftovers of everything else</td></tr>
          <tr><td><b>${P.gears.name}</b></td><td>${P.gears.pv}</td><td>metal: gear, tools, bars and ore</td></tr>
          <tr><td><b>${P.sparks.name}</b></td><td>${P.sparks.pv}</td><td>magic: spell pages, ink, wands, and magical drops like stardust and voidglass</td></tr>
          <tr><td><b>${P.relic.name}</b></td><td>${P.relic.pv}</td><td>anything Bom would pay ${num(T.relicAt)} or more for</td></tr></table>
        <h3>Salvage</h3>
        <p>An item salvages into parts worth <b>${Math.round(T.rate*100)}%</b> of what Bom would pay you for it, and something he pays nothing for (a feather, a pit) is still worth a little Scrap. A stack is added up before it's rounded down, so a pile of junk is worth more than one piece of it. <b>Salvage the lot</b> takes only plain drops and loot, never gear, food or anything rare; those go one at a time. Salvaging pays Tinkering xp: half an item's part value, but never more than ${T.salvXpCap} for one item, so a rare is not a shortcut. Building a gadget pays ${T.buildXpLvl} xp for each level it needs. Money, keys, eggs, pets and quest or event items can't be salvaged.</p>
        <h3>Gadgets</h3>
        <p>Built at the Scrap Bench from parts plus a ticket fee. A timed gadget runs only outside (and in the Guild), like a drink, and you can run one of each at once; the others are used on the spot. Every build has a ${Math.round(T.masterwork*100)}% chance of a <b>Masterwork</b>: twice as many. Gadgets are items, so they trade on the Market.</p>
        <table class="tbl"><tr><th>Level</th><th>Gadget</th><th>Does</th><th>Costs</th></tr>${gad.map(([id,g])=>`<tr><td>${g.lvl}</td><td>${H.wl(`items/tk_${id}`,`${H.ico(`tk_${id}`)} ${H.esc(g.name)}`)}${g.n>1?` ×${g.n}`:""}</td><td>${H.esc(g.does)}${g.mins?` (${g.mins} min)`:""}</td><td>${parts(g.parts)}, ${num(g.fee)} tickets</td></tr>`).join("")}</table>
        <p><b>The automation tools</b> (Auger, Chainsaw, Auto-Reel) keep you gathering with no clicks and walk you to the next rock, tree or spot of the same kind. Whenever nobody has touched the game for a few minutes they work at ${Math.round(T.autoRate*100)}% speed, and nothing gathers while you're logged out.</p>
        <h3>World Projects</h3>
        <p>Broken things around the world that the whole server rebuilds together. Anyone can give parts and tickets to the current stage at its board; when a stage is full, somebody with the Tinkering level it asks for has to stand at it and finish the job. Everybody who gave gets that build's <b>Builder's Pin</b>, and the Builders board on the Hiscores counts what each person gave. Each project has three stages:</p>
        ${proj.map(([pid,p])=>`<h3>${H.ico(`pin_${pid}`)} ${H.esc(p.name)} <small>${H.esc(p.where)}</small></h3><p>${H.esc(p.blurb)}</p><table class="tbl"><tr><th>Stage</th><th>Needs</th><th>Finish at</th><th>Does</th></tr>${p.tiers.map(t=>`<tr><td><b>${H.esc(t.name)}</b></td><td>${parts(t.need)}</td><td>Tinkering ${t.finish}</td><td>${H.esc(t.does)}</td></tr>`).join("")}</table>`).join("")}`}},{id:"outfitters",title:"Archery and magic gear: the outfitters",icon:"🧥",cat:"Going further",body:(G,H)=>{const O=G.OUTFIT,tix=n=>`${n.toLocaleString()} tickets`,nm=k=>H.wl(`items/${k}`,`${H.ico(k)} ${H.esc(G.ITEMS[k]?.name||k)}`);const setTable=shop=>{const style=O.style[shop];return`<table class="tbl"><tr><th>Level</th><th>Set</th><th>Defence (whole set)</th><th>Whole set costs</th></tr>${O.tiers[style].map(([key,name,lvl])=>{const ks=Object.keys(O.slots).map(s=>`${key}_${s}`),def=ks.reduce((a,k)=>a+(G.ITEMS[k]?.def||0),0),cost=ks.reduce((a,k)=>a+(G.outfitShelf(shop).find(r=>r.k===k)?.price||0),0);return`<tr><td>${lvl}</td><td>${ks.map(k=>H.ico(k)).join("")} <b>${H.esc(name)}</b></td><td>${def}</td><td>${tix(cost)}</td></tr>`}).join("")}</table>`};const weapons=shop=>G.outfitShelf(shop).filter(r=>r.kind==="weapon").map(r=>`${nm(r.k)} (${tix(r.price)})`).join(", ");return`<p><b>Two outfitters keep stalls out in the world:</b> <b>${H.esc(O.npc.ranger)}</b> dresses archers, in ${H.areaLink(O.at.ranger.scene)}, and <b>${H.esc(O.npc.mage)}</b> dresses mages, on ${H.areaLink(O.at.mage.scene)}. Each sells five-piece sets of armour (helm, body, legs, gloves and boots) in five tiers, the weapons of her style, and buys that gear back.</p>
        <h3>What the armour does</h3>
        <p>It has <b>half the defence of plate</b> at the same level, but every piece adds damage for its style, and <b>a whole set is +10%</b>: the body the most, then the legs, the helm and gloves, the boots least. The bonus only counts while you fight in that style: a ranger's set does nothing for a sword or a wand. <b>Archers' pieces also make you faster on your feet</b>, up to <b>6%</b> for a whole set. It needs your Archery or Magic level to wear, and the anvil doesn't reforge it.</p>
        <h3>${H.esc(O.npc.ranger)}: archery</h3>${setTable("ranger")}
        <h3>${H.esc(O.npc.mage)}: magic</h3>${setTable("mage")}
        <h3>Weapons, the expensive way</h3>
        <p>They also sell every bow and quiver, or every wand and Magic Bag, but at a steep price on purpose: making your own with Fletching or Wizardry is far cheaper. Wren: ${weapons("ranger")}.</p><p>Morwenna: ${weapons("mage")}.</p>
        <h3>Reforging</h3>
        <p><b>The armour reforges at an anvil like plate</b>: each piece takes the same bars, and the same Smithing, as the plate piece at its level. See <a data-wiki="guides/smithing">Smithing</a> for the odds. Bows and quivers reforge with their wood, wands with theirs and Magic Bags with spell paper, as they always have.</p>
        <h3>Selling back</h3>
        <p>Each buys her own style's armour and weapons for what Bom would pay: an eighth of the shelf price, and never more than ${tix(G.GEAR_SELL_MAX)} for a piece.</p>`}},{id:"fletching",title:"Fletching and archery",icon:"🏹",cat:"Skills",body:(G,H)=>{const rs=Object.values(G.RECIPES).filter(r=>r.skill==="fletching").sort((a,b)=>a.lvl-b.lvl);const nm=k=>H.esc(G.ITEMS[k]?.name||k);const bows=rs.filter(r=>G.ITEMS[r.out[0]]?.launcher),arrows=rs.filter(r=>G.ITEMS[r.out[0]]?.ammo),quivers=rs.filter(r=>G.ITEMS[r.out[0]]?.pouch);const row=r=>`<tr><td>${r.lvl}</td><td>${H.ico(r.out[0])} ${H.wl(`items/${r.out[0]}`,nm(r.out[0]))}${r.out[1]>1?` <small>x${r.out[1]}</small>`:""}</td><td>${r.in.map(([k,n])=>`${n} × ${nm(k).toLowerCase()}`).join(" + ")}</td></tr>`;return`<p><b>The fletching table stands in the Yard, in the north court beside the furnace and the anvil.</b> Everything here is made at it, except arrowheads, which are <a data-wiki="guides/smithing">smithing</a> at the anvil two tiles away.</p>
      <p><b>The Wild Bench</b> is fletching's Nexus: it stands in the grove in the north-east of the Wilderness, beside the Ancient yew, and fletches everything the table does, <b>${G.NEXUS.mult}&times; as much</b>, for <b>${Math.round((G.NEXUS.xp-1)*100)}% more Fletching xp</b>. (That is shafts and arrows: a bow or a quiver still comes out one at a time, and so does the Long Count.) Anyone can find you there.</p>
      <p><b>An arrow is three things from three places.</b> A <b>shaft</b> from any log (a better tree just gives more per log), a <b>head</b> hammered from a bar, and a <b>feather</b> off something with plumage &mdash; one to three, about a third of the time, from a Chicken, Highwayman, Understudy, Angel, Thunder Goose or Fat Lady, so there is a bird for every level. A better tree gives more shafts per log, up to fifty from the Deep Wild's Gallows logs at Fletching 92. Fletching cannot make one on its own, and that is the point.</p>
      <h3>The bow is speed and reach; the arrow is damage</h3>
      <p>Every wood makes a <b>shortbow</b> (quick, reaches ${G.ITEMS.logs_shortbow.launcher.range} tiles) and a <b>longbow</b> (slow, reaches ${G.ITEMS.logs_longbow.launcher.range} and hits harder). The arrow you load adds half its strength to every hit, from +${Math.round(G.ITEMS.bone_arrow.ammo.str*G.AMMO_SHARE)} for bone to +${Math.round(G.ITEMS.singularity_arrow.ammo.str*G.AMMO_SHARE)} for singularity. So the real choice is a good bow with cheap arrows, or a cheap bow and a quiver of the good ones.</p>
      <p><b>A bow with nothing to fire is not a weapon.</b> One arrow is spent per shot, hit or miss.</p>
      <h3>Quivers</h3>
      <p>A quiver wears the <b>offhand</b> &mdash; so a bow is a two-handed choice against a shield &mdash; and holds one kind of arrow in bulk, from ${G.FLETCH.quiverCap[0]} for rough up to ${G.FLETCH.quiverCap.at(-1)} for bogwood. Click arrows in your bag to load it. A bow shoots only what is in the quiver, so when it runs out, load more. Clicking a different kind of arrow swaps them.</p>
      <h3>Gems</h3>
      <p>Four stones turn up in ore, one ore in ${Math.round(1/G.GEMS[0].drop)} of the kinds below, and each tips the arrows of the metals it comes out of. The <a data-wiki="guides/gems">Gems</a> page lists every rock and where it is.</p>
      <table class="tbl"><tr><th>Gem</th><th>Mined out of</th><th>Tips</th><th>Adds</th></tr>
        ${G.GEMS.map(g=>`<tr><td>${H.ico(g.key)} ${nm(g.key)}</td><td>${g.ores.map(o=>nm(o)).join(", ")}</td><td>${g.tips.map(t=>nm(t)).join(", ")}</td><td>+${g.str}</td></tr>`).join("")}
      </table>
      <h3>The ladder</h3>
      <table class="tbl"><tr><th>Fletching</th><th>Makes</th><th>From</th></tr>${rs.map(row).join("")}</table>
      <p><b>Arrowheads</b> are hammered at the anvil at each metal's own Smithing gate, fifteen to a bar.</p>
      <p><b>Fletching makes it, <a data-wiki="guides/archery">Archery</a> draws it.</b> Every bow, quiver and arrow carries an Archery level to use, which sits at the Fletching level to make it &mdash; except the rough shortbow, the rough quiver and bone arrows, which are Archery 1 and on Brutus's shelf.</p>
      <p><b>The Long Count</b> at 99 wants a singularity core &mdash; the same one-in-two-thousand drop the top melee weapons want &mdash; so the two ladders end on the same chase.</p>`}},{id:"agility",title:"Agility",icon:"🏃",cat:"Skills",body:`<p><b>The Run is an obstacle course</b>, up a rope ladder in the north of the Yard. You go round it: each obstacle pays, and finishing a full lap pays far more than the parts do.</p>
      <table class="tbl"><tr><th>What</th><th>Gives</th></tr>
        <tr><td>Each obstacle cleared</td><td>12 xp</td></tr>
        <tr><td>Clearing one perfectly</td><td>+10 xp on top</td></tr>
        <tr><td>Finishing a lap</td><td>150 xp, and more when others are running</td></tr>
        <tr><td>Marks picked up on the way</td><td>13 tickets each</td></tr>
      </table>
      <p><b>What it buys is movement speed, everywhere.</b> It climbs steadily with the level &mdash; about <b>+5% at 50</b> and <b>+10% at 99</b> &mdash; and it applies to every step you take for the rest of the game: every walk to a rock, a tree, a fishing spot or the bank.</p>
      <p><b>That is the argument for it.</b> Agility makes nothing and sells nothing, so it looks like the skill you can skip. What it actually does is shorten every other skill you will ever train.</p>
      <p><b>A lap is worth more with company</b>, so it is one of the few things in the game that rewards a crowd rather than tolerating one.</p>
      <p><b>Your best lap is recorded</b>, which is the other reason to keep going round.</p>`},{id:"smoking",title:"Smoked fish",icon:"🐟",cat:"Skills",body:(G,H)=>{const rows=Object.entries(G.ITEMS).filter(([k,it])=>k.startsWith("s")&&it.meal&&G.ITEMS[k.slice(1)]).map(([k])=>{const raw=k.slice(1),sm=Object.values(G.RECIPES).find(r=>r.out[0]===k);const cook=Object.values(G.RECIPES).find(r=>r.out[0]===`c${raw}`&&r.skill==="cooking");const coal=(sm?.in.find(([i])=>i==="charcoal")||[,1])[1];const fx=G.ITEMS[k].meal.fx,says=Object.entries(fx).map(([f,v])=>`+${Math.round(v*100)}% ${{rare:"rare drops",tough:"toughness",speed:"speed",tix:"tickets",zdrop:"ZCoin drops",bite:"bite rate"}[f]||f}`).join(" and ");return{k,raw,lvl:sm?.lvl??0,cookLvl:cook?.lvl,coal,heal:G.ITEMS[k].heal,says}}).sort((a,b)=>a.lvl-b.lvl);const best=Math.max(...rows.map(r=>r.heal));return`<p><b>Smoking is cooking with charcoal.</b> ${rows.length} fish can be smoked instead of plainly cooked. A smoked fish heals more, sells for far more, and &mdash; the reason to bother &mdash; gives a twenty-minute buff.</p>
      <p>Do it at <b>any fire or range</b>, with the fish and the charcoal in your bag. You do not switch anything on: the fire always makes the best thing it can, so it smokes while you have charcoal and drops back to plain cooking when you run out.</p>
      <table class="tbl"><tr><th>Smoked</th><th>Smoke at</th><th>Coal</th><th>Heals</th><th>For 20 minutes</th></tr>
        ${rows.map(r=>`<tr><td>${H.ico(r.k)} ${H.wl(`items/${r.k}`,H.esc(G.ITEMS[r.k].name))}</td><td>Cooking ${r.lvl}</td><td>${r.coal}</td><td>${r.heal}</td><td>${H.esc(r.says)}</td></tr>`).join("")}
      </table>
      <p><b>A smoke can spoil.</b> One in ten fails, at every level, and the fish and the charcoal go with it. Cooking the same fish plainly is unaffected. The fire tells you the odds before you start.</p>
      <p><b>Cooking is usually what holds you back, not fishing.</b> A fish comes out of the water long before you can smoke it &mdash; a smoke sits about five levels above its own plain cook.</p>
      <p><b>Nothing here buffs experience</b>, and that is deliberate &mdash; a stacked xp buff would be a multiplier on the one thing the Tower exists to pay. The best smoke heals <b>${best}</b>.</p>`}},{id:"buffs",title:"Food, drinks and luck",icon:"🍺",cat:"Going further",body:`<p><b>Eating heals you. Some food also buffs you for twenty minutes, and a drink for ten.</b> You can have one meal and one drink running at once, so the good combination is a dinner plus a drink, not two dinners.</p>
      <h3>Dinners &mdash; 20 minutes</h3>
      <table class="tbl"><tr><th>Dish</th><th>Heals</th><th>Gives</th></tr>
        <tr><td>Winner's chicken dinner</td><td>6</td><td>+10% tickets</td></tr>
        <tr><td>Steak dinner</td><td>8</td><td>+10% speed</td></tr>
        <tr><td>High roller's chops</td><td>10</td><td>+25% rare drops</td></tr>
        <tr><td>Fisherman's platter</td><td>14</td><td>+10% bite rate and +10% tickets</td></tr>
      </table>
      <p>The <a data-wiki="guides/smoking">smoked fish</a> are dinners too, and they heal far more &mdash; up to 48. That page has their buffs.</p>
      <h3>Drinks &mdash; 10 minutes</h3>
      <table class="tbl"><tr><th>Drink</th><th>Gives</th></tr>
        <tr><td>House lager</td><td>+5% tickets</td></tr>
        <tr><td>Top-shelf whiskey</td><td>+15% speed, but <b>&minus;10% toughness</b></td></tr>
        <tr><td>The Safety Net</td><td>+20% toughness</td></tr>
        <tr><td>Champagne</td><td><b>+50% ZCoin drop chance</b></td></tr>
      </table>
      <p>Whiskey is the only thing in the game that makes you worse at something. Champagne is the one to drink before a long session outside.</p>
      <h3>Luck</h3>
      <p>A <b>Lucky clover</b> turns up while you fish. Click it and your next <b>15 kills or catches</b> are lucky &mdash; a real ZCoin is 5% more likely on each. It counts down by events, not by time, so there is no rush to use it.</p>
      <p><b>None of this touches the casino.</b> Buffs work outside only; no drink, dinner or clover can move the odds at a table.</p>`},{id:"zcoins",title:"Finding ZCoins",icon:"💎",cat:"Money",body:`<p><b>Real ZCoins drop in the world.</b> Not tickets &mdash; the actual currency from eastcoin.vip. They are rare on purpose and there is no way to buy them with tickets, in either direction.</p>
      <p><b>Fishing drops them</b> at roughly <b>one cast in six hundred</b>, creeping up slightly with the better fish &mdash; a sardine is about 1 in 800, a thunder squid about 1 in 556. It is close enough to flat that you should fish wherever you actually enjoy fishing.</p>
      <p><b>Fighting drops them too</b>, scaled to what you killed, so the Thunderhead pays better than the Yard.</p>
      <p><b>A big one lands about one time in twenty</b>, worth five of the ordinary find.</p>
      <p>Take a ZCoin to <a data-wiki="npcs/Bom Trady">the Prize Counter</a> and it goes straight onto your real balance on the site.</p>
      <p><b>Nothing you can buy improves the rate</b> beyond the drop buffs the game already hands out, and no world buff can ever touch the casino's odds. The two are deliberately separate.</p>`},{id:"dying",title:"Dying",icon:"💀",cat:"Starting out",body:`<p><b>You keep everything you are wearing and carrying.</b> Dying costs you tickets, not gear &mdash; there is no gravestone to run back to and nothing to lose permanently.</p>
      <p><b>What it costs is a share of the tickets on you, capped by where you died.</b> The cap is what matters: the deeper the zone, the more a death stings, but it is never everything.</p>
      <table class="tbl"><tr><th>Where</th><th>You lose</th><th>At most</th></tr>
        <tr><td>The Yard</td><td>5%</td><td>250</td></tr>
        <tr><td>The Gloam</td><td>10%</td><td>1,000</td></tr>
        <tr><td>The Lantern Mire</td><td>10%</td><td>2,000</td></tr>
        <tr><td>The Boneyard</td><td>10%</td><td>3,500</td></tr>
        <tr><td>Cloudreach</td><td>10%</td><td>5,000</td></tr>
        <tr><td>The Thunderhead</td><td>10%</td><td>6,000</td></tr>
        <tr><td>The Vault</td><td>10%</td><td>8,000</td></tr>
        <tr><td>The Trailer Park</td><td>10%</td><td>9,000</td></tr>
      </table>
      <p><b>Bank your tickets before a long trip out</b> and a death costs you almost nothing &mdash; the percentage is of what you are carrying.</p>
      <p><b>The Wilderness is different.</b> Other players can attack you there and the rules are its own; see the signs on the way in.</p>
      <p><b>Eat before you need to.</b> There is no potion and no auto-heal &mdash; cooked fish is the entire system, and the fight does not pause while you find some.</p>`},{id:"jobs",title:"Today's jobs",icon:"📋",cat:"Money",body:`<p><b>Three jobs a day, from a pool of seventy</b>, on the task board inside the casino. They reset every day and they are the same three for you until you claim them.</p>
      <p>They are things you were going to do anyway &mdash; gather fifty logs, catch twenty sardines, kill some number of something &mdash; so the trick is reading them <b>before</b> you go out, not after.</p>
      <p><b>They count themselves.</b> Nothing to start and nothing to hand in: fishing a sardine counts a sardine job wherever you are. You go back to the board only to take the money.</p>
      <p><b>The pool is level-aware.</b> Jobs you have no chance at will not be handed to you, so what you see is doable today.</p>
      <p>Pays in tickets, and scales with what it asked for &mdash; a few hundred for an easy gather, more for the ones that send you somewhere unpleasant.</p>`},{id:"vip",title:"VIP",icon:"👑",cat:"Money",body:`<p><b>VIP is lifetime turnover, not a purchase.</b> It counts every ticket you have ever staked, so it goes up by playing and never goes down.</p>
      <p>What it buys is a <b>standing discount at the Prize Counter</b> &mdash; everything Bom sells, permanently cheaper.</p>
      <table class="tbl"><tr><th>Rank</th><th>Staked</th><th>Off at the counter</th></tr>
        <tr><td>Guest</td><td>&mdash;</td><td>&mdash;</td></tr>
        <tr><td>Bronze</td><td>25,000</td><td>2%</td></tr>
        <tr><td>Silver</td><td>100,000</td><td>4%</td></tr>
        <tr><td>Gold</td><td>400,000</td><td>6%</td></tr>
        <tr><td>Platinum</td><td>1,500,000</td><td>8%</td></tr>
        <tr><td>Diamond</td><td>5,000,000</td><td>10%</td></tr>
      </table>
      <p><b>Those numbers are turnover, which climbs faster than it sounds.</b> The same tickets get staked again every time you re-bet them, so Bronze is a session or two rather than a fortune.</p>`},{id:"bank",title:"The bank",icon:"🏛️",cat:"Money",body:`<p><b>A booth holds 200 different items</b> and everything in it is safe &mdash; a death never touches your bank.</p>
      <p><b>Click to move one thing; the 1 / 5 / 10 / All selector at the foot decides how many.</b> Or <b>shift-click to move a whole stack</b> in either direction, which is the same gesture the trade window uses.</p>
      <p><b>Sort it</b> by Recent, A&ndash;Z, Value or Amount &mdash; the chips sit under the search box, and your choice is remembered. The header shows what the whole bank is worth, and hovering any stack tells you what that stack is worth.</p>
      <p><b>Deposit bag</b> and <b>Deposit worn</b> empty you out in one click. Neither will take your tickets: those stay on you always, and cannot be banked, dropped or given away.</p>
      <p><b>Your bag is the thing worth upgrading.</b> Bom sews on extra pockets &mdash; five of them, each dearer than the last, from 50,000 up to 400,000 tickets, taking you from 25 slots to 30. The button is in the bank as well as at his counter, because "I need more room" is a thought you have with the bank open.</p>
      <p><b>The Market delivers here.</b> Anything you buy, and anything your sell offers earn, lands in your bank whether you are online or not. See <a data-wiki="guides/trading">Trading</a>.</p>`},{id:"trading",title:"Trading and the Market",icon:"🤝",cat:"Money",body:`<h3>Face to face</h3>
      <p><b>Click another player and offer a trade.</b> Both sides put things up, both sides see exactly what is on the table, and both have to accept. <b>Shift-click offers a whole stack</b> rather than one of a thing.</p>
      <p><b>Tickets can be traded</b>, but nothing else about them changes: they still cannot be banked or dropped.</p>
      <p>The swap is worked out in full on the server before either side is touched, so the old trick of offering something and getting rid of it before the trade completes has nowhere to land.</p>
      <h3>The Market</h3>
      <p><b>The stall in the Yard is an offer book, not a shop.</b> You post what you will sell and at what price; somebody else posts what they will pay. When the two meet it happens &mdash; whether either of you is online.</p>
      <p><b>Everything lands in your bank.</b> What you buy, and what your sales earn, is waiting there next time you log in. Nothing to collect, nothing expires.</p>
      <p><b>The house takes 1% of each sale.</b> That is the only fee, and it is there to stop tickets piling up forever.</p>
      <p><b>It sells out of your bag and your bank together</b>, so you do not have to fetch things before listing them.</p>
      <p><b>Gear cannot be sold to other players yet.</b> A reforged piece belongs to whoever reforged it &mdash; a known limitation and a real project to fix, not an oversight.</p>`},{id:"islands",title:"Your island",icon:"🏝️",cat:"Going further",body:(G,H)=>`<p><b>Charon keeps a cart in the Yard</b>, a few steps out of the casino's front door, and everyone gets an island. It is yours, it keeps growing things while you are logged off, and you decide whether anybody else can visit.</p>
      <p><b>Three sizes, and every one of them is big.</b> You start with the first and buy the others from Charon's cart. A cobbled path runs from the dock up to your cottage, with sand all round the coast. The Far Shore is a second island joined to yours by a bridge off the east side, so it is one walk, not a second trip.</p>
      <table class="tbl"><tr><th>Island</th><th>Costs</th><th>Plots</th><th>Pedestals</th><th>Decor outside</th></tr>
        <tr><td>Island</td><td>&mdash;</td><td>8</td><td>6</td><td>20</td></tr>
        <tr><td>Bigger island</td><td>5,000</td><td>12</td><td>9</td><td>32</td></tr>
        <tr><td>The Far Shore</td><td>20,000</td><td>20</td><td>15</td><td>48</td></tr>
      </table>
      <p>The cottage holds 20 pieces inside. Rugs and paths count as a quarter of a piece.</p>
      <h3>Themes</h3>
      <p><b>A theme changes the whole island: the grass, the beach, the sea and the trees.</b> Buy one at Charon's cart, then choose it at the sign on your island.</p>
      <table class="tbl"><tr><th>Theme</th><th>Costs</th><th>What it looks like</th></tr>
        ${Object.values(G.THEMES).map(t=>`<tr><td>${t.icon} ${t.name}</td><td>${t.price==null?"not for sale":t.price?t.price.toLocaleString():"free"}</td><td>${t.ex}</td></tr>`).join("")}
      </table>
      <h3>Your cottage</h3>
      <p><b>The Store sells the cottage itself in five other styles</b>: a Stone Manor, a Log Cabin, a Beach Hut, a Witch's House and a Casino Villa. It also sells walls (cream, burgundy, navy, forest green, gold damask) and floors (marble, casino carpet, checkered tiles, flagstone) for inside. Everyone who visits sees them, and you can switch back any time.</p>
      <h3>Yahsmeena's Decor, and the Store's</h3>
      <p><b>Yahsmeena stands outside the cottage and sells furniture for your island and your cottage.</b> Buy a piece from her, then press <b>Decorate</b> and put it where you want it. She buys back at a quarter of what you paid, and a piece can be picked up and moved as often as you like. Her shop also lists the Store's decor, with a button straight to it.</p>
      <p><b>A few pieces do something.</b> The bank chest (10,000) opens your bank on the island. The hatchery hatches eggs, and the cellar ladder takes you down to your mushroom beds.</p>
      <h3>Livestock</h3>
      <p><b>A chicken coop, a cow pen and a fishing cage fill up while you are away</b>, logged in or not. Yahsmeena sells them. Click one on your island to empty it into your bag (anything that doesn't fit goes to the bank). A bubble over it shows how many rounds are waiting, and a gold "!" means it is full.</p>
      <table class="tbl"><tr><th>Piece</th><th>Costs</th><th>Every</th><th>Gives</th><th>Holds</th></tr>
        ${Object.values(G.ISLE_FARM).map(f=>`<tr><td>${f.name}</td><td>${f.price.toLocaleString()}</td><td>${f.ms>=36e5?`${f.ms/36e5} hour${f.ms===36e5?"":"s"}`:`${f.ms/6e4} minutes`}</td><td>${f.gives?f.gives.map(([k,n])=>`${n} ${G.ITEMS[k].name.toLowerCase()}`).join(" + "):"a fish (sardine, trout or catfish)"}</td><td>${f.cap} rounds</td></tr>`).join("")}
      </table>
      <p>Two of the same kind fill twice as fast, and ${G.FARM_MAX} is the most of each that works. Nothing fills for time before you put it down.</p>
      <h3>Growing things</h3>
      <p><b>Plant a crop and it grows in real time, whether you are online or not.</b> Click an empty plot, pick what to put in it, come back when it is ready. A ripe plot pays several of what you planted, so one crop feeds the next.</p>
      ${SEEDS_NOTE(G)}
      ${cropTable(G,H)}
      <p><b>Farming is background money, not a living.</b> A full set of plots kept going comes to roughly a sixth of what fighting the same zone pays &mdash; it is something that happens while you do something else, which is the whole point of it running while you are logged off.</p>
      <h3>The rest of the island</h3>
      <p><b>Pedestals</b> put an item on display for visitors. The <b>pet pen</b> breeds two pets into a better one.</p>
      <p><b>Open or closed.</b> The island sign decides whether anyone can ferry over. Closing it sends any visitors home.</p>
      <p><b>Type /island in chat</b>, anywhere, to see how long everything on your island has left: crops, mushrooms, the breeding pen, a hatching egg and the livestock.</p>`},{id:"saving",title:"Saving",icon:"💾",cat:"Starting out",body:`<p><b>There is no save button and there is nothing to lose.</b> The server owns your character, not your browser &mdash; every level, item and ticket is written down as it happens.</p>
      <p><b>Closing the tab is safe.</b> So is losing your connection, and so is your battery dying mid-fight. You come back where you were.</p>
      <p><b>The world keeps going without you.</b> Crops on your island grow while you are logged off, and anything your Market offers sell is waiting in your bank when you return.</p>
      <p><b>When the server restarts</b> &mdash; which it does when the game is updated &mdash; you get a countdown in chat first, everyone is saved, and the page waits it out and reconnects you. You do not need to do anything.</p>
      <p><b>The whole world is backed up nightly</b>, every character and every offer.</p>`}];const UPDATES=[{date:"2026-09-30",title:"The islands, rebuilt",items:["EVERY ISLAND IS MUCH BIGGER, for everyone and for free: the first is about 28 by 15 tiles now (it was 17 by 10), the Bigger island 34 by 18 and the Far Shore 41 by 22. Everything you put down is exactly where you left it; the new land grows round it. Decor goes from 12/20/32 outside to 20/32/48.","THEY LOOK BETTER: a sand beach all round, a cobbled path from the dock up to your door, and new trees and rocks on the new land.","THEMES ARE THE WHOLE ISLAND NOW, grass, beach, sea and trees. Five new ones at Charon's cart: Tropical and Autumn (5,000), Frozen (7,500), The Void and High Roller (10,000). Choose yours at the island sign.","YOUR COTTAGE: bigger inside for everyone (20 pieces of decor, from 12). The Store sells it in five other styles (Stone Manor, Log Cabin, Beach Hut, Witch's House, Casino Villa), and new walls and floors for inside. Visitors see all of it.","LIVESTOCK, 5,000 each at Yahsmeena's: a chicken coop (raw chicken and feathers), a cow pen (raw beef and cowhide) and a fishing cage (fish). They fill up while you're away, up to a day's worth; click one to empty it. A bubble shows what's waiting. Two of a kind fill twice as fast.","NEW PLOTS AND PEN: the garden plots are wooden raised beds now, and the breeding pen has a picket fence, straw and a little kennel.","TYPE /island IN CHAT to see every clock on your island at once: how long your crops, mushrooms, breeding pen, hatching egg and livestock have left.","Yahsmeena's shop lists the livestock first, and every piece the Store sells with a button straight to it."]},{date:"2026-09-30",title:"The Store: pets, eggs and bag slots",items:["A PETS TAB in the Store. TEN PET SKINS: the Baby Dragon, Phoenix Chick, Ghost Cat, Neon Fox, Lucky Cat, Tiny Kraken, Mecha Pup, Void Wisp, Unicorn Foal and the Slot Bot. A skin changes how your pet LOOKS and nothing else: it keeps its bonuses, its name and its rank, and a Greater keeps its blue glow, a Legendary its orange. Some of them spark or glow. Press Try to see one at your heel first.","EGGS FOR TICKETS: every egg in the game, from the Speckled egg to the Gilded, the Raptor and the Yeti. Hatch them in a hatchery on your island as usual.","EXTRA BAG SLOTS: up to five more, on top of the five sold in the game.","EVERYTHING IN THE STORE HAS ITS OWN PICTURE NOW, and the boosts, shows and upgrades read as a short line and a table of what they do.","THE WIKI: long tables are paged. A skill's 'What you can make' shows every recipe, 25 to a page, with a box that jumps to a level (a player found Smithing stopped at 60)."]},{date:"2026-09-30",title:"The Store, rebuilt",items:["THE STORE IS REBUILT, with six tabs: Boosts, Effects, Name, Decor, World and Upgrades. New things wear a NEW ribbon and come first, and a few are ON SALE.","EFFECTS: walking trails (embers, frost, gold dust, sakura petals, hearts, bubbles, shadow steps, coins and the Rainbow Road), glows (gilded, frost, ember, void, a halo, toxic haze), weapon hits (thunderstrike, flame burst, frost shatter, shadow slash, jackpot coins, starburst, petals) and hit splats (blood, gold coin, ice, venom, void, heart, skull). Everyone sees them. Press Try in the Store to walk about in one before you buy it.","TITLES are the game's own now: fourteen to pick from, or write your own (2 to 20 letters, change it whenever you like). Titles from eastcoin.vip no longer show in the game.","PET NAME TAGS: your pet's name over its head, in leather, gold or glowing.","THE 2X POTIONS SAY WHAT THEY DO: the old 2X Potion is now 2X TICKETS & CRAFTING XP, and there is a new 2X SKILLING XP potion (every non-combat skill, for everyone, 30 minutes). Running together, crafting xp stays 2X, never 4X.","THE LOUPES, for the Gem Sorter: the Jeweller's Loupe (a Perfect gem 1 in 56 instead of 1 in 213) and the Master Jeweller's Loupe (1 in 20), 10 rolls each. The Sorter shows the odds you're rolling at.","DECOR: 29 pieces you can only get here, for your island and your cottage: a Jackpot Monument, a Void Portal, a Backyard Volcano, a Dragon Skull, a Pirate Wreck, a Grand Piano, a Fireplace, a Canopy Bed, a Frog Chair, a Cherry Blossom Tree, an Ornate Pool and more. Some of them glow, smoke or play music. Put them down with Decorate.","WORLD: Fireworks, a Confetti Cannon, Sky Lanterns and a Snow Globe, set off wherever you are for everyone there; and the WAR HORN, which calls the Ice Man down on the Yard in your name (5 online, 3 hours between raids).","UPGRADES: extra bank pages (40 slots each, up to five more) and extra quick slots (up to 8, keys 5 to 8).","FIX: anything that said it made you faster (food, drinks, the Ditched set, Yeti-fur boots, the achievement) only ever sped up your swings. It makes you walk faster too now."]},{date:"2026-09-30",title:"The Frozen Reach",items:["TWO NEW MAPS NORTH OF CLOUDREACH: the Frozen Reach and the Frostspire, monsters from level 100 to 115. A MAGE'S COUNTRY: a wand and Magic 60 let you in whatever your Combat, every creature takes 40% more from spells (the owls 70%), spells land at least half the time up there, and most of them stand on snowy shelves and ice floes where no sword reaches.","THE COLD KILLS: without a Frost ward it takes 25 health a second. Wren (Cloudreach) and Morwenna (the Thunderhead) sell a plain Frost charm, and the anvil makes a Frost ward ring and amulet from the Yard raid's frost shards and yeti pelts.","THE FROST JARL waits on the Frostspire's high shelf, and ONCE A DAY, at an hour nobody knows between 2 PM and midnight, THE ICE WYRM comes up through the Reach's lake for half an hour. Both are spells only and shared: everyone who hurts them gets the drop (14,000-22,000 and 20,000-32,000 tickets each), the report, and CASINO calls it.","NEW LOOT: Rimeheart (a legendary ice wand), the Crown of the Frost Jarl (a helm that keeps out the cold), Winter's Heart and the Frostbite ring (spells hit harder), the Frostmind draught, the Glacier Satchel (10,000 pages), the Frostpine wand, glacite (Mining 94), frostpine (Woodcutting 94) and icefin through the ice (Fishing 94).","THE RAID'S SPOILS MAKE THINGS NOW: Frost wards, Yeti-fur boots (the best boots in the game), Rimefang arrows (the strongest arrow) and Frostmind draughts; and the Ice Man carries a legendary axe, Rimecleaver.","BOSS PETS: every late boss can drop its own pet, stronger than anything that hatches: the Rexling (Old Rex), the Matriarch's Calf, the Jarl's Hound, the Wyrmling (the Ice Wyrm) and the Ice Imp (the Ice Man). The Valley's and the Reach's hatchlings and Legendaries are stronger too: the Snow Owlet, the Yeti Cub, the Blizzard Owl and the Abominable.","THE ROAD BEHIND YOU: the Valley's and the Reach's monsters now also drop a few plain materials from the maps before them, now and then.","FIX: a boss's own pet (the Deepwarden's Pot Boy) could only drop during the Long Night. It drops all year now."]},{date:"2026-09-30",title:"The Yard Raid: the Ice Man",items:["THE YARD CAN BE RAIDED. When the frost starts creeping over the Yard, CASINO counts it down: five minutes, then every minute, then thirty seconds. Then THE ICE MAN comes through the north gate with his war party of frost wolves, yetis and frost giants.","STAND ON THE WEST BANK: the war party will not cross the river into the court. Everyone of every level can fight: the raiders come in waves, from wolves a new player can put down to giants that need a crowd, and they carry logs, ores, bars, fish, feathers, bowstrings, spell paper, ink and now and then a gem.","THE ICE MAN is enormous, his health grows with how many are online, and every 10 to 15 seconds he casts DEEP FREEZE on a few of the people fighting him: locked in ice, a few seconds, no moving, no swinging. When he is badly hurt he calls THE LAST WAVE, his huscarls.","WIN and everyone who fought shares the spoils, split by how much of the fighting they did, with a floor for anyone who joined in, plus 15,000 to 25,000 tickets each from the Ice Man himself for everyone who hurt him enough. You get the after report too.","LOSE (he is still standing after twenty minutes) and the Yard is sacked: Bom, Nestor, Livia and Hexa are boarded up for ten minutes. Nobody loses anything they own."]},{date:"2026-09-30",title:"The Primeval Valley",items:["THREE NEW MAPS NORTH OF THE TRAILER PARK: the Primeval Valley's Lowlands, the Ridge and Old Rex's Lair, with monsters from level 90 to 110.","A BOW'S COUNTRY: ARCHERY 40 AND A BOW LET YOU IN, whatever your Combat (everyone else needs Combat 90, 95 and 100). Most of what lives here stands up on the ledges where no sword reaches, every monster takes 40% MORE from arrows (pterodactyls 70%), and in the Valley your arrows land at least half the time, whatever the monster's defence.","TWO WORLD BOSSES, UP ON THE PLATEAUS, ARROWS ONLY: Old Rex on his throne in the Lair and the Mammoth Matriarch on the Lowlands' great plateau. Swords and spells do nothing to them. Everyone who lands arrows shares the kill (12,000 to 20,000 tickets EACH from Rex, 8,000 to 14,000 from the Matriarch), everybody gets the after report, and CASINO tells the server when they fall and when they are back. Their health never resets, so go back for more arrows if you need to.","ARCHERY LOOT: the Skyripper (a pterodactyl-wing longbow), the Raptor-claw ring and the Hunter's Fang (your arrows hit harder), the Hunter's draught (15 minutes of harder arrows), pterodactyl sinew, silkstring and arrowheads. The Golden Raptor turns up one time in 500.","THE CYCAD TIER: cycad shortbows, longbows, quivers and wands, the best a fletcher or a wizard can make, strung with pterodactyl sinew and weighted with fossils.","NEW GATHERING: fossil rocks (Mining 92), cycads (Woodcutting 92) and coelacanth in the lake (Fishing 92).","NEW PETS: the Raptor Hatchling and the Pterodactyl Chick hatch from the Valley's eggs, and each has a Legendary: the Little Tyrant and the Sky King. Nestor takes both eggs.","ARCHER AND MAGE ARMOUR CAN BE REFORGED: Wren's and Morwenna's armour now reforges at an anvil like plate, with the same bars and the same Smithing as the plate piece at its level.","FIX: the Nexus and the Wild Bench no longer double gear. A wand, a Magic Bag, a bow or a quiver comes out one at a time (pages, arrows and shafts still get the extra), and so does a Tinkering gadget's double make."]},{date:"2026-09-30",title:"Roads on every map",items:["COBBLED ROADS EVERYWHERE: every map's paths are laid in the Yard's cobbles now, each shaded to its ground (dark and damp in the Gloam and the Mire, pale in Cloudreach, stormy on the Thunderhead, sandy in the Golden Sands) with the edges broken into the ground around them, so every road feels like part of one world.","A GEM TAKEN OUT OF YOUR GEM BAG KEEPS ITS ROLL: take out a +4% topaz and you get a +4% topaz, to put back, swap round, trade or sell. It used to come back unsorted."]},{date:"2026-09-29",title:"Fights hit harder",items:["EVERY BLOW LANDS: whatever you hit flinches back and flashes white before the red, and so do you when something hits you.","YOUR ATTACKS ARE DRAWN: a sword leaves an arc in its metal's colour, a bow's string snaps back with a streak down the line of the shot, and a wand throws a ring in its page's element.","NEW SOUNDS: you hear a monster wind up before it swings at you, a crit has its own heavy impact, and a hit that is WEAK, RESISTED or GUARDED rings, thuds or clanks. When your health drops below a quarter in a fight, you hear your heartbeat. Monsters falling, and other people's fights nearby, can be heard across the map.","DYING SAYS SO: the screen greys over with what got you, wherever it happened, dungeons included.","Wren and Morwenna's prices now match Bom's melee gear, tier for tier; their weapons cost ten times that.","THE JUKEBOX IS THE RADIO NOW: the Green Room's songs no longer play in the game or follow you around. Pick a station at the jukebox, as before; the Green Room itself is still on eastcoin.vip."]},{date:"2026-09-29",title:"Archers and mages get their own gear",items:["TWO OUTFITTERS keep stalls out in the world: Wren the Ranger in Cloudreach and Morwenna the Mage on the Thunderhead. Each sells five-piece sets in five tiers (Archery or Magic 10, 30, 50, 70 and 90): half the defence of plate, but a whole set adds +10% damage for its style, and an archer's set makes you 6% faster on your feet. They also sell bows, quivers, wands and Magic Bags, expensively (make your own, it's far cheaper), and buy it all back at Bom's rate.","LONGBOWS ARE TWICE AS STRONG. With a shortbow, archery already kept up with a sword; the longbow was the weak one for its extra reach. Now it hits nearly as hard as a shortbow.","Bom (and the outfitters) now buy every wand and Magic Bag. Ones made with a gem had no price and were turned away.","BRONNY'S NEW SKILLS ask for early and mid-game things only: Harvesting, Fletching, Wizardry and Tinkering lines are never late-game."]},{date:"2026-09-29",title:"Bronny needs more trades",items:["BRONNY'S ORDERS NOW DRAW ON NINE SKILLS, not five: Harvesting (crops from your island), Fletching (shafts, arrows and bows), Wizardry (spell paper and pages) and Tinkering (gadgets, a few at a time) join Fishing, Woodcutting, Mining, monster drops and Cooking. Each order still has five lines, picked from the nine.","THE 2X BANNER keeps time by the server's clock, so a computer whose clock runs fast no longer loses it early."]},{date:"2026-09-29",title:"The Wilderness moves out to the Thunderhead, and Bronny wants more",items:["THE WILDERNESS LADDER HAS MOVED from the Gloam to the Thunderhead, on the storm-plain's south edge. It was far too close to the Yard for somewhere that dangerous and that rewarding. A sign in the Gloam points the way. Climbing back out brings you up where you went down.","THE WILD BENCH has moved to the Deep Wild, beside the Nexus altar: both half-again stations in one place, and that place is the Deep Wild.","BRONNY'S ORDERS ASK FOR HALF AS MUCH AGAIN, so the Yard's 2X takes more to earn. An order already out keeps the counts it was given.","SORTED GEMS ARE SINGLE ITEMS NOW: each shows its roll on its corner (+10%, -3%) in its band's colour, and clicking one in your bag sets it straight into your gem bag."]},{date:"2026-09-29",title:"Tinkering rebalanced, and every map's missing art back",items:["TINKERING XP IS PACED LIKE THE OTHER SKILLS NOW. Salvaging pays half an item's part value, and never more than 40 xp for one item, so a rare or a piece of top gear isn't a shortcut any more. Building a gadget pays 15 xp for each level it needs. Giving parts and tickets to a World Project pays less xp than it did (finishing a stage still pays well). Levels already earned stay earned.","GADGETS MOVED UP AND COST TEN TIMES AS MUCH: the Confetti Cannon is Tinkering 31, the Whetstone, Scope and Arc Coil 40, the Lantern 58, the Auger 78 and the Boss Bomb 90. Every part and ticket fee is ten times what it was. The early levels are salvaging and World Projects. The Tinkering guide has the full table.","TINKERING HAS ITS OWN ICON everywhere (skills, profiles, the Hiscores and the wiki), five achievements (Scrapper, Gadgeteer, Automation, Builder and Town Planner), and a Builder's Pins page in the collection log.","MISSING ART FIXED: the Boneyard's dragonstone rocks, Cloudreach's onyx rocks, and the barrels on the Gloam, the Golden Sands, the Fight Pit and the Thieves' Guild all show again."]},{date:"2026-09-29",title:"Tinkering, World Projects, and gems are open",items:["TINKERING, A NEW SKILL: take your junk to Sprocket Sal's Scrap Bench by Bronny's worksite in the Yard and salvage it into parts (Scrap, Gears, Sparks and Relic shards, kept in their own pouch). Build gadgets out of them: a Whetstone, a Scope, a Pressure Cooker, a Lantern for rare drops, the Auger, Chainsaw and Auto-Reel that keep you gathering, a Boss Bomb, and more. See the Tinkering guide.","WORLD PROJECTS: broken things around the world, starting with the jetty in the Yard pond, that the whole server rebuilds together. Give parts and tickets at a project's board; when a stage is full somebody with the Tinkering level it asks for finishes the job, and everybody who helped gets a Builder's Pin. There's a Builders board on the Hiscores.","GEMS: from level 60 in a skill you'll turn up that skill's gem now and then, and monsters of level 60 or more drop combat gems. Take one to the Gem Sorter, a jeweller's bench in the Yard's north court, to roll it a bonus from -5% to +10% (the high rolls are rare), then put it in your gem bag: the Gems button on your inventory. One combat and one skilling setting to start, more for tickets. See the gem bag guide.","THE YARD'S NORTH PASTURE is less crowded: nine fewer monsters around Hexa's stall, every kind still there."]},{date:"2026-09-29",title:"A river through the Yard, quivers and Magic Bags three times the size, and a round of fixes from the bug board",items:["THE YARD, REDONE: a river runs down its middle. East of it are the two courts with every workbench, Livia, Charon and the road to the casino; west of it, every monster, Bronny and Sal. The road crosses on a plank bridge and is cobbled all the way west to the Carnival and north to the Gloam, with lamp posts along it that light up after dark. The courts are fuller too: barrels, crates, sacks, a quench bucket by the anvil, and two chickens loose in the south court.","QUIVERS AND MAGIC BAGS HOLD THREE TIMES AS MUCH: a rough quiver is 300 arrows and a Bogwood one 3,000; Magic Bags run from 300 to 7,500 pages, and the Shroud Satchel holds 3,000. Loading takes every stack of that arrow or page in your bag in one click.","THE WILD BENCH: fletching's own Nexus, in the Wilderness grove against the west rock. It fletches everything, and half as much again.","THE NEXUS, TONED DOWN: it prints one and a half times the pages (was twice) for a quarter more xp (was half as much again).","HOW MANY TO MAKE: every crafting window and the anvil ask how many first (1, 5, 10, 25 or All), and stop when that many are done.","BOM BUYS BOWS, QUIVERS, WANDS AND MAGIC BAGS now, which he used to turn away.","THE BANK takes 1, 5, 10, 25 or 99 at a time, and your stacks stay where they are while you work instead of shuffling.","OTHER PEOPLE'S GEAR: on someone's profile, hover a piece they are wearing to see it, and right-click it for its wiki page.","FIXES: you arrive where you meant to (the nearest open tile, never inside a wall), both ways across the Far Shore bridge; a refresh on your own island keeps you on it; a Master's seal +4 stays +4 through a save; Finished offers stays open; the Gallows oak no longer stands on the onyx rock; the 2X banner sits below the skill ring; and planting a mushroom bed pays Fungiculture xp like a seed pays Farming. Thanks to everyone who used the bug button."]},{date:"2026-09-28",title:"Party meter, run reports, and a report for the Pumpkin King",items:["THE PARTY METER: in a party, a meter sits under the minimap: damage (and damage a second), damage taken, HP healed by food, and deaths, for this fight or the whole run. Fold it, drag it, reset it.","RUN REPORTS: when a Crypt or Pyramid run clears or wipes, or the Count Room's floor is cleared, everybody in it gets a report: the time against your best, awards (MVP, Killing Blow, Snack King, Deadeye and more), the party's numbers, damage over the run, your xp, and who went down to what. Post it to chat, or open it again from the meter.","THE PUMPKIN KING GETS ONE TOO: everybody who fought him gets the report when he falls, or when he gets away, party or not.","FIXED: Bronny's order and a running 2X now survive the server restarting. Before, a restart posted a fresh order and lost what had been handed in. The countdown shows seconds now too.","Eggs drop one kill in 1,500 (it was one in 500 for a few hours today).","THE NEXUS, TONED DOWN: it prints half as much again as another altar (it was twice as much), for a quarter more Wizardry xp (it was half as much again). A print that makes one page makes one or two, one and a half on average."]},{date:"2026-09-28",title:"Bronny's order: the server's daily 2X",items:["BRONNY THE FOREMAN is rebuilding the Yard. Find him at his worksite by the Yard's west gate. He posts ONE ORDER for the whole server: five lines, one each from fishing, woodcutting, mining, monster drops and cooking, always two early-game, two mid-game and one late-game, so there's something for everybody to bring.","Hand in from your bag, any amount, any time: it all goes on the same bars, and his window shows the clock, the bars, what you've got and who's helping. What you hand in is gone for good (he's building with it), and he only takes what the order still needs.","FILL IT AND THE WHOLE SERVER GETS A 2X POTION. It waits at Bronny until somebody who helped claims it, then it's 30 minutes of double tickets and double crafting xp for everyone online, and Bronny puts up the next order. An order that runs out unfilled is replaced by a fresh one."]},{date:"2026-09-28",title:"A new look, and monsters that land their hits",items:["MONSTERS LAND THEIR HITS: out in the world, a monster now aims at the gear its level asks for, all of it, amulet and ring included. Fight something at your level in your tier's kit and it lands about 4 swings in 10 (it was nearer 2). More defence still helps all the way up, reforges included, but it never switches a monster off. Its hits are a little smaller to match, so a fight costs about half again what it did: pack food. The Yard's starters, the Tower and the dungeons are unchanged.","A NEW LOOK FOR EVERY WINDOW: one style across the game, with titles in a new face and a new text face for everything you read. The Market is a Grand Exchange (your eight offers always in view, browse by item, sell from what you own), the quest log is a journal (what you're on, what's near, the step you're on), and the Hiscores have a podium and your own rank pinned at the top.","THE SCREEN: a slim health bar, a slimmer top bar with your menu under your name and settings behind the gear, one wallet strip under the bag, a quest tracker on screen, a paper-doll equipment tab, and I / U / K / J for the bag, gear, skills and quests.","FIXED: right-clicking a tree, rock or fishing spot that needs a tool shows its card again.","THE BUG BUTTON: the ladybird beside your hotbar (or Bugs & ideas under your name). Report a bug or suggest a feature, and see what happens to it: your own reports show their status, and the board shows what's been fixed, what's been added, what's in progress and what's on the backlog. When yours moves, you're told in chat, and the button wears a red count until you look, even if it happened while you were away.","XP/H ON THE TOP BAR: the skill you've trained most recently and its xp an hour this session. Point at it for every skill you've trained, how far through the level you are, and how long until the next one.","CASHING OUT: the Prize Counter now says how many of your 100 ZCoins a day are free right now and when the next lot comes back. It's a rolling 24 hours: each ZCoin comes back a day after it left.","BREEDING: two Greater pets that only have the same one stat can breed now (they could never pick two different stats).","Big numbers fit the wallet strip (313K, 3.1M), and its candy corn counts your bank too. Planting a crop pays a little Harvesting xp. Devil's dice turn up half as often.","BOM'S PRIZE COUNTER, REBUILT: tabs for Sell, Buy, Buy back and ZCoins, Bom himself at the top (with plenty to say), and a lot more cha-ching: your tickets fly into your pile and count up as you sell, fly out onto what you buy, and a big trade-in gets the win banner.","BUY BACK: sold something by mistake? Bom keeps the last 8 things you sold him for an hour, and sells each one back for exactly what he paid you. Reforged gear comes back at its level."]},{date:"2026-09-27",title:"The Depths of the Mountain, and chat that remembers",items:["THE DEPTHS OF THE MOUNTAIN is open: north of the Thunderhead and south of the Trailer Park. Ledges of mossy rock over a drop nobody has found the bottom of, combat 73 to 84. Old Pickett at the landing has three quests.","A MINING MAP. Abyss crystal on the east wing (Mining 75), eclipse (70) and nova (80) in the throne room behind the Iron Ogres. Abyss crystal is the richest jewel vein in the game: any of ruby, sapphire, topaz or opal can turn up in it.","EVERY MONSTER HERE SHRUGS SOMETHING OFF. Pot Boys take 75% less from Magic; Abyss Wisps hang over the drop where no sword reaches (bring a bow); Crystal Ogres shatter arrows (90% less); Iron Ogres take 90% less from everything except Void magic. Goblin Cutters and the Deepwarden take it all, and hit very hard.","THE DEEPWARDEN guards the throne at the far end. Share the kill. He always drops nova ore and abyss crystal, sometimes an opal, 3% of the time the Deepwarden's sigil (an amulet: more tickets, a little tougher), one in sixty a Pot Boy pet, and ONE KILL IN A HUNDRED the chase: THE MOUNTAIN'S HEART, a ring with a singularity ring's stats at Hitpoints 84 that makes every jewel in the rock turn up twice as often.","Pot Boys carry the odd ruby, sapphire or topaz, about one kill in twenty-seven.","EVERY MONSTER'S CARD AND WIKI PAGE NOW SAYS WHAT IT RESISTS: Melee, Archery and Magic as a percentage, 0% included. Right-click one to see it.","CHAT REMEMBERS. A refresh, a restart or logging in now opens on the last fifty lines of chat instead of an empty box."]},{date:"2026-09-27",title:"The Boardwalk: six islands west of the Carnival",items:["THE BOARDWALK is open, out the Carnival's west fence. It is six islands: the Market, Cabin Coast, the Lighthouse, Shipwreck Isle, Pirate's Pier and Skull Isle. Each island's rowboat takes you to the next (and back). The monsters get tougher the further out you row: gulls and deckhands (66-69), Clawhands (74), Kraken Arms (78).","FISHING 60 TO 84: mackerel (60), bluefin (72) and swordfish (84), cooked at the Market's Chip Shop or smoked for a twenty-minute buff. Fishing on the Market and Cabin Coast starts at Fishing 60.","ORE AND WOOD ON THE WAY: starfall, eclipse and nova rocks (Mining 60, 70, 80), and island palms (Woodcutting 60) on most islands. Rubies and friends turn up in the ore like anywhere else; the Gems guide lists every rock.","CAPTAIN CLAW holds Skull Isle, the last island. Everyone who hurts him shares the kill, and when he falls his treasure chest rises out of the sand: each of you opens it once for tickets, opals, sapphires, claw pins and cooked swordfish. He is back 45 minutes later.","CAPTAIN CLAW'S GRIP: new gloves only he drops (1 in 25, and a small chance in the chest). Defence 8, accuracy and strength +4, a little quicker, a little harder to hurt. Melee 75.","Salty Meg at the Market has three quests: mackerel, the deckhands, and the captain.","Monsters out in the Boardwalk, the Foundry and the Orchard Wall take a few minutes to come back (longer the higher their level), not seconds like the Yard."]},{date:"2026-09-27",title:"Where gems come from, on the wiki",items:["GEMS, on one page: the new Gems guide lists all four, every rock that turns each one up, where it is, the Mining level, the chance (1 in 71 ores) and what each gem is for. Every Ruby, Sapphire, Topaz and Opal page says the same, and each ore's page says which gem it can come with.","The wiki no longer points at monsters or recipes you cannot reach yet."]},{date:"2026-09-27",title:"Ranged fighting trains Hitpoints slower",items:["HITPOINTS AT RANGE: with a bow or a wand, the Hitpoints xp from each hit is a third of what a melee weapon gives. Archery and Magic xp are unchanged, and melee is unchanged. Your Hitpoints level is your maximum health, so a ranger still grows sturdier, just more slowly."]},{date:"2026-09-27",title:"Breeding, Fungiculture, and pets change hands",items:["BREEDING: put two pets in the pet pen on your island. Two Ordinary pets make a Greater one with the two stats you pick from its parents, 25% stronger, glowing blue. Two Greater pets of the same kind make that pet's Legendary, glowing orange. Both parents come back when you collect the baby, so a pair can be bred again and again to train the skill. Eggs drop from monsters and hatch in a hatchery, which Yahsmeena sells.","PET FOOD: Ordinary, Greater and Legendary, cooked at a campfire from monster drops and mushrooms (Cooking 20, 50 and 80). Every recipe is on the food's wiki page and in the Breeding guide.","FUNGICULTURE: buy a Cellar ladder from Yahsmeena, climb down, make compost at the bin and grow mushrooms in the beds. Every outdoor map also has three wild clusters you can pick once a day. The Fungiculture guide lists every shroom and every recipe it goes into.","PETS CAN BE TRADED AND SOLD. Offer them in the trade window next to items and tickets. List one on Livia's Exchange under the new Pets tab: anyone can buy it outright and the money goes to your bank, less 1%. Or sell one to Bom at the Prize Counter (Ordinary 1,000, Greater 5,000, Legendary 25,000 tickets). A traded pet keeps its rank, its stats and its name.","THE BUFFS BAR shows each buff as its icon and colour only. Hover one for its name, what it does and the time left.","THE BANK, REBUILT: five PAGES to file things on (drag an item onto a page, or hold / right-click it and pick one), tabs by kind (gear, ranged, tools, food, materials, seeds, breeding, potions), one search over bank and bag, your own amount beside 1 / 5 / 10 / All, and a meter of slots used and what it is all worth. Your bag is the leather panel on the right.","A BOW OR WAND FIRES ONLY WHAT IS LOADED in its quiver or Magic Bag. Arrows and pages in your bag no longer fire on their own: load them. Clicking a different kind swaps it in.","NO PET YET? Cooking pet food trains Breeding a little until you have a pet or an egg.","YOUR BAG HAS SLOTS, like OSRS: drag an item to any slot (an empty one takes it, an occupied one swaps), a used-up stack leaves a gap, a new item takes the first gap, Sort packs it. In the bank, drag a bank item onto your bag to withdraw, a bag item onto the bank to deposit, or onto another bank item to reorder.","FAVOURITES: right-click (or hold, on a phone) an item in your bag and star it. Favourites wear a star, come first when you Sort, and Deposit bag, Stack all and Sell all leave them with you.","ON A PHONE: the map is closer (a tile is thumb-sized), the top bar is one line with a More button, the stats are one row so your bag is in reach, and the tab bar sticks while you scroll. Sideways, the panel is narrower so the game has room."]},{date:"2026-09-27",title:"The Store, the world map, and Bom pays less for gear",items:["THE STORE, in the top nav: tickets only. A 2X Potion for the whole room (100,000), clovers and homeward scrolls, and name cosmetics that everyone sees over your head and in chat: colours, effects, badges and frames. Nothing there changes a fight or a roll.","A WORLD MAP replaces the how-to-play tab: every open map as its real shape, roads between them, the combat band coloured against your level, quest arrows, who is where, and a fog over maps you have not set foot on. Click the minimap or the tab to open it.","BOM PAYS AN EIGHTH of the shelf price for smithed gear, down from a quarter (and a reforged piece's bonus halves with it), AND NEVER MORE THAN 2,500 FOR ONE PIECE, reforged or not. Bronze through dragonstone are under that and unchanged by it; onyx and everything above it buys back for 2,500. Smithing high gear to sell it was printing tickets the ore never earned: five nova bars sell for about 4,900, and the cuirass they made sold for 75,000.","BARS FROM ONYX UP COST TWICE AS MUCH TO SMELT: twice the ore, twice the grimstone or voidglass and twice the charcoal. A starfall, nova or singularity bar still takes ONE bar of the tier below, which has already doubled, so every top bar costs exactly twice what it did. They sell for the same, so smelting to sell pays about half what it did.","THE SKILLS TAB is a grid of tiles; click one for its wiki page. Quest givers now say which step comes first when it is with somebody else.","TYPE /pumpkin IN CHAT to time the Pumpkin King: how long until he rises, or how long he has left and how much health. Only you see the answer.","TEMPER AND FLUX, EXPLAINED on the Smithing page: carrying one does nothing until you click its button at the anvil's Reforge tab so it lights up.","THE PUMPKIN KING IS A CROWD'S BOSS. He has ten times the health he launched with (5,200), anyone can hit him, and everyone who does at least 5% of his health gets their own drops, corn and quest credit. Three players take about ten minutes; alone, you will not finish him before he sinks. His combat xp is ten times what it was, because xp is paid per point of damage.","COMBAT MEANS ONE NUMBER. The Combat hiscore and the skills tab now show your combat level, the same number as the stats panel; Melee has a board of its own.","THE HISCORES, SORTED. The rail is grouped into Combat, Skills, Records and Dungeons & runs, in the skills panel's order. Alchemy has a board at last. THE TOWER ranks the highest floor anyone has cleared, THE PYRAMID has a fastest-clear board, and every dungeon board filters to 2-man, 3-man and 4-man clears, each kept as its own top twenty, so a pair's record is never pushed off by a party of four.","ZCOINS OUT OF THE GAME ARE 100 IN ANY 24 HOURS, per person: tickets traded at the counter and found ZCoins banked count together. Ticket bets keep their own allowance of 50 ZCoins' worth an hour."]},{date:"2026-09-27",title:"The Wilderness, rebuilt",items:["THE WILDERNESS AND THE DEEP WILD are new maps: rock walls, winding roads, a plateau, cave mouths, waterfalls, lava in the Deep. The skilling nodes moved into far pockets held by stronger monsters, and the far corners now carry yew, dragonstone, onyx, starfall, skyash, mooncarp and stormmarlin.","THREE MONSTERS LIVE ONLY THERE: the Wild Weaver (wild silk, four silkstrings a coil), the Marrow Hound (marrow, for the wild-only marrow arrow) and the Grim Lich in the Deep (grimcore, which brews Void ink with grimstone, and seeds ten times as often as anything else).","A THIRD OF THE WILD ATTACKS FIRST, most of it around the nodes, and everything there takes 45 seconds to 2 minutes to come back.","UTILITY PAGES print from Wizardry 50 to 99 now; Waystones are printed on a grimstone. Seeds are rare, but a harvested seed crop gives two seeds back every time, and one harvest in ten gives three.","NOTHING BUT TICKETS ALWAYS DROPS: every monster's own drop is a 25-45% chance now, and an arrow or a page adds half its strength to a hit rather than all of it.","FORTY QUESTS, in stages: go and see someone, hear them out, fetch or make or defeat a thing, carry it somewhere. Easy ones in the Yard, the Gloam and the Mire; medium in the Boneyard, Cloudreach and the Sands; hard from the Thunderhead out to the Deep Wild. Seven new people give them: Mudge in the Mire, Sister Morrow in the Boneyard, Zephyr in Cloudreach, Rashid in the Sands, Volta in the Thunderhead, the Auditor in the Vault, and Grimm the Hermit by the rope down to the Wilderness. A blue marker over someone's head means a quest has sent you to them.","YOUR BAG HOLDS 25 now, before any pockets Bom sews on.","THE TOP OF THREE LADDERS: voidfin and grimscale in the Deep Wild's Black Pool (Fishing 92 and 97, Cooking to 90, smoking to 95), the glass gourd, ember wheat and starfruit on your island (Harvesting 62, 78 and 92, seeded by the Carnival, the Vault and the Trailer Park), and a Gallows oak in the Deep (Woodcutting 90, fifty shafts a log)."]},{date:"2026-09-25",title:"Fletching and archery",items:["ARCHERY FIX: a bow fights with the bow's and the quiver's own accuracy and strength (plus the arrow's), not your melee armour's. Heavy melee gear was making a first bow hit like a high-level one, which raced people through the early arrow tiers. Your armour still counts in full for defence.","DAILY JOBS: every kill job now asks for ten times the kills, for the same tickets. Jobs already on your board today keep the count they were given.","A KEYBINDS page in the wiki (Starting out): every key in one place. Number keys in a conversation now only answer it; they no longer use your quick slots as well.","MAGIC AND WIZARDRY. A third way to fight: hold a wand, load a Magic Bag with spell pages, and every hit pays Magic xp. Five elements (Fire, Frost, Storm, Void, Sun), and every monster may be weak to one and resist another: hover it to see. Wizardry prints the pages at altars around the world, from paper and ink brewed out of flowers you grow on your island. The Nexus, deep in the Wilderness, prints anything, twice. Utility pages give buffs (Haste, Focus, Ward, Rainmaker and more) and four Waystones carry you across the world. The Magic 1 kit is on Brutus's shelf.","E EATS your best cooked food: whatever heals most. It never touches potions, drinks, buff meals or smoked fish, and does nothing at full health.","QUICK SLOTS: four slots beside the chat button, on keys 1 to 4. Click an empty one to put a potion, food, a buff, arrows or a piece of gear in it; click or press its number to use it; right-click to empty it. They follow you to any device. The emote buttons that used to sit there are gone.","STACK ALL in the bank puts every stack in your bag that the bank already holds straight in, in one click. Bows twang less: a shot is now one of four recorded swishes.",`THE TOWER MOVED up behind the north court's railing, into the trees, and the fletching table took its old spot, so the court has room to breathe. Bows and quivers can be reforged now, in their own wood, at the fletching table or the anvil (Fletching, not Smithing): a bow gains accuracy and strength, a quiver a tenth more room a level. Crafting lists say when a recipe makes more than one: "Feather ×15".`,"BOWS SOUND AND LOOK LIKE BOWS. A shot twangs, the arrow you loaded flies across (a diamond arrow looks like one), and it lands with a thud and a puff of splinters and feathers; a crit lands heavier and gold.","COMBAT IS NOW MELEE. The skill you train with a weapon is called Melee, and your combat level is Melee, Archery and Hitpoints together: your stronger style counts in full, the other adds on top. Nobody's combat level went down.","ARCHERY IS A COMBAT SKILL of its own. Hold a bow and every hit pays Archery instead of Combat, damage for damage, and every roll in the fight reads it. It is on the skills panel, the hiscores and profiles. Fletching makes the kit; Archery draws it, and the rough shortbow, the rough quiver and bone arrows are Archery 1 on Brutus's shelf.","A BOW SHOOTS FROM WHERE YOU STAND. Click something inside its reach and you never move; further away and you walk only to the edge of it. Big monsters take a fifth more from an arrow. With a loaded quiver you draw on the next one of the same kind when your target dies, and the idle timer runs eight minutes.","Three Thunder Geese sit over the tear in the Thunderhead's floor. Only an arrow reaches them.","Arrows stack to 1,000. Feathers are 1-3 a kill now, and the cauldron brews fifteen from a small vial, three feathers and a sulky sporecap at Alchemy 5.","A NEW SKILL. Cut logs into shafts and bows at the fletching table in the Yard, fletch arrows from a shaft, a smithed arrowhead and a feather, and go and shoot something. A bow in your hand sets how fast you draw and how far you reach; the arrow you load sets how hard it lands. Every wood makes a shortbow and a longbow, every metal makes an arrow, and the ladder runs 1 to 99.","QUIVERS wear the offhand and hold one kind of arrow in bulk — click arrows in your bag to load one. A shot draws from the quiver first.","GEMS come out of ore now: rubies, sapphires, topaz and opals, about one rock in seventy, and each tips the arrows of the metals it was mined with for extra damage.","FEATHERS are back on chickens. They are worth nothing at the counter now — they are a component, not loot — which is what let them back onto the bird without touching its wage.","Logs have a second use. Every tree in the game now makes bows and shafts as well as charcoal, and a better tree gives more shafts per log."]},{date:"2026-09-25",title:"Pick what you are making, and nothing is a sure thing",items:["THE CAMPFIRE, THE RANGE, THE FURNACE AND THE CAULDRON NOW ASK WHAT YOU WANT TO MAKE, the way the anvil always has. They used to take the hardest thing they could, so a bag with sardines and one bowfin in it only ever cooked the bowfin, and sand at a cauldron was always the large flask. One click still starts straight away on your last choice there; the panel beside it is only there if you want to change your mind.","NOTHING YOU SMELT, HAMMER OR SMOKE IS A CERTAINTY ANY MORE — one attempt in ten fails, at every level, and it takes the materials with it. A scan found 114 recipes that could never fail at all: 95 pieces of gear, seven bars, nine smoked fish and the three anvil consumables. All of them now can.","The panel prints the chance on every row, so you always know what you are risking before you start.","NOVA AND SINGULARITY NEVER FAIL, deliberately. Their weapons already want a core that drops about one kill in two thousand, and gambling that as well would be cruel rather than tense.","COOKING IS UNCHANGED, and so is plainly cooking a fish you could have smoked. Each fish still has a level at which it never burns again.","COOKING IS UNCHANGED. Each fish still has a level at which it never burns again — that promise stays."]},{date:"2026-09-25",title:"A wiki pass: the tables now write themselves",items:["THE MINING, WOODCUTTING, FISHING, COOKING, SMOKING, TOOLS, THIEVING AND “road out” TABLES ARE NOW BUILT FROM THE GAME'S OWN RULES. Between them they had thirty-odd wrong numbers: every sell price in three of them was double what Bom pays, six cooked fish healed a different amount on the page than in your hand, vaultwood was listed fifteen levels and a whole axe grade low, and grimstone was in the wrong zone with the wrong pickaxe.","AND A GREAT DEAL WAS SIMPLY MISSING: the Golden Sands and the Carnival were not on the map of the world, five waters were not in the fishing table, nine dishes were not in the cooking one, and four of the eight thieving marks had no entry at all. Sand, willow, palm, skyash, rustpine, bogwood and the carnival wreck now say where they come from on their own item pages, which none of them did.","THE TOWER AND THE CARNIVAL HAVE GUIDES, which they never have. The Tower's is written for the 99-floor climb: what a floor costs you, how much food to bring, and where the checkpoints are.","FIGHTING NOW EXPLAINS CLICKING AGAIN TO SWING FASTER, and the jackpot kill. Neither was written down anywhere.","Four guide links went nowhere when clicked, and one was labelled with the name of a different page. A checker now fails on all of that, so the next new fish cannot quietly leave the wiki behind."]},{date:"2026-09-23",title:"Rocks hold a lot more ore",items:["EVERY ROCK IN THE WORLD NOW HOLDS 2 TO 12 ORE instead of 1 to 5. What you actually feel is the interruption going away: running a rock dry stops you and makes you pick another one, and that now happens less than half as often. Measured, that is about 4% more ore an hour at low levels and nearly 7% by level 40 &mdash; and a great deal less clicking, which is the part you will actually notice.","It counts ore TAKEN, not swings, so a failed swing costs you time but not depth &mdash; same as before.","Rocks already standing in a loaded area keep the number they were given until they next run out, so this arrives over a minute or two rather than all at once."]},{date:"2026-09-23",title:"A reforge belongs to the item now",items:["YOU CAN SELL A REFORGED PIECE, AND THE BUYER GETS THE REFORGE. Until today a +3 belonged to YOU rather than to the axe: sell it and the buyer got a plain one, while you kept the +3 and would find it waiting on the next axe you picked up. The level lives on the piece now, so it goes where the piece goes.","WHICH MEANS YOU CAN OWN TWO OF A KIND AT DIFFERENT LEVELS. A plain Diamond axe and a +3 Diamond axe are different things and sit in different bag slots &mdash; so a reforged piece costs you a slot, which is the honest price of it.","NOTHING WILL EAT YOUR BEST PIECE. Selling, eating, banking or handing over several of something always spends the PLAIN ones first; the reforged one is only ever touched when you pick it out yourself.","AT THE MARKET you choose which one you are listing, the listing says &quot;+3&quot; in its name, and hovering it shows exactly what that reforge is worth. A buy offer for a plain one will never be filled with a reforged one, or the other way about.","AT THE ANVIL, if you are WEARING one it works on that; otherwise it takes the best one in your bag. So carrying a +2 up to +3 keeps working on the same piece, and a plain spare is only touched when it is all you have.","FACE-TO-FACE TRADES STILL PASS PLAIN PIECES ONLY, for the moment. A trade offer has nowhere to record a level yet, and rather than hand somebody a plain axe while destroying your +3 we have left reforged pieces out of it. The market handles them properly; the trade window is next.","AND YOUR EXISTING REFORGES HAVE MOVED ONTO YOUR ACTUAL GEAR &mdash; what you are wearing first, then your bag, then your bank. If you had a level recorded for something you no longer own, it is gone, which is the whole point of the change."]},{date:"2026-09-23",title:"Every rare drops at 1 in 100",items:["ONE RATE FOR EVERY RARE. A monster's named rare drops — the rings, the hoods, the King's set, the seed crops — all land at exactly 1%, instead of the hand-set numbers between 0.4% and 25% they used to have. It is one rule you can hold in your head, and it applies to anything we add from here on without us having to pick a number for it.","SOME THINGS GOT RARER AND SOME GOT COMMONER. The goat's toga was one in four and is now one in a hundred; the Junk King's cap and wrench come down a long way too. Going the other way, the Loss adjuster's visor, the Bookie's amulet and a few others were under 1% and are now easier.","TWO THINGS ARE DELIBERATELY NOT ON THE FLAT RATE. Real ZCoins still climb with the monster's level, and the casino chips, boxes and dice still scale with what the monster pays — so a bigger monster still turns up more of them. Flattening those would have made farming chickens the best earning in the game.","And a correction: this guide still quoted the old ZCoin fishing rates after yesterday's halving. A sardine is about 1 in 800 and a thunder squid about 1 in 556."]},{date:"2026-09-23",title:"Bom will take your spare rares now",items:["EVERY RARE HAS A BUYER. Twenty drops &mdash; the casino set, the Junk King's two, the Tax Wraith's hood, the mystery boxes &mdash; had nobody who would take them, so a second one was worth nothing at all unless another player happened to want it. Bom takes them now.","HE LOWBALLS YOU AND WE ARE NOT HIDING IT. He pays a quarter of what the piece is reckoned to be worth, which is the same deal he gives on gear: he buys an Eclipse gladius back for 539 and sells one for 92,400. Selling to another player will basically always be the better idea. This is a floor under a duplicate, not a price.","IT IS ONE CLICK PER ITEM, AND &quot;TRADE IN THE LOT&quot; STILL CANNOT TOUCH IT. Your rares are a separate list with their own buttons, deliberately, so no amount of clicking the big button can sell the ring you are wearing.","A Green house chip is not on the list on purpose: using one already pays 100 tickets, so a quick sell would only ever be the worse button."]},{date:"2026-09-23",title:"A bank on your island, and the island looks like one",items:["YAHSMEENA SELLS A BANK CHEST, 10,000. Put it down anywhere on your island and it opens your bank &mdash; the same bank, the same rules &mdash; so a full bag of crops no longer means a trip back. It is the only thing in her shop that does anything; the rest is for show, and that is deliberate.","THE PLOTS ARE DRAWN NOW. Every crop has four growing stages, hand-drawn, and the last one means ripe: if it looks finished, it is. They had been three coloured rectangles because the pictures were made a week ago and never wired up.","SO IS THE DOCK. Real planking, running the length of the pier instead of a flat brown rectangle with lines ruled across it.","IF YOU OWN THE FAR SHORE, YOUR ISLAND WAS DRAWING ITSELF WRONG. The largest island was the one tier nobody had listed in the art, so its plots, palms, pedestals, pen, ferry and lighthouse were all falling back to rough shapes. Fixed.","And the guide for islands said Charon runs a ferry at River Bend. He has worked from a cart in the Yard since the Forum closed."]},{date:"2026-09-23",title:"Wheat in the Yard, and the medals are real",items:["WHEAT GROWS IN THE YARD NOW &mdash; three patches, well apart: one in the north-west above the copper, one beside the path through the middle, and one out in the south-west meadow. They grow back on their own, they need nothing in your hand, and each one is 8 Harvesting xp.","WHICH MEANS HARVESTING CAN BE STARTED. It could not before, and that was our mistake rather than anything you were doing wrong: the only wheat in the game was in a part of the map that is shut, this guide has been pointing at the Yard the whole time, and every other crop needs a level you could only get by growing something. Wheat is the level 1 crop and it is now where the wiki always said it was.","THE ACHIEVEMENTS WINDOW HAS BEEN REDRAWN. Every tier wears its own medal &mdash; bronze, silver, gold, a cup and a crown &mdash; instead of its name in a colour that was close to unreadable on parchment. Ticket amounts show the real ticket rather than an emoji, tier headings say what the tier pays on a line of their own, and the button in the bar carries the same badge the window does.","SMALL, BUT WORTH SAYING: every 'Sells' column in these guides was still quoting yesterday's prices after the halving. Twenty-nine of them were wrong and they are right now, and the wiki checker reads those columns from the rules from here on so they cannot drift again."]},{date:"2026-09-23",title:"Half the tickets, and the tables take a cut",items:["EVERYTHING YOU SELL NOW PAYS HALF. The Cashier, Brutus and the tickets a kill carries have all been halved together &mdash; fishing, mining, woodcutting, farming and fighting alike &mdash; so nothing has become a better or worse way to earn than it was yesterday. What things COST has not changed at all, so gear, bag pockets and island plots each take about twice as long to save for.","WHY. Tickets were being made a great deal faster than there was anything to spend them on: every price in the game put together came to about forty hours of play at the top band, and after that tickets had one use left. At 1,000 tickets to the ZCoin that was quietly minting more ZCoins than the whole of the rest of eastcoin.vip added together.","THE TABLES NOW TAKE A CUT. A ticket play pays between 93% and 99% of the fair price, drawn fresh every play, so the house keeps about 4% &mdash; a little under a roulette wheel. No play is ever better than fair any more, which means there is still no table worth shopping for. It was 96% to 104%, which averaged exactly 100% and so drained nothing at all. The ZCoin tables on eastcoin.vip are untouched and still pay 96% to 104%.","REAL ZCOIN DROPS ARE HALVED TOO, from kills and from fishing alike. They were never the big half of it &mdash; an hour of fighting dropped about four and converted about forty-five &mdash; but they are part of the same flow.","THE CRYPT CAME WITH IT. Antes and clears are both halved, so a clear is still worth about half again what the same minutes pay on your own. The slots ticket jackpot starts at 10,000 now for the same reason.","WHAT DID NOT CHANGE: the daily jobs, the prize wheel, achievement rewards, free-play chips, and every price in the game."]},{date:"2026-09-23",title:"Tools reforge into tools, and your +2 shows",items:["A REFORGED PICKAXE, AXE OR ROD NOW BUYS SPEED, not accuracy and strength. Offering combat stats on a skilling tool never made sense — tools are deliberately poor weapons — so a level is +2.5% at what the tool actually does: mining, chopping or fishing. Three levels is +7.5%, just under a full tier, so reforging still gets you closer to the next rung without jumping it.","FISHING RODS CAN BE REFORGED AT LAST. A rod has no combat stats at all, which is the only reason it was refused; now that tools reforge on speed there is nothing to refuse. The three starter bronze tools can be reforged too.","RINGS AND AMULETS CAN BE REFORGED. They give a little of everything, so a level moves all three stats — which makes jewelry the best value on the anvil. A ring costs 2 bars an attempt, an amulet 3.","YOUR REFORGE LEVEL IS VISIBLE NOW. A +2 shows in gold on the item in your bag and on your character, not just at the anvil. If you gambled bars for it you should be able to see it.","A FIX: reforging was quietly paying about a quarter of what the anvil advertised. The bonus is a percentage of the piece's own stat OR +1 a level, whichever is more — but the +1 floor was only being applied to the number on screen, not to the stats you actually fought with. A full set at +3 was giving +5 defence where the anvil said +18, and a +3 weapon swung exactly like a plain one. Everyone's existing gear now does what it always said it did.",'The anvil also stops saying "next level adds nothing to this piece" — that was the same bug, and it was wrong on over half the list.']},{date:"2026-09-22",title:"Rocks hold more than one ore",items:["EVERY ROCK, EVERYWHERE, NOW HOLDS 1 TO 5 ORE. It used to give exactly one and then sit empty for eight seconds — and it stopped you mining, so every single ore cost a click and a wait. You stand and work a rock now, the way you work a tree or a fishing spot, and it only runs out when it is actually out.","That is roughly twice the ore an hour, and the number of rocks in a zone no longer caps how fast you can mine. The big veins are unchanged: they never run dry and never did.","THE RUN is entered by a rope ladder now, north of the market at the top of the Yard, instead of a door.","The Yard's two choppable trees are a gnarled Old oak, so you can tell them from the 126 that are only scenery — and they leave a proper stump."]},{date:"2026-09-22",title:"A forge in the Yard, reforging, and smoked fish",items:["THERE IS A FURNACE AND AN ANVIL, in the Yard's north court beside the Crypt stairs and the Tower. Smelting and smithing have had recipes all along and nowhere to do them — every bar and every piece of gear is now actually makeable. The court grew two rows north to fit them.","REFORGING, at the anvil. Spend bars to push a piece you already own further: a level adds 5.5% of that piece's own stats or +1, whichever is more, up to +3, which is worth about one gear tier. A fully reforged set slightly beats a fresh set of the tier above — so it is a way to keep going when the next tier is out of reach, not a way past it.","THE ODDS ARE ON THE BUTTON, and so is the risk. +1 always works. +2 is 80%, +3 is 55%. A miss normally knocks the piece down a level — but at +2 there is an 8% chance, and at +3 a 15% chance, that it CRACKS APART AND IS GONE. About one piece in seven is lost on the way to +3. The bars go whether it works or not, and a broken piece takes its level with it.","SMOKED FISH give you twenty minutes of something: tougher, better drops, more tickets, or quicker on your feet. Smoke instead of cooking by having charcoal on you — the fire does it automatically when it can, and drops back to plain cooking when the charcoal runs out. Seven kinds, from ghostcarp up to bowfin.","CHARCOAL ALSO STEADIES A FIRE. Carrying it means your cooking will not burn — it spends one instead of taking the roll, and only when the risk is worth it, so it is never quietly wasted on a fish you were never going to ruin.","YOUR OWN PET IS VISIBLE TO YOU NOW. Everyone else could always see it at your heel; you could not see your own. Sorry about that."]},{date:"2026-09-22",title:"The furnace burns wood now, and the top maps bite",items:["EVERY SMELT TAKES CHARCOAL. Bronze wants one, Eclipse wants four. If your smelting has stopped working, that is why: put logs in your bag and stand at the furnace anyway. It burns a log, smelts, burns another — you do not have to do anything differently.","CHARCOAL IS BURNT LOGS, made at the furnace. BETTER WOOD GIVES MORE: plain logs and willow give one, ash and pine two, yew three, void and bogwood four. One bogwood log fuels an Eclipse bar where it would take four ordinary ones and most of a bag. It sells for less than a log does — burn it to smelt, not to sell.","Woodcutting was the only gathering skill that fed nothing. Now it feeds the same furnace mining does.","SOME MONSTERS ATTACK ON SIGHT AGAIN, from the Boneyard upward — and only there. The Yard, the Gloam and the Lantern Mire stay exactly as calm as they were. Nothing reaches further than three tiles, so it is a thing you walked up to, not a thing that crossed the map at you.","It is where the good wood, ore and fish are: the Boneyard, Cloudreach, the Thunderhead, the Trailer Park and the Vault. Turning up at a level-80 tree with no way to defend yourself is now a decision rather than a free lunch.","A HISCORE BOARD FOR EVERY SKILL, plus Total level. It was Combat and Fishing only."]},{date:"2026-09-22",title:"Luck cut back, and the Market shows what Bom charges",items:["LUCKY CLOVERS AND HORSESHOES ARE RARER, and worth less. A clover turned up every TWELVE gathers and was good for fifteen lucky actions, so anyone skilling was lucky more than full time — which is not a buff, it is the baseline with extra words.","The bonus is now 5% more likely to find a real ZCoin, down from 25%. Clovers drop about 1 in 100 gathers (was 1 in 12) and horseshoes about 1 in 600 (was 1 in 150). Luck is on roughly a fifth of the time now instead of always.","THE MARKET SHOWS WHAT BOM CHARGES. Picking something to sell, each row in the list carries his price beside your count, and it sits on the reference line with cheapest-listed, best-offer and last-sold while you set yours. Half the goods have no figure because he does not sell ore, fish, logs or drops — those say nothing rather than inventing one."]},{date:"2026-09-22",title:"The Trailer Park",items:["A NEW ZONE, north off the Thunderhead. Combat 80 to fight in it, Fishing 80 for the water. The road west still ends at the Vault — this is a turning before it, so the top of the game is a fork rather than a queue.","THE JUNK KING, level 98, in the fenced yard at the east end. Twice the hitpoints of anything else alive, and the only thing that drops his cap or his wrench.","Junkyard Dogs, Rabid Possums, Scrappers and Yard Gators, 80 to 92.","TRUCKS UP ON BLOCKS give up their catalytic converters to a pickaxe — the most valuable thing you can carry out of a scene. Slagstone from the bank behind the yard, rustpine and bogwood to cut, and mud cat and bowfin in the black water, which cook into the best food in the game.","All of it wants a top-rung tool. Until now there was nothing above Vaultwood to chop and nothing above the Vault to mine, so the last three rungs of the tool ladder had nothing to do."]},{date:"2026-09-22",title:"The Run has something to do in it",items:["AGILITY NOW PAYS. Every level made you very slightly quicker — except it didn't: the bonus was written the day the skill was built and never connected to anything. It is connected. At 99 you move 9% faster, everywhere, forever.","PERFECT GATES. Cross a gate within a quarter-second of it opening and it counts as perfect, and the count carries through the lap. Eight out of eight DOUBLES what the finish pays.","MARKS ON THE COURSE. Three are scattered down the lane at the start of every run, always off the middle row — so fetching one costs you a beat, and maybe the gate you were lined up for. They pay tickets and Agility xp. Yours alone: nobody can take the ones dropped for you.","BEST LAPS ARE ON THE BOARD, at the start of the course and in the Hiscores window. Your own best also sits on the Agility row in the Skills tab.","And the course has its sign back, and a way out. The passage down to the door had been walled off, so anyone who went in could not walk out again."]},{date:"2026-09-22",title:"Tools come in seven grades, and the Yard has a market",items:["PICKAXES, AXES AND RODS NOW HAVE TIERS — bronze, emerald, diamond, dragonstone, onyx, starfall, eclipse, the same seven as the armour, each with its own art.","A rock, a tree or a fishing spot asks for a tool of its own grade. The grade it wants is always the grade named on it, so anything you are high enough to work, you are high enough to hold the tool for.","Every grade up is 8% quicker at everything below it as well, so a better tool is never wasted on easy work.","Buy them at the Prize Counter — cheap for their grade on purpose — or smith them: two bars for a pickaxe or an axe, one for a rod.","AND YOU HAVE TO BE HOLDING IT. Pickaxe, axe or rod: it goes in the weapon slot, and one in your bag will not do. A tool in the bag used to count, which with seven grades of each meant the weapon slot was free — you could fight with a sword and mine with whatever was at the bottom of your bag.","ORE YOU CAN ACTUALLY REACH. Every grade of ore below starfall used to sit in a closed map, so there was nothing to train Mining on between 1 and 60. Copper and tin are in the Yard now, emerald in the Gloam, diamond in the Mire, dragonstone in the Boneyard and onyx in Cloudreach.","THE YARD HAS A MARKET. Livia, the bank chest, Charon's cart, the campfire, the jukebox and the stairs down to the Crypt were all standing about on grass. They are on two paved, railed courts either side of the road in from the casino now, with lamp posts, crates and barrels about the place. Each court is fenced on three sides and open to the road.","RAW FISH IS NOT FOOD. Cook it first — and the Cashier only buys it cooked."]},{date:"2026-09-21",title:"The Green Room, a Sportsbook, and animals that walk",items:["THE JUKEBOX IS THE GREEN ROOM. It used to run its own little queue. It is now the SAME room as eastcoin.vip/?view=music: the same songs, the same history and rankings, the same reactions and skip votes. Put one on in the Yard and the whole site hears it with you, with your name on it.","Songs are FREE now. They cost 50 tickets before. What limits you is the queue, the same as it limits everyone on the site.","If you have the music page open in another tab, the game keeps quiet rather than playing over the top of it, and says so.","THE SPORTSBOOK: a new board beside Bom Trady, in the casino. It is EastCoin Picks — tonight's real games, their real prices, your record and the season leaderboard — and a pick made here is the same pick as one made on the site. ZCoins only; tickets do not touch it.","The chickens, cows, boars, hornworms and both olives WALK now instead of sliding, and they breathe when they stand still."]},{date:"2026-09-21",title:"Six jobs a day, and five times the pay",items:["THE TASK BOARD PAYS FIVE TIMES WHAT IT DID, and gives you SIX jobs a day instead of three. If you already had today's three, the other three are waiting on the board now.","Each job shows the MONSTER'S OWN PICTURE and WHERE to find it, so you know which way to walk before you start.","The casino's south door is shut for now. Vince is standing in front of it. The arch on the west side is the way out to the Yard, where everything is.","Crits are rarer: the top tenth of what you can hit, and never under 4 damage. A brand-new player was seeing CRIT on half their hits.","A monster's health bar now sits above its head whatever size it is. It used to lie across the big ones' faces."]},{date:"2026-09-21",title:"The Hoodie's hoard",items:["A CHEST EACH. When the Hoodie dies, his hoard appears in front of the throne. Everybody who earned the clear opens it for their OWN loot: nothing is shared and nobody can take yours.","3 TO 7 THINGS. The first is always the clear's tickets (they used to land in your bag at the kill; now they're in the chest). The rest: bonus tickets, drinks, dinners, lucky clovers, Casino scrolls, house chips, and rarely a horseshoe or one of the six rare buff pieces.","Your roll at a real ZCoin happens when you open it.","FORGOT IT? Walked out, lagged out, party left? It's sent after you, the moment you're anywhere else. It can't be lost and it can't be opened twice.","Past your three paid runs for the day the chest is lighter: 3 things, no rare gear."]},{date:"2026-09-21",title:"The Fight Pit takes tickets too",items:["THE FIGHT PIT: BET TICKETS, WIN TICKETS. The Pit has the same ZCoins / Tickets switch as the floor. A ticket bet is 10 to 20,000 tickets on one fighter, and you can add to it until bets close. It's paid in tickets when the fight ends, at exactly the price a ZCoin bet on that fighter gets.","That's every table now: ZCoins in, ZCoins out. Tickets in, tickets out. Trade tickets for ZCoins at the Prize Counter.","FIXED: the Crypt's fastest-clear boards went blank every time the game restarted. They're read back properly now. So are the jukebox's station and the song queue."]},{date:"2026-09-21",title:"Everything's by the jukebox now",items:["THE TOWN IS CLOSED, and nothing you used there is gone: it all moved to the Yard, right outside the casino, around the jukebox.","LIVIA and her EXCHANGE STALL, CHARON and his cart to your island, and the STAIRS DOWN TO THE CRYPT are all there, next to the bank chest and the campfire that already were.","Both of the casino's doors lead outside to the Yard now. Coming back from your island sets you down by Charon's cart.","If you logged out in the town or the bank, you'll wake up in the casino. Your bank is the same bank: the chest in the Yard opens it."]},{date:"2026-09-21",title:"Tickets in, tickets out",items:["BET ZCOINS, WIN ZCOINS. BET TICKETS, WIN TICKETS. Every table on the floor has a ZCoins / Tickets switch. On Tickets you play for tickets and you're paid in tickets: stack them for gear, or trade them for real ZCoins at the Prize Counter (1,000 a ZCoin). It remembers which one you used last.","Ticket bets are 10 to 20,000 tickets (chips: 100, 1K, 5K, 20K), and they no longer use up your hourly ZCoin allowance, so bet tickets as much as you like.","SAME ODDS AS THE ZCOIN TABLES. Every ticket play pays between 96% and 104% of the fair price, drawn fresh each time, 100% on average. No table is the better bet. The prices you see are the fair ones (the coin says 2x); each play lands a little over or under.","The slots have a TICKET JACKPOT of their own, starting at 20,000 tickets. Three sevens on a 20,000-ticket spin takes all of it.","The Fight Pit and Roulette haven't changed yet: tickets there are still a stake that pays ZCoins."]},{date:"2026-09-21",title:"Trade tickets for ZCoins",items:["TICKETS FOR ZCOINS, AT THE PRIZE COUNTER. Bom Trady now trades your tickets straight into real ZCoins: 1,000 tickets for 1 ZCoin, onto your eastcoin.vip balance. Pick how many, press the button. Up to 50 ZCoins an hour (ticket bets and ZCoins you found share that).","Taking an Exchange offer down now puts what was left back in your BAG (your bank if the bag's full), and tells you exactly what went where. It used to go quietly to your bank.","The Prize Counter lists armour and arms above the drinks and dinners. Profiles show a green dot for online, red for offline."]},{date:"2026-09-21",title:"Look anybody up",items:["PROFILES. Right-click somebody in the world, or click their name in the chat log or on a Hiscores board, and you get their profile: the character they made, every skill level, their combat level, kills, quests, crypt clears, tickets earned and time played.","It works for people who are offline too. If they're standing next to you, the profile has Trade and Invite to party on it.","Fishing, cooking, the bag and the rest of the skilling sounds are quieter and always the same now: this is a game you leave running, so the noise it makes had to be one you can sit beside."]},{date:"2026-09-21",title:"Fishing spots, scattered",items:["FISHING SPOTS aren't in a neat row any more. Every pond, lake and sea has its five spots scattered over the first two rows of water, and they come in five looks: ripples, bubbles over a school, lily pads, a whirlpool with a fin, and reeds.","The item that pops up over your head when you catch or gather something is bigger, and the xp number beside it lost its little skill icon.","The PARTY box now keeps up with where everybody is and how hurt they are all the time, not only inside the Crypt, and it sits higher so it doesn't cover the game's messages."]},{date:"2026-09-21",title:"The Crypt, dressed. And you can't be lagged out of it",items:["DROPPED OUT OF A RUN? LOG BACK IN. If the game lags you out, or you refresh, or your internet blinks, your place in the party and in the crypt is held for 3 minutes. Log back in and you're standing where you were. If the boss died while you were gone, you're paid when you're back.","THE CRYPT LOOKS LIKE ONE NOW. Drawn flagstones, brick walls with skulls and shackles in them, broken pillars, cages, open coffins, an altar, ghost-fire braziers, gargoyles, and a throne of bones behind the Hoodie.","A WAY OUT AT THE FAR END. Stairs up to town, in the back wall of the Hoodie's room. They only work once he's dead.","HIT NUMBERS have drawn badges: a red splat for a hit, a gold burst for a crit, a blue shield for a miss. The red-tile slam now shows its number over your head too.","The Hoodie's health bar no longer looks half-empty before anybody has touched him.","DROPS / XP: the chat box has a second tab that lists what you've found and the xp you've earned this session.","The casino's three boards aren't squashed together any more. The TASK BOARD has its own bit of wall, right of the roulette door. Winners' Wall is left of the door, Hiscores further right.","The way out of a room can't hide under the Chat button any more, and every room's doorway is drawn: a doormat, a carpet runner, marble or stone steps.","COOKING IS BACK. There's a campfire just inside the Yard, by the way in from the casino. Click it with raw fish in your bag. Every fish can be cooked now. A cooked fish sells for TWICE the raw one and heals a lot more. You'll burn a few at first.","Higher or Lower and Mines say CASH OUT, with the ZCoin beside the amount. Games, Wiki and Hiscores got proper buttons."]},{date:"2026-09-21",title:"THE CRYPT: bring a party",items:["A DUNGEON YOU CAN'T DO ALONE. Stairs down to the Crypt are in town, beside the bank. It takes a PARTY of 2 to 4: click another player and choose Invite to party. Your party's health shows on the left.","HOW A RUN GOES. Everybody stands by the stairs and the leader picks a difficulty: the Crypt, the Deep Crypt or the Black Crypt. THE DOOR'S NUMBER IS NOT THE FIGHT'S. The doors open at Combat 10, 30 and 40, but a crypt boss has far more defence than its own gate level can swing at: below Combat 22, 47 and 76 you hit it about one time in ten WHATEVER you are wearing, and the fight takes over an hour. Take the Black Crypt at 76 and up, or bring somebody who is. Each of you puts up an ante. Clear the Ossuary and its gate opens; clear the Haunted Hall and the next one does; then everybody alive gathers at the lever to open the Sanctum.","THE HOODIE. Too much health to solo, and more of it the bigger your party. He goes for whoever has hurt him most, so let your toughest player start. When the floor around him turns RED, get out of it: the slam takes two fifths of your health. At half health he whistles up a skeleton for each of you. After five minutes he hits twice as hard.","WHAT IT PAYS. About one and a half times what the same minutes pay solo: roughly 5,000, 14,000 or 22,000 tickets EACH on a clear, and everybody gets their own roll at a real ZCoin. Do under a tenth of the boss's damage and you're paid half. Three paid runs a day; after that a clear pays a quarter.","DYING costs nothing in there: you wake at the bottom of the stairs and run back. But if the WHOLE party is down at once it's a wipe, and the crypt keeps the ante.","Clicking a player now opens a small menu (Trade, Invite to party) instead of sending a trade request straight away. Fastest clears are on the Hiscores."]},{date:"2026-09-21",title:"A better first minute",items:["NEW PLAYERS ARE TOLD WHAT THIS IS FIRST. The explainer now comes before the character builder, says a word about making your character, and takes you straight into it. When you come out, it offers the two ways to start: the games, or outside.","THE GAME LOADS A LITTLE FASTER. The maps of areas that are closed are no longer downloaded just to log in.","The island's farm plots and pet pen have proper pictures. They aren't ready yet, and say so when you click them."]},{date:"2026-09-21",title:"Yahsmeena's decor shop is open",items:["DECORATE YOUR ISLAND. Yahsmeena, by your cottage, sells furniture and decorations for tickets: benches, flower beds, a flamingo, tiki torches, a fountain, a hot tub, a beer pong table, and for indoors sofas, rugs, a big TV, a pool table, a trophy case and one gold toilet. 34 pieces, all for show.","HOW: buy from her on your own island, then press Decorate (bottom right of the game). Pick a piece from the tray and click a tile. The hand picks a piece back up; nothing is ever lost by moving it. She buys back what you don't want for a quarter.","THE RULES: pieces can't overlap, can't go in the sea, and can't wall anything off (the game won't let you seal in your plots or your door). Outdoor pieces go outside, cottage pieces go inside, some stand against the back wall. 12 pieces on the first island, 20 on the bigger one, 32 with the Far Shore, and 12 in the cottage.","VISITORS SEE ALL OF IT. Go and look at somebody else's.","A GZ button joins the quick emotes."]},{date:"2026-09-21",title:"Emotes in chat",items:["THE CHANNEL'S EMOTES WORK IN GAME CHAT. Type an emote's name as its own word (Zcoin, GIGACHAD, NOOO, any of the 7TV and BetterTTV ones from the stream) and it shows as the picture. Thanks to Kellzifer for asking.","Yahsmeena's name tag says she's an NPC, and her face is in her talk window."]},{date:"2026-09-21",title:"Yahsmeena moves in",items:["EVERY ISLAND HAS A DECORATOR. Yahsmeena stands by your cottage. She will be the one selling furniture and decorations for your island; the shop isn't open yet, so for now she has opinions. (She asked for the job while helping test the game, and got it.)"]},{date:"2026-09-21",title:"A Quests completed board",items:["HISCORES: QUESTS COMPLETED. The House Tour counts once you have walked it to the end, every daily job you claim at the board counts, and so will story quests when they come back. Daily jobs count from today: nobody was keeping score before."]},{date:"2026-09-21",title:"Songs on the jukebox, a real Hiscores board, and tickets you can trade",items:["PICK A SONG. The jukebox has a Songs tab now: search for anything (or paste a YouTube link), pay 50 tickets, and it plays for everyone in the casino and the Yard, in time with each other. It queues, two each, eight minutes a song at most. Nobody can skip yours but you. The station comes back when the songs run out.","HISCORES THAT WORK. The button was broken for everyone: fixed. The boards are the game as it is now: Combat, Fishing, tickets earned, tickets wagered, kills, and real ZCoins found. There is a board on the casino's back wall too, by the Winners' Wall.","TICKETS TRADE. Click a player, open a trade, type how many tickets. Both of you accept twice, like any trade.","THE HOUSE TOUR'S SECOND STEP IS FIXED. There is no free chip any more, and the step could not be finished. Any play at a table finishes it now, and so does reading the job board if you have no ZCoins yet.","We say OUTSIDE now, not 'out the arch'.","The Free-play chip is called a Green house chip now, because that is what it is: click it and it cashes into 100 tickets. It was never going to show up on a table."]},{date:"2026-09-21",title:"A proper welcome, and the bar put its prices up",items:["A WELCOME FOR THE REGULARS. The first time you arrive you are told the two things that matter: every game from eastcoin.vip is here for the same ZCoins (the Games button glows until you press it), and tickets are new money you earn outside.","THE BAR IS TEN TIMES DEARER. Every drink and every dinner, and the round for the room. They were too cheap to think about.","The tile outline under your mouse is off unless you turn it on in Settings.","ONE VOLUME FOR EVERYTHING. Top right of the game, beside your buffs: a mute button and a slider that turn the sound effects and the jukebox up and down together. M still mutes.","The casino windows show our own ticket, not the emoji one.","YOU WALK FASTER. About a fifth quicker, everywhere."]},{date:"2026-09-21",title:"Walk further, earn more",items:["THE ROAD PAYS MORE THE FURTHER YOU GO. Inside every area the first monster used to be the best money, so there was no reason to walk on. Now each monster along the road pays a bit more a minute than the one before it, all the way to The House. Nothing pays less than it did.","JACKPOT KILLS. About one kill in fifty was carrying the house's money: five times that monster's tickets on the spot, with the casino's own win banner. Everyone in the area hears about it."]},{date:"2026-09-21",title:"Guy or girl, and a new body",items:["YOU PICK. The mirror asks Guy or Girl first now, and Surprise me stays inside your answer. It used to roll across everybody, which is why half of you woke up as women.","A NEW BODY: Fat as shit. It is exactly what it says.","Trousers are called Pants now.","SKIN TONES TAKE PROPERLY. Pale highlights on the women and most of the Big guy never took your skin colour, so darker skins came out patchy. Every body is one colour all over now.","BETTING TICKETS SAYS TICKETS. Pick Tickets at a table and the button reads Spin · 5,000 tickets, not 5 ZC. A win still pays ZCoins.","Kellz has moved to the smoking section. The ticket count in your stats wears a ticket, not a coin."]},{date:"2026-09-20",title:"The jukebox takes tickets",items:["PAY TO PLAY. A pick on the jukebox costs 100 tickets. Everyone in the casino and the Yard hears it, and it is yours for 10 minutes: nobody else can change it or switch it off until your time is up.","THE MUSIC STOPS WHEN YOU LEAVE. Close the game, lose your connection, or put your phone away, and the radio goes quiet."]},{date:"2026-09-20",title:"Music in the Yard, the regulars are losing, and prizes on the counter",items:["A JUKEBOX IN THE YARD. It's on a slab of concrete just inside the gate. Same station as the casino's: put something on at either one and everybody in the casino and the Yard hears it.","THE REGULARS PLAY FOR REAL NOW. Well, for pretend. Watch someone at a table and their wins and losses float up over their head: green when they hit, red when they don't. Mostly red.","BOM TRADY LEFT A FEW THINGS OUT. A trophy, a football, a ring box, some chips: small prizes sitting on his black counters."]},{date:"2026-09-20",title:"A mute button, the jukebox moved, and Bom Trady's counters straightened",items:["THE JUKEBOX MOVED. It is in the middle of the casino now, by Bom Trady's booth, where everyone can reach it. It used to hide in the corner by the bar.","BOM TRADY'S BOOTH IS SQUARE NOW. His black LED counters run in straight lines: one down each side, one across the front with the lit prize cases in it, and the man himself in the middle.","ONE CLICK FOR QUIET. The 🔊 in the top bar (or the M key) mutes everything at once, sound effects and the jukebox, and one more click brings back exactly what you had. Your volume and Settings are left alone."]},{date:"2026-09-20",title:"A real jukebox, and the GOAT's new look",items:["THE JUKEBOX PLAYS REAL RADIO. Click it (in the middle of the casino), pick a style or search for anything, and the whole casino hears your station. Your own volume and mute are in the same window.","BOM TRADY HAS BEEN REDRAWN: the jaw, the eye black, the 12, and seven rings. He runs the Prize Counter from inside a booth of lit glass cases.","RONY TOMO is by the wheels. It's the Cowboys' year. He'll tell you."]},{date:"2026-09-20",title:"The road isn't always west",items:["THE WAY ON MOVED. North out of the Yard, west out of the Gloam, north out of the Mire, north and up out of the Boneyard, west out of Cloudreach. Follow the signs.","THE WHEEL HAS BEEN DRAWN: a gold rim with bulbs, a star hub and a proper pointer. The slices are exactly what they were."]},{date:"2026-09-20",title:"Bom Trady runs the Prize Counter",items:["THE GOAT HAS THE FLOOR. Bom Trady stands in the middle of the casino where the big ruby was, with glass prize cases all round him.","He does everything the ruby did: trade in your drops, buy gear, food and drinks, bank a ZCoin. Click him, or any case."]},{date:"2026-09-20",title:"Louder wins, a livelier floor",items:["EVERY WIN POPS. Any win at any table, even a small one, gets a gold banner, a jingle and a throw of sparks.","BIG WINS ARE CALLED OUT. Hit 10x or better and the whole casino hears about it, with confetti over your head.","EMOTES. Five buttons by the chat: cheers, GG, RIP, a wave, a dance. They float over your head.","HITS LAND HARDER. Sparks on every hit, gold CRITs on your biggest rolls, a puff when something drops.","THE FIGHT PIT HAS BEEN DRAWN: a flagstone floor, a raised ring of sand, torch posts, a ring bell and a proper fight card.","MORE LOOKS: three new hairstyles (bob, bun, pigtails), beards, ball caps in your team's colours, and the team list now says the full name.","The other gamblers show what they're playing over their heads, and every scene has its own light and shadows.","Store name colours and titles from eastcoin.vip now show over your head in here.","Stake buttons are 1, 5, 10 and 20. The half, double and max buttons are gone."]},{date:"2026-09-20",title:"Who are you?",items:["MAKE YOUR OWN LOOK. The first time you walk in you're asked who you are: pick a body, a hairstyle, your skin, your hair colour, a tee and your trousers.","WEAR YOUR TEAM. The tee comes in all 32 NFL cities' colours. If you've set a favourite team on eastcoin.vip, it starts on that.","THE MIRROR by the casino's front door changes your look any time, free.","DRESS CODE: inside the casino everyone shows up as themselves. Armour shows once you're outside.","The two old Cashier booths are gone. The big ruby does everything they did."]},{date:"2026-09-20",title:"Rugs, and Kellz",items:["EVERY SECTION OF THE CASINO HAS ITS OWN RUG NOW: slots, cards, the bar, wheels, coin flip, dice and the instant wins.","KELLZ HAS LANDED. Flight jacket, long hair. He's walking the main aisle.","People no longer flicker into an old sprite when they turn."]},{date:"2026-09-20",title:"New faces",items:["EVERYONE LOOKS LIKE SOMEONE NOW: six everyday looks for players without armour (you get one and keep it), and the other gamblers on the floor wear them too. No more tunics.","LIVIA, GAIUS AND AURELIA have been drawn.","RUSSIAN ROULETTE'S WINDOW now lists who's at the table and who's watching."]},{date:"2026-09-20",title:"A new carpet, and a proper Russian Roulette room",items:["THE CASINO HAS A NEW CARPET: dark, with big stars. You, the tables and everyone else stand out on it now.","SIX SEATS AT THE RUSSIAN ROULETTE TABLE. Sit down and you walk to your stool. Get shot and the room sees you drop.","A BELL ON THE CASINO FLOOR: when someone sits down, everyone hears it, with a Walk there button.","A WALL OF FAME beside the table: today's biggest pots, the longest winning run, and who's been shot the most.","BINO'S BAR CART: a shot for 1 ticket. It does nothing. The room hears about it."]},{date:"2026-09-19",title:"Russian Roulette takes centre stage",items:["RUSSIAN ROULETTE IS NOW THE MIDDLE OF THE ROULETTE ROOM, with Bino beside it.","The regular roulette wheel is away for repairs. It'll be back."]},{date:"2026-09-19",title:"New buttons, fewer words",items:["LESS READING EVERYWHERE: the wiki's guides, the casino's how-to board and what people say to you have all been cut down to a few short lines. Guides for things that are closed are gone.","RUSSIAN ROULETTE HAS A HAND-DRAWN CYLINDER, and Mines' bomb buttons match the rest.","THE GAME WINDOWS HAVE NEW HAND-DRAWN BUTTONS: a gold Spin / Bet / Drop button, wooden and gold pills for the games and the ZCoins / Tickets switch, wooden stake buttons, and proper poker chips at the roulette table.","FEWER WORDS. Every game's explainer is one short line now. The numbers you need are on the buttons and the pay table.","FISHING IN THE YARD AND THE GLOAM PAYS A LITTLE LESS: sardine 8, perch 10, trout 14, catfish 18 tickets. Fishing was paying as much as fighting out there; it's meant to be the quieter job for a bit less. The deeper waters were already right."]},{date:"2026-09-19",title:"Six scenes, thirteen new monsters, eight new fish",items:["TODAY'S JOBS NOW COVER ALL SIX SCENES: there's a job for every monster and every fish outside, and the board only hands you ones your levels can reach. The wiki's area pages say each scene's levels, its fish and what dying there costs, and there's a new guide: The road west.","NOTHING ATTACKS ON SIGHT ANY MORE. Every monster in every scene waits to be clicked, The House included: it's a game to relax in. The signs out there have been repainted.","THE WORLD OUTSIDE NOW RUNS IN TEN-LEVEL BANDS, one scene each, in a line west from the casino: the Yard (1-9), the Gloam (10-19), THE LANTERN MIRE (20-29), THE BONEYARD (30-39), Cloudreach (40-49) and THE THUNDERHEAD (50 and up). Walk anywhere you like. You can't START a fight until your Combat reaches the scene's level, and you can't fish its water until your Fishing does: the label over a monster or a pond tells you what it needs. Something already attacking you can always be fought back.","THIRTEEN NEW MONSTERS. The Gloam: Sulking Toadstool (10), Bone Idle (16). The Mire: Paper Twister (20), Card Counter (24), Loan Shark (26). The Boneyard: The Stagehand (32), One-Eyed Usher (36). Cloudreach: Brainstorm (40), Sea-Goat of the Upper Air (46). The Thunderhead: Storm Golem (52), Thunderwolf (58), Hail Drake (62), and THE HOUSE (70), a walking slot machine in the far corner. Four old faces are back too: the Angry Olive, the Goat in a Toga, the Sulking Revenant and the Angel of Minor Inconvenience.","EVERY SCENE HAS ABOUT TWO DOZEN MONSTERS OF FIVE KINDS, like the Yard, and the deeper the scene the more a kill pays. The last band pays noticeably more than Cloudreach.","TWO FISH TO EVERY WATER. The Yard's pond: sardine, and perch from Fishing 5. The Gloam's black pond: trout (10), catfish (15). The Mire's lake: lanternfish (20), mudskipper (25). The Boneyard's flooded crypt: bonefish (30), ghost carp (35). Cloudreach: sky eel (40), cloud ray (45). The sea under the Thunderhead: storm marlin (50), thunder squid (58). Every one heals when eaten and trades in at the Prize Counter. (Trout left the Yard: it's a Gloam fish now.)","DYING NOW COSTS A HOSPITAL BILL: a tenth of the tickets you're carrying (a twentieth in the Yard), capped by how deep you were: 250 in the Yard up to 6,000 in the Thunderhead. Nothing else is ever taken: not your gear, your bag, your ZCoins or your levels."]},{date:"2026-09-19",title:"Buffs work outside now",items:["THE GAME IS CALLED EASTSCAPE AGAIN. Same game, same address, old name.","EVERY BUFF IN THE GAME NOW HELPS YOU FIGHT AND FISH, not bet. The tables are eastcoin.vip's own and nothing in EastScape touches a bet, so the old gambling effects had nothing left to do. Same items, same names, same rarity, new jobs.","WORN GEAR: Gambler's ring, fish heal 50% more. Bookie's amulet, 5% more tickets. Loss adjuster's visor, 10% less damage taken. Card sharp's gloves, swing and fish 5% faster. Angel's ring, rare drops 15% more often. Stakeholder's loafers, still make your other buff gear 50% stronger.","DINNERS LAST 20 MINUTES AND DRINKS 10, and the clock only runs while you're outside: sit in the casino as long as you like. Chicken dinner +10% tickets from kills. Steak +10% speed. Chops, rare drops +25%. Fisherman's platter, fish bite more and a 10% chance of two on one line. Lager +5% tickets. Whiskey +15% speed but you take 10% more damage. The Safety Net, 20% less damage. Champagne, a real ZCoin is 50% more likely to drop.","LUCK IS FOR ZCOINS NOW: while you're lucky, a real ZCoin is 25% more likely to drop, and each kill or catch uses one up. Clovers still only come from fishing.","THE FINDS: a Free-play chip cashes for 100 tickets, the Devil's dice play for up to 1,000 of the tickets in your bag (triple, one time in three), and the Rewind watch is a full heal you can use mid-fight.","VIP IS EARNED BY TICKETS EARNED (kills, trade-ins, daily jobs), and every tier takes a little off every Prize Counter price: 2% at Bronze up to 10% at Diamond.","GONE: hunger and thirst (the cooler and the buffet are scenery now), and High Roller."]},{date:"2026-09-19",title:"Roulette and the Fight Pit play for ZCoins (or tickets)",items:["EVERY GAME IN THE BUILDING NOW TAKES ZCOINS OR TICKETS AND PAYS REAL ZCOINS. The last two joined today: ROULETTE upstairs and THE FIGHT PIT. Tickets stand in at 1,000 a ZCoin, as everywhere else, and the usual limits apply: 1 to 20 a bet, ten bets an hour at each game, 400 an hour out.","ROULETTE: a spin a minute, and everyone in the room is on the same spin. ONE SPOT A SPIN: red or black, odd or even, high or low, a dozen, or a single number (a number pays about 37x). 40 seconds to bet, then the ball rolls.","THE FIGHT PIT: a fight every minute and a half, the same fight for the whole room. Back one side, once: the price is on the card (a long shot pays about 4x). 40 seconds to bet, then they go at it, and you can watch it from the ring or from the window.","Both can be checked afterwards like any other game: the seed is published when the round closes.","ALSO: a bank chest in the Yard (by the road in from the casino), two revolvers on the Russian Roulette table so nobody mistakes it for the other one, Bino dealing it, and a real ZCoin or a rare find that lands on a full bag now goes to your bank instead of being lost."]},{date:"2026-09-19",title:"Russian Roulette is in the Roulette Room",items:["THERE'S A NEW TABLE UPSTAIRS: Russian Roulette, on the left of the Roulette Room. It is eastcoin.vip's own table, the very same one, so you may find yourself sitting across from someone playing on the website.","HOW IT GOES: the first to sit opens the table and starts a 30 second clock. Everyone pays 20 ZCoins. Each round the cylinder holds one live chamber and the seats pull in turn; whoever gets it is out. Reload, and again, until one is left. THE LAST ONE STANDING TAKES EVERY BUY-IN, and the house takes nothing. Alone when the clock runs out? Your 20 comes back.","ZCOINS ONLY at this table: no tickets. The site's limits apply (ten tables an hour, 400 ZC an hour out), and every table's seed can be checked afterwards from the window.","The classic roulette wheel next to it still takes tickets for now.","TICKETS STAY ON YOU. They can't be dropped, banked or handed over in a trade any more: they only leave your bag by being spent. Any tickets you had in the bank are back in your bag."]},{date:"2026-09-19",title:"Slots and Dice play for ZCoins (or tickets)",items:["SLOTS AND DICE ARE REAL NOW. Same machines, same dice table, same 'Bet with' switch as the other tables: ZCoins, or tickets at 1,000 a ZCoin, and a win pays real ZCoins. The usual rules: 1 to 20 a bet, ten plays an hour at each game, 400 an hour out, and a seed you can check afterwards.","THE SLOTS JACKPOT IS REAL ZCOINS. 2% of every spin feeds one pot everybody shares. Three sevens wins it: a 20 ZC spin takes all of it, a smaller spin takes its share and the rest stays. It stops growing at 500 (anything over waits and starts the next pot), and it restarts at 50 after a win.","Slots pay tables are a little different from the old chip machines: about one spin in three pays something, the biggest regular prize is three diamonds at about 61x, and three sevens is the jackpot rather than a price.","DICE pays the fair price for your number: under 50 is about 2.04x, under 5 is 25x.","Still tickets in, tickets out: roulette upstairs and the Fight Pit. They are next."]},{date:"2026-09-19",title:"One currency: tickets. And the tables take tickets or ZCoins",items:["CHIPS AND CASH ARE GONE. There is one currency in EastScape now: TICKETS. Kills, catches and daily jobs pay them, the Prize Counter takes them, and every table takes them. Your bag panel shows Tickets and your real ZCoins side by side. (Chips anyone was holding were wiped: the game is still in testing.)","THE SIX REAL TABLES TAKE ZCOINS OR TICKETS. Coin Flip, the Wheel, Higher or Lower, Mines, Plinko and Scratch-Off have a 'Bet with' switch: ZCoins (your own) or Tickets, where 1,000 tickets stand in for each ZCoin. It is the very same eastcoin.vip game either way, same limits, same fairness seeds, and A WIN IS ALWAYS PAID IN REAL ZCOINS.","Ticket bets have an allowance: 50 ZCoins' worth an hour. Banking ZCoins you found shares it. When it runs out the Tickets side waits for the hour to roll on; ZCoin bets still work.","THE RUBY'S SCRATCH TICKETS AND ITS EXCHANGE ARE GONE: betting tickets is the way tickets become ZCoins now. The Prize Counter still banks any ZCoins you find, and still sells gear, dinners, drinks and Casino scrolls.","Slots, dice, roulette upstairs and the Fight Pit take tickets and pay tickets for now. They are next in line to become ZCoin games.","THE HIGH ROLLER ROOM IS CLOSED for a refit. Vince is still on the door, and still won't tell you anything."]},{date:"2026-09-20",title:"The real tables are in the building",items:["COIN FLIP, THE WHEELS, HIGHER OR LOWER, MINES, PLINKO AND SCRATCH-OFF ON THE CASINO'S MAIN FLOOR NOW PLAY FOR REAL ZCOINS, from your real eastcoin.vip balance. They're the same windows you know; behind them is the site's own casino. Click a table and it opens the moment you click (your character strolls over on its own).",`They play by the site's rules, exactly: 1 to 20 ZCoins a bet, ten plays an hour at each game, 400 an hour out, the same fairness seeds (there's a "check the last one's seed" link in the window), the same Daily Jackpot, and your results show on your eastcoin.vip profile. Nothing in EastScape (luck, dinners, drinks, gear, hunger, VIP) touches these tables.`,"COIN FLIP AND THE WHEEL ARE SHARED ROUNDS, as they are on the site: one flip every 30 seconds and one spin a minute for the whole room. Get your bet in and the window counts you down to it.","A GAMES BUTTON (top left, or press G) opens them from anywhere on the main floor, and a strip across the top of the window hops between the six.","HIT A LIMIT, OR OUT OF ZCOINS? That's what outside is for: every kill and catch can drop a real ZCoin, and tickets buy Ruby scratch tickets at the Prize Counter.","STILL CHIPS: the slots, the dice pit, roulette upstairs, the Fight Pit and the whole High Roller Room (which keeps its own chip versions of every table)."]},{date:"2026-09-20",title:"Tickets, the Prize Counter, and real ZCoin drops",items:["THE WORLD OUTSIDE PAYS TICKETS NOW, like an arcade. Every kill and every daily job pays tickets instead of Cash, and the numbers over monsters and fishing spots have a little ticket beside them so nobody mistakes them for ZCoins. A ticket is worth exactly what a dollar was: a cow still pays about 28.","THE PRIZE COUNTER is the big ruby in the middle of the casino (both Cashier windows work too). It takes your drops and fish for more tickets, and it's the one place tickets are spent: CASINO CHIPS to play with (1 ticket, $1, or all of it in one click), drinks, dinners and Casino scrolls, a set of arms and armour for every level (Brutus has packed up his pitch in the Yard), and Ruby scratch tickets.","RUBY SCRATCH TICKETS cost 1,000 tickets and pay 25, 10, 5 or 2 REAL ZCoins, or nothing. Five an hour at most. Trading Cash straight for ZCoins is gone: this is the way now.","REAL ZCOINS DROP, RARELY. Any kill, and any catch at a pond, can turn up an actual ZCoin (one time in twenty it's five of them). About 2 to 5 an hour if you're at it steadily, a little more the deeper you go. It lands in your bag; BANK it at the Prize Counter and it goes onto your eastcoin.vip balance. Banking counts toward the same 25-an-hour allowance as scratch tickets, and anything over waits in your bag. Everyone in the scene hears about it.","Your bag panel shows Tickets and Chips side by side. The free daily wheel and anything you win at the tables are still chips."]},{date:"2026-09-20",title:"Outside is simple now: fight, or fish",items:["THE WORLD OUTSIDE THE CASINO IS MONSTERS AND A POND. Go outside, click a monster, get paid: Cash, its one drop, and a roll at something rare. That's the job. If you'd rather not fight, every scene has a pond. Mining, woodcutting, smelting, smithing and cooking are gone from the world (your levels in them are kept, in case they come back).","KILLS ARE TWICE AS FAST. Every monster has half the hit points, so a fight at your own level is about 8 to 12 seconds. Each kill pays a little less and there are twice as many of them, so an hour's fighting is worth what it was, with twice the drops and twice the rare rolls.","MORE MONSTERS. The Yard has 24 (chickens by the gate, then cows, rotten tomatoes, hornworms, and boars at the far end). The Gloam has 18. Cloudreach has 13, including Thunder Geese at the far west end for anyone past level 50.","FISHING is the quiet job. Your chance of a bite now grows with your Fishing level, there are five spots at every pond, and the fish are worth more out deeper: it pays somewhat less than fighting does (two thirds to nine tenths, depending on your level), for none of the risk. It's the ONLY place lucky clovers come from. And a fish is food straight out of the water: click one to eat it.","BRUTUS SELLS GEAR FOR EVERY LEVEL, in the Yard by the pond: bronze at Combat 10, emerald at 20, diamond at 30, dragonstone at 40, onyx at 50. Bronze costs what it did; onyx is a couple of hours' fighting. The GOOD stuff still only drops.","ALL SIX PIECES OF GAMBLING GEAR ARE RARE DROPS NOW. Gambler's ring: boars and hornworms. Bookie's amulet: highwaymen and gnashers. Loss adjuster's visor: moths and Tax Wraiths. Stakeholder's loafers: ghouls, rams and geese. Card sharp's gloves and the Angel's ring: where they were.","DEX HAS A KITCHEN. The four dinners (Well Fed, plus an effect each) are on his menu with the drinks.","RARES FOUND. The Quests tab has a collection: every rare there is, greyed out until you've found one, with a count. Hover one to see what drops it.","Today's jobs are kills and fish only. New characters start with a rod and $25."]},{date:"2026-09-20",title:"Simpler drops: Cash, its one thing, and a rare",items:["Every monster now drops the same three lines. CASH, always. ITS ONE THING, always: chicken from chickens, beef from cows, tomatoes from rotten tomatoes, husk from hornworms, pork from boars, hide from highwaymen, emerald ore from gnashers and moths, a receipt from Tax Wraiths, diamond ore from ghouls and the Understudy, cobweb from the spider, dragonstone ore from rams. And A RARE: one roll a kill, at most one a kill.","The rare is either one of the monster's own named pieces (the highwayman's mask, the Bog-hound hide, the wraith's hood, the Ring of Mild Menace, the Lantern shield, the Eight-league boots, the Grudge knife from rams, Card sharp's gloves, the Angel's ring) or a casino find (house chips, a free-play chip, a mystery box, Devil's dice, a rewind watch). A piece of gear dropping is announced to everyone in the scene. Each monster's wiki page lists its rares and the chance of each.","A kill is worth exactly what it was: the Cash makes up the difference.","Gone: bones, pits, feathers and tusks (what you have still sells), and the long tables that gave every piece of emerald and diamond gear a tiny chance from late monsters. That gear is smithed at the camp.","Two recipes changed to match: the Gambler's ring is 2 bronze bars and a piece of pork; the Bookie's amulet is 3 bronze bars and 2 hides (hide comes from highwaymen now)."]},{date:"2026-09-20",title:"One way out: the Yard, the Gloam, Cloudreach",items:["THE WORLD IS ONE LINE NOW. The casino has one arch (OUTSIDE), and it leads to three scenes in a row: the Yard (levels 1 to 14), the Gloam (15 to 29) and Cloudreach (30 and up). Every one of them has its rocks, trees and fish AND its monsters, so whatever you and your friends are doing, you're doing it in the same field. The further out you walk, the more everything is worth.","THE CAMP. In the Yard, between the pond and the tin rocks: a furnace, an anvil, a cooking range, and Brutus (who moved out there with his shop, and still buys what you smith). It's the only place to smelt and smith, it's right beside the rocks, and you pass it on every walk home. Anything you make sells for double, so make it before you cash in.","The Yard's animals live at its west end: chickens, cows, rotten tomatoes, hornworms and boars. None of them attack first.","The Gloam now has highwaymen, lantern moths, Bog Gnashers and Tax Wraiths. Gnashers (the north clearing) and wraiths (the far south-west) come for you on sight; signs say where, and they can't reach the rocks, the pond or the path. Cloudreach has Sorry Ghouls, the Understudy, Cumulus Rams, and one Chandelier Spider in the middle of the south that you should not wander into by accident.","There's a campfire to cook on in the Gloam and in Cloudreach. Smelting and smithing are only at the Yard's camp.","The Paddock, the Rough and the Boneyard are closed (their monsters moved into the line). If you logged out in one, you'll wake up in the casino. The Forum keeps the bank, the Exchange and Charon's cart; its smithy has moved to the camp.","Cashing in is still only inside the casino, at the Ruby or a Cashier's window."]},{date:"2026-09-20",title:"A free spin every day, VIP tiers, and the Winners' Wall",items:["THE DAILY PRIZE WHEEL is open: the big wheel by the casino's front door. One free spin a day: Cash from $50 to $1,000, lucky clovers, a lager, free-play chips, Casino scrolls, a mystery box, even a black house chip. Spin every day: each day in a row adds 10% to the Cash slices, up to +70%. It resets at midnight, Central. It says FREE SPIN over it until you've had yours.","VIP TIERS. Every dollar you ever bet counts, win or lose: Bronze at $10,000, Silver at $50,000, Gold at $250,000, Platinum at $1,000,000, Diamond at $5,000,000. Your tier shows as a coloured diamond by your name for everyone to see, and each tier raises every table's limit (Bronze +$50 up to Diamond +$1,000). Your progress is under your bag.","THE WINNERS' WALL, on the back wall right of the Roulette door: today's five biggest single wins, from any table, roulette and the Fight Pit included. Win $500 or more on one bet to get on it. Wiped at midnight, Central."]},{date:"2026-09-20",title:"The House Ruby pays in ZCoins, and the High Roller Room",items:["THE HOUSE RUBY NOW TRADES CASH FOR REAL ZCOINS. Click the big ruby in the middle of the casino floor. $100 of Cash is 1 ZCoin, paid straight to your eastcoin.vip balance. You can take up to 25 ZCoins in any hour.","RUBY TICKETS. $500 buys a ticket you scratch right there: it pays 25, 10, 5 or 2 ZCoins, or nothing. A ticket uses 5 of your hour's 25 whatever it pays. On average a ticket pays a little less than trading straight: it's the same money with a story.","If the Ruby ever can't tell whether a trade went through, your Cash is HELD, not lost. Open the Ruby again a minute later and it finishes the job or hands the Cash back.","THE HIGH ROLLER ROOM. There's a new door in the Fight Pit's back wall, and Vince in front of it. He lets you in with $2,500 on you, or with the High Roller buff (which you get from fighting). Inside: the same games at TEN TIMES the limits, $100 minimum, the good buffet, and Sterling. Luck and buffs cover the first $1,500 of any bet, so a $5,000 flip is a big swing, not a better deal.","The wiki's words now load when you first open the wiki, which makes the game itself start a little faster."]},{date:"2026-09-20",title:"EastScape: three jobs, three rewards, and a bar",items:["The game is called EastScape now.","FIGHTING PAYS PROPERLY. Every monster carries Cash on top of its drops, measured so a fighter of the right level earns a little MORE a minute than a miner of that level, for the risk. A cow is worth about $47 a kill, a boar $82, a Tax Wraith $240, the Understudy $350. Before this, everything past a cow paid worse than the rock next to it.","SKILLING is now the only way to get Lucky: clovers turn up while you gather (and, rarely, a horseshoe). Monsters no longer drop horseshoes; the ones you have still work.","FIGHTING has its own rewards. Any kill can turn up a house chip (red $250, black $1,000, gold $5,000), a free-play chip (your next bet is on the house, up to $100), a mystery box, Devil's dice (within two minutes of a win: triple it, one time in three, or lose it) or a rewind watch (within a minute of a loss: it never happened, up to $500). Bigger monsters turn them up far more often. One kill in eight makes you a HIGH ROLLER: every table takes double from you for your next 10 bets over the normal limit. Two pieces of gambling gear only ever drop: Card sharp's gloves (wins pay 1% more profit) and the Angel's ring (1 lost bet in 200 comes back whole).","CRAFTING makes what you keep. At the anvil: the Gambler's ring (half the hunger and thirst), the Bookie's amulet (+$250 on every table), the Loss adjuster's visor (1% of every loss comes back) and the Stakeholder's loafers (your other gambling gear is 50% stronger). At the range, four dinners: every one leaves you WELL FED (no hunger or thirst) for 30 bets or more, and adds an effect of its own. Each takes something dug up AND something killed.","DEX'S BAR IS OPEN. Talk to Dex: lager, The Safety Net, whiskey and champagne each change your next 10 to 15 bets. One drink at a time. $300 buys a round for everyone on the floor.","CASINO SCROLLS. Dex sells them for $50. Click one anywhere (not the Wilderness, not mid-fight) and you're back on the casino floor.","YOUR ISLAND IS BACK. Charon has a cart in the square out the casino's front door. Plant wheat or tomatoes on your island and they grow while you're away; upgrades and themes are sold from the cart.","Everything that's on is in the Buffs bar, top right. Hover one to read it. Your table limit on every game follows your buffs. The ceiling: gear alone can never take a game over 100% back, and everything stacked with luck stops at about 104%, for as long as the dinner and the drink last.","WHAT THINGS MADE ARE WORTH changed. A made thing sells for double the RAW materials in it, plus a quarter for each further step: a bronze bar is $40, a bronze sword $100 (it was $160, which paid a miner with an anvil twice what anyone else could earn). The Cashier now tells you when something in your bag is worth more made into something first.","The Cashier no longer buys anything you can wear or hold (so a click can't sell your sword). Brutus, at the Forge, buys what you smith.","Today's paid jobs moved to the Quests tab, and there are jobs for MAKING things now (bars, swords, dinners). Under your bag: thirst and hunger, your cash, and what your bag is worth, each in its own box."]},{date:"2026-09-20",title:"The Fight Pit",items:["There's a second door in the casino's back wall, in the slots room, with FIGHTING lettered over it. Behind it: a sand pit, a rail to lean on, and two monsters who have been told the other one said something about their mother.","One fight at a time for the whole room. You get 30 seconds to put money on one of them (up to $500, one side only), then a proper 40-second scrap with misses and the lead changing hands, then the winners are paid, ten seconds to gloat, and the next pair comes out. Click the pit or either betting board.","There are two water coolers and two buffets along the pit's back wall, so you never have to leave the rail (or miss a fight) to eat or drink.","It is pure luck. The price on each fighter comes from its level: a chicken against a revenant pays big, because it mostly loses. Whoever you back, the house keeps 5%. Nothing else decides it.","The House Ruby in the middle of the casino floor now takes your loot: click it to cash in, the same as a Cashier's window."]},{date:"2026-09-20",title:"Hunger and thirst",items:["Gambling is thirsty work. Every bet takes a little off your Thirst and your Hunger (about forty bets to a drink). Under 20% on either, the tables won't take your bets until you've had something.","The water cooler and a new buffet stand side by side on the card room's back wall, next to the bar. Each click gives you back 20%, free, as many clicks as it takes.","Cooked food from your bag fills you up too (25% a piece), so a fisherman never goes hungry.","Both meters are in the wallet under your bag and on every table. Working, fighting and standing about cost nothing: only betting does."]},{date:"2026-09-20",title:"A smaller bag, a wallet, and a Buffs bar",items:["Your bag holds 20 things now, not 30, so it fills and sends you back past the tables to the Cashier. If you had more than 20, the extra went to your bank: nothing was lost.","Under the bag is your wallet: your Cash, what the loot in your bag would sell for (it turns green when there's money to collect), the slots jackpot, today's three paid jobs with their progress, and a line on what to do next.","Top right of the game is now a Buffs bar. It shows everything that's improving your odds. There's one kind today (Lucky, from clovers and horseshoes); it's built to hold several.","The casino looks lived in: a janitor's bucket and a wet-floor sign by a spilled drink, coats by the doors, a suitcase nobody came back for, and chips, cards, losing slips and one shoe on the carpet."]},{date:"2026-09-20",title:"The casino floor, laid out like a real one",items:["Every kind of game now has its own roped-off room, named in gold on the carpet at its way in. SLOTS fill the north-west: three banks of machines back to back, plus the wall. WHEELS and COIN FLIP share the south-west. The CARD ROOM (Higher or Lower, and the blackjack and poker tables that open soon) is next to THE BAR in the north-east. The DICE PIT and INSTANT WINS (two Plinko machines, two Mines tables, two Scratch-Off kiosks) are in the south-east.","Later the same day: fewer ropes (just a short run either side of each way in), and the rooms are broken up with the things a casino is full of. Stools at the slot machines, the tables and the bar (stand on one: it's where you'd sit), soda and snack machines, a water cooler, bins, planter boxes, and a smoking section in the north-east corner with club chairs, ashtrays and its own haze.","The velvet ropes are real: you go into a room through its gap. The long aisle from the skilling arch to the fighting arch stays clear, with a Cashier at each end and the House Ruby in the middle.","Dex, DookieBetts and the regulars have moved to where they belong: Dex behind the bar, Dookie in the dice pit, Whale Wendell in the card room."]},{date:"2026-09-20",title:"Three more places to make money",items:["The skilling line now runs three maps deep out the WEST arch. Past the Workyard is the Gloam (level 15): emerald rock $15, gloomwillow $15, lanternfish $16, and diamond rock $22 at Mining 25. Past that is Cloudreach (level 30): dragonstone $30, skyash $28, sky eels $30, and storm-struck onyx $40 at Mining 40.","The fight line runs three deep out the EAST arch. Past the Rough is the Boneyard: Bog Gnashers and Lantern Moths by the gate, Sorry Ghouls and Tax Wraiths (who carry real Cash) in the middle, a Chandelier Spider and the Understudy at the far end. Several of them come for you on sight. Combat 20 at the very least.","There are no monsters on the skilling line any more, and the workshop in town is still the one place to make things. Everything you bring back from the new maps smelts and sells for double like everything else.","More jobs on the task board now that there are places to do them: emeralds, lanternfish, gloomwillow, diamonds, dragonstone, boars, highwaymen, moths and ghouls."]},{date:"2026-09-20",title:"Go broke, go get more",items:["Every table has been rebuilt to look and play like the casino on eastcoin.vip: a dark table, one gold button, what it pays beside the board, and your sitting's bets, net and best win. Mines has the tile board and the ladder, Higher or Lower deals real cards and shows your run, Plinko drops a ball through real pegs, Scratch-Off has foil you actually scratch, Slots has spinning reels and the jackpot on the table, Dice is a slider and a track, and the Coin flips.","Everything out in the world now has its price written over it: $10 a rock, $10 a log, and so on. Monsters show roughly what a kill is worth.","New: the Cashier, a window by each arch on the casino floor. One click turns everything you found and made into Cash. It leaves your tools, charms and anything you could wear alone.","Making things pays DOUBLE. A bronze bar sells for twice the ore in it, a sword for twice the bars, cooked food for twice the raw. The workshop out the front door has a furnace, an anvil and now a cooking range.","Tools just work from your bag: no more wielding a pickaxe before you can mine.","A second fight map, the Rough, east of the Paddock: hornworms, boars, highwaymen carrying actual Cash, and two Bog Gnashers at the far end. Come at Combat 8 or so.","The casino floor has been re-planned into neighbourhoods so there's room to wander: Slots Alley down the west wall, the Coin Corner, the Card Pit, the Bar, and the Drop Zone (Mines and Plinko) in the south-east. The entrance is clear again.","Cash is written as dollars now ($250), because that's what it is."]},{date:"2026-09-19",title:"Five more games, right where you walk in",items:["Wheel, Higher or Lower, Mines, Plinko and Scratch-Off now stand round the rug you arrive on, with a Coin Flip table beside them. The same games as the site's casino, played for Cash.","Wheel: red or black pays 1.97×, the gold sliver 58×. Plinko: twelve rows, 25× at the edges. Scratch-Off: three of a kind, up to 100×.","Higher or Lower and Mines are runs: every right call or gem multiplies your stake and you cash out when you like. A run is kept for you if you close the window, walk away or the game restarts.","Luck works on all of them, and every table returns about the same, so play the one you enjoy."]},{date:"2026-09-19",title:"The casino floor fills up",items:["The hall has furniture now: the House Ruby behind velvet ropes in the middle, poker and blackjack tables (opening soon), a prize wheel, cocktail tables, a jukebox, a grand piano, a cash machine that thankfully doesn't work, and art on the back wall.","It moves: spotlights drift over the carpet, the lamps breathe, the JACKPOT sign buzzes, the slot machines blink. Turn on Reduced motion in Settings and it all holds still.","Meet the regulars: Parlay Pete, Nana Jackpot, Rent Money Randy and Whale Wendell. None of them should be listened to. There are a few players at the machines now too."]},{date:"2026-09-19",title:"A simpler GAMBA: bigger tiles, luck, and a smaller world",items:["Every area is now twice as wide and twice as tall, and the view follows you as you walk. The casino is a proper hall: more slot machines, three coin tables, three dice tables.","Luck: want better odds? Work in the Workyard and you'll find lucky clovers; monsters in the Paddock drop lucky horseshoes. Click one in your bag and your next bets are lucky: every win pays 2.5% more. It shows top-right and at every table.","The world is small on purpose for now: the casino (with its Roulette Room), the town, the Workyard and the Paddock. The roads out of town are closed; more opens later. Anyone who was standing somewhere else wakes up in the casino.","Combat is ONE skill now. Attack, Strength and Defence merged into Combat (you keep the best of your three levels), and stances are gone: hit things, get better at all of it."]},{date:"2026-09-19",title:"Welcome to GAMBA",items:["The game has a name: GAMBA. The casino is now the middle of the world, and where everyone starts (and wakes up after dying).","Four ways out of the casino: north is Floor 2 (the Roulette Room), the west arch leads to skilling (the Workyard: trees, copper, tin, wheat and a fishing pond), the east arch to fighting (the Paddock: chickens, cows and rotten tomatoes), and the front door to town for crafting and the market.","The casino floor is bigger, with more slot machines. Everything that was in the world before is still there, through the front door.",'New here? Dex gives you the House Tour: a free chip, a first game, a first job and a first payday, with the next step always shown top-left. Anyone can ask him for it, or ask "What should I do next?" any time.',`The ways out of the casino are labelled, and there's a "How GAMBA works" board by the front door.`]},{date:"2026-09-18",title:"The Casino",items:["The Forge building in the Forum is now the Casino. Brutus still works his smithy right outside.","Inside: slots, coin flip and dice for Cash (never ZCoins), a bar, sofas, and Dex the Dealer.","Round the rug where you walk in: Wheel, Higher or Lower, Mines, Plinko and Scratch-Off, the games from the site's casino, for Cash. Higher or Lower and Mines are runs you cash out of; a run is kept for you if you leave the table.","The task board moved in too: three daily tasks each, picked for your levels, paid in Cash.","Through the door at the back: the Roulette Room, one shared table where everyone plays the same spin.","The slots have a jackpot everyone feeds: three sevens wins it."]},{date:"2026-09-18",title:"A simpler market",items:["The Exchange is now a two-sided market: Buy shows the newest listings with a search and an item picker; Sell shows your offers and people who want what you have.","Buy straight off a listing, or post a buy offer. Sell from your bag or your bank.","Nothing to collect any more: purchases and takings go straight to your bank, and you get a chat line every time something of yours sells or fills.","First hit claims a monster: once you've hit it, nobody else can attack it until the fight ends or you leave it alone for 10 seconds (not in the Wilderness). Busy areas also respawn faster."]},{date:"2026-09-18",title:"The Gloam and Cloudreach",items:["The Gloam, west of the Olive Grove: a wood where it is always five minutes before dark. Emerald and Diamond ore, Gloomwillows, and lanternfish in the black pond.","Cloudreach, north off Tomatoe Hill: an island of cloud in the open sky. Dragonstone and storm-struck Onyx ore, Skyash trees, and sky eels fished straight out of the sky. The Angels of Minor Inconvenience attack on sight.","Every tier of bar now smelts from its own ore (Onyx also wants one Wilderness grimstone).","Six new monsters, up to level 55. Your body armour now shows its tier on your character.","Right-click any item for its wiki page, and the xp tracker tells you when your next level lands."]},{date:"2026-09-18",title:"Attack, Strength, Defence, Smithing and five gear tiers",items:["Melee is now three skills: Attack (accuracy), Strength (max hit) and Defence. Your old Melee level carried over into all three.","Pick a stance in the Skills tab to choose which skill your fights train.","Gear goes from Bronze up through Emerald, Diamond, Dragonstone and Onyx, ten levels apart. Weapons swing at different speeds.","A new skill, Smithing: smelt ore into bars and hammer bars into gear. Brutus still sells bronze.","An amulet slot, hover-to-compare on gear, an xp tracker and hiscores.","Fishing, mining, chopping, picking, cooking and smithing now stop after 3 minutes with no clicks. The resources never run dry, but you have to be there."]},{date:"2026-09-18",title:"Cooking, eating and the Forge",items:["A new skill, Cooking: cook raw fish and meat at the Farmhouse range, your cottage hearth or a campfire. Food can burn, less as you level.","Click cooked food in your bag to eat it and heal, even mid-fight.","Brutus the Smith has opened the Forge in the Forum: tools and the Bronze set for sale, and he'll buy what you gather.","A bag slot now holds up to 99 of anything (Cash has no limit). Extra spills into the next slot; the bank still holds any amount.","Bronze gear needs a Melee level to wear, and the Bronze cuirass changes your look from recruit to gladiator."]},{date:"2026-09-18",title:"Bigger islands, the Far Shore, and your cottage",items:["Island upgrades from Charon: a Bigger island (5,000 Cash) with 12 plots and 9 pedestals, then The Far Shore (20,000 Cash): a bridge to a second island with 8 more plots, 6 more pedestals and a lighthouse that points the wrong way.","Your cottage opens: walk in through the door. A hearth, a bed, a chest and a lot of empty floor, for later.","Wilderness monsters take longer to come back the tougher they are: from a minute up to three."]},{date:"2026-09-18",title:"The Wilderness and your own island",items:["The Wilderness is open, down the pit on the Ludus Farm (Melee 10). Anyone can attack anyone. The Cage, by the rope, is for fights that cost nothing.","Die outside the Cage and there's a 1 in 4 chance you drop something you're wearing. Your killer has a minute to grab it.","The Deep Wild: Tax Wraiths, Chandelier Spiders and the Sulking Revenant come looking for you. Grimstone, Deadwood and the Black Pool give 50% more xp, and sometimes a glimmering geode.","New gear from the Wilderness: the Grudge knife, Tax Wraith hood, Bog-hound hide, Lantern shield, Ring of Mild Menace, and Eight-league boots, the first thing that makes you walk faster.","Everyone has an island. Charon the Ferryman at River Bend rows you there. Grow crops while you're away, show off six things, pick a theme, and visit other people's islands."]},{date:"2026-09-18",title:"The Forum opens north and east",items:["The Forum now has gates on all four sides. The Forge moved over to make room for the north road.","North: Tomatoe Hill. Tomatoe vines to pick, the Big Tomatoe, Nonna Tomatoe (it has an e), Rotten Tomatoes and Tomatoe Hornworms. And a golden vine for much later.","East: the Via Appia. Cypress trees to chop, milestones, a toll post with Centurion Vibius, Highwaymen (level 12, they drop Cash and sometimes a mask), a very stubborn mule, and a marble outcrop for later. The road is washed out past the barricade.","New things: tomatoes, golden tomatoes, hornworm husks, marble, and the Highwayman's mask (a helmet)."]},{date:"2026-09-18",title:"The Bank, a lived-in farmhouse, and movement speed",items:["The Bathhouse is now just the Bank, inside and out. It has a red runner to the counter, potted palms, benches, banners, a vault door, and a statue of its first depositor.","The Farmhouse has a rug, stools, shelves, drying herbs, a window, a flour sack, a spare bucket and a cat in a tiny helmet.","Movement speed is now a number the server keeps. Boots, pets and potions will raise it later: the first +20% counts in full, the rest counts half, and it caps at +50%. Your Equipment tab shows your speed.","Your Cash and your name and picture now sit at the top right."]},{date:"2026-09-18",title:"Buildings, the bank, the Exchange and trading",items:["Buildings you can walk into: each is its own room. The Bank in the Forum and the Farmhouse on the Ludus Farm are open.","The bank: 200 item slots, unlimited stacks.","The Exchange: a market stall in the Forum with sell offers and buy orders that match on their own, a board to browse, and a 1% cut on sales.","Trading face to face: click another player.","The currency is now called Cash.","This wiki.","Level-up celebrations, in chat and on screen.","The simulated players talk a lot less.","Picked wheat is soil you can walk on until it grows back, so every stalk can be reached.","A clearing round the copper at River Bend."]},{date:"2026-09-18",title:"The server",items:["The game moved to its own game server: everything is decided there, and your character saves itself continuously.","Game-wide chat (bottom left, closed until you open it).","Settings, and an admin panel for the builder.","Your own movement is instant: the page walks you straight away and the server keeps it honest.","What you gather pops up over your head."]},{date:"2026-09-18",title:"The world",items:["Four areas: Ludus Farm, River Bend, the Forum and the Olive Grove.","Skills: Melee, Hitpoints, Fishing, Harvesting, Mining and Woodcutting.","Quests from Bom Trady and Old Tullius.","One high-level resource in every area, for later: the Ancient Yew, the Moonlit Eddy, the Fallen Star and the Sun Olive tree."]}];const SKILL_EXTRA={breeding:(G,H)=>{const B=G.BREED,n=x=>Number(x).toLocaleString(),hrs=ms=>`${Math.round(ms/36e5)} hours`;const eggs=Object.entries(G.EGGS).map(([k,e])=>`<tr><td>${H.ico(k)} ${H.wl(`items/${k}`,H.esc(G.ITEMS[k]?.name||k))}</td><td>${hrs(e.ms)}</td><td>${n(Math.round(e.xp*.1))}</td><td>${n(e.xp)}</td></tr>`).join("");return`<h3>How it trains</h3>
      <table class="tbl"><tr><th>You do</th><th>Breeding</th><th>Takes</th><th>xp when you start</th><th>xp when you collect</th></tr>
      <tr><td>Breed two Ordinary pets into a Greater one</td><td>${B.greater.lvl}</td><td>${hrs(B.greater.ms)}</td><td>${n(B.greater.xpStart)}</td><td>${n(B.greater.xpEnd)}</td></tr>
      <tr><td>Breed two Greater pets into a Legendary one</td><td>${B.legend.lvl}</td><td>${hrs(B.legend.ms)}</td><td>${n(B.legend.xpStart)}</td><td>${n(B.legend.xpEnd)}</td></tr></table>
      <h3>Hatching eggs</h3><p>An egg goes in a hatchery with ${B.hatch.food} Ordinary pet food. You get a little xp when it goes in and the rest when it hatches.</p>
      <table class="tbl"><tr><th>Egg</th><th>Takes</th><th>xp when it goes in</th><th>xp when it hatches</th></tr>${eggs}</table>`},fungiculture:(G,H)=>{const n=x=>Number(x).toLocaleString(),mins=ms=>ms>=54e5?`${Math.round(ms/36e4)/10} hours`:`${Math.round(ms/6e4)} minutes`;const rows=Object.values(G.FUNGI).map(F=>`<tr><td>${F.lvl}</td><td>${H.ico(F.yields)} ${H.wl(`items/${F.yields}`,H.esc(G.ITEMS[F.yields]?.name||F.yields))}</td><td>${mins(F.ms)}</td><td>${n(F.xp)}</td><td>${n(Math.max(10,Math.round(F.xp*G.FUNG.wildXp)))}</td></tr>`).join("");return`<h3>How it trains</h3><p>Three ways: making <b>compost</b> at the bin (the table below), harvesting a <b>fungus bed</b> in your cellar, and picking a <b>wild cluster</b> (one pick each a day).</p>
      <table class="tbl"><tr><th>Level</th><th>Shroom</th><th>Bed grows in</th><th>xp a harvest</th><th>xp a wild pick</th></tr>${rows}</table>`}};const SKILL_GUIDE={tinkering:"Salvage what you don't need into parts at Sprocket Sal's Scrap Bench in the Yard, build gadgets out of them, and give parts to the World Projects the whole server builds together. Salvaging pays xp (up to 40 an item), building pays more the higher the gadget, and finishing a project's stage pays the most.",breeding:"Breed two pets in the pet pen on your island to make a better one, and hatch eggs in a hatchery. Starting a pair gives some xp and collecting the baby gives far more. Every pairing and every hatch trains it.",fungiculture:"Grow mushrooms in the cellar under your island, and pick the wild clusters on every map once a day. Compost from the bin in the cellar trains it from level 1 and feeds the beds.",cooking:"Cook raw fish and meat at a range, hearth or campfire. Each food needs a level to cook and stops burning at a higher one. Cooked food heals when you eat it.",melee:"Fight monsters with a weapon in hand. Every point of damage you deal gives Melee xp, and a little Hitpoints xp with it. (With a bow in hand it is <b>Archery</b> xp instead.) Your combat level is Melee, Archery and Hitpoints together. One skill does all three jobs — you land more swings, you hit harder and you get hit less — and it is what better weapons and armour ask for.",hp:"Goes up alongside the fighting skills as you deal damage: fully with a melee weapon, a third as fast with a bow or a wand. Your Hitpoints level is your maximum health.",fishing:"Hold a fishing rod and click the water. Every spot holds two fish: the second is better, needs a higher level, and turns up about a third of the time once you can catch it.",farming:"Pick wild wheat in the Yard — the only gathering skill that needs nothing in your hand — or grow your own on your island, where a plot keeps growing while you are logged off: food crops, and from Harvesting 15 the four flowers Wizardry brews its inks from.",mining:"Hold a pickaxe and click a rock. Every rock holds two to twelve ore and you work it until it is empty; a vein is slower per ore but never runs dry, which makes it the one to stand at. Now and then an ore comes with a gem: rubies from copper, tin and emerald, sapphires from diamond and dragonstone, topaz from onyx and starfall, opals from eclipse, nova and singularity. Each gem's page says where those rocks are.",woodcutting:"Hold an axe and click a tree. A tree is good for about 25 logs before it falls and an oak for about 50; a felled one is back in fifteen seconds. Logs burn into the charcoal every smelt needs.",smithing:"Burn logs into charcoal at the furnace — the only thing you can do at level 1 — then smelt ore and charcoal into bars, and hammer bars into gear at the anvil. The anvil also reforges what you already own.",thieving:"Pick pockets in the Thieves' Guild, south of the Yard. Nobody there fights back. Each room further in holds better marks, and what they carry either sells or goes to the anvil.",archery:"Fight with a bow. Every hit pays Archery the xp Combat would have had, a bow shoots from where you stand, and a loaded quiver keeps you shooting. Fletching makes the kit; Archery draws it.",magic:"Fight with a wand. A wand casts from five tiles; the spell page you load sets the damage and the element, and monsters weak to that element take far more.",wizardry:"Print spell pages and utility scrolls at the element altars around the world, from paper and ink. The Nexus, deep in the Wilderness, prints anything, twice.",fletching:"Cut logs into shafts and bows, fletch arrows from a shaft, a smithed head and a feather, and load them into a quiver. A bow in your hand is speed and reach; the arrow in it is the damage.",agility:"Run the obstacle course north of the Yard. Each obstacle pays, a finished lap pays far more, and what it buys you is movement speed everywhere else."};export{GUIDES,SKILL_EXTRA,SKILL_GUIDE,UPDATES,cropTable};
